(366714,40746,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Több mint negyven éve hűségesen ... ezt a klubot.'::text,'támogatja'::text,'támogatja'::text,'támogatja'::text,'Több mint negyven éve hűségesen támogatja ezt a klubot.'::text),
(366717,40747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Kamera ... die Reihe entlang, während alle Treue zeigten, kein Witz.'::text,'glitt'::text,'glitt'::text,'ist geglitten'::text,'Yo, die Kamera glitt die Reihe entlang, während alle Treue zeigten, kein Witz.'::text),
(366721,40747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, камера ... вздовж ряду, поки всі показували свою вірність, без жартів.'::text,'рухалася'::text,'пройшлася'::text,'пройшлася'::text,'Йо, камера рухалася вздовж ряду, поки всі показували свою вірність, без жартів.'::text),
(366720,40747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, la cámara ... a lo largo de la fila mientras todos mostraban su lealtad, en serio.'::text,'se estaba moviendo'::text,'se movió'::text,'se ha movido'::text,'Ey, la cámara se estaba moviendo a lo largo de la fila mientras todos mostraban su lealtad, en serio.'::text),
(366719,40747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, la caméra ... le long du rang pendant que tout le monde montrait sa loyauté, sans mentir.'::text,'glissait'::text,'a glissé'::text,'a glissé'::text,'Wesh, la caméra glissait le long du rang pendant que tout le monde montrait sa loyauté, sans mentir.'::text),
(366722,40747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, herkes sadakatini gösterirken kamera sıra boyunca ..., yemin ederim.'::text,'ilerliyordu'::text,'ilerledi'::text,'ilerlemiş'::text,'Kanka, herkes sadakatini gösterirken kamera sıra boyunca ilerliyordu, yemin ederim.'::text),
(366723,40747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a kamera ... a sor mentén, miközben mindenki a hűségét mutatta, komolyan.'::text,'haladt'::text,'végighaladt'::text,'elhaladt'::text,'Figyu, a kamera haladt a sor mentén, miközben mindenki a hűségét mutatta, komolyan.'::text),
(366726,40748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fan hat mit diesem Verein 30 Saisons ..., eine solide Kennzahl für Loyalität.'::text,'verbracht'::text,'verbracht'::text,'verbringt'::text,'Der Fan hat mit diesem Verein 30 Saisons verbracht, eine solide Kennzahl für Loyalität.'::text),
(366730,40748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уболівальник ... з цим клубом 30 сезонів — солідний показник лояльності.'::text,'провів'::text,'проводить уже'::text,'проводить'::text,'Уболівальник провів з цим клубом 30 сезонів — солідний показник лояльності.'::text),
(366729,40748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El aficionado ... 30 temporadas con este club, una sólida métrica de lealtad.'::text,'ha pasado'::text,'lleva pasando'::text,'pasa'::text,'El aficionado ha pasado 30 temporadas con este club, una sólida métrica de lealtad.'::text),
(366728,40748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le supporter ... 30 saisons avec ce club, un solide indicateur de loyauté.'::text,'a passé'::text,'passe depuis'::text,'passe'::text,'Le supporter a passé 30 saisons avec ce club, un solide indicateur de loyauté.'::text),
(366731,40748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taraftar bu kulüple 30 sezon ..., sağlam bir sadakat metriği.'::text,'geçirdi'::text,'geçiriyor'::text,'geçirir'::text,'Taraftar bu kulüple 30 sezon geçirdi, sağlam bir sadakat metriği.'::text),
(366732,40748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szurkoló 30 szezont ... ezzel a klubbal, ez stabil hűségmutató.'::text,'töltött el'::text,'tölt'::text,'tölt'::text,'A szurkoló 30 szezont töltött el ezzel a klubbal, ez stabil hűségmutató.'::text),
(366735,40749,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hielt seine Mütze an die Brust, weil er sie zuerst vom Kopf ... – das ist Treue.'::text,'genommen hatte'::text,'genommen hat'::text,'nimmt'::text,'Er hielt seine Mütze an die Brust, weil er sie zuerst vom Kopf genommen hatte – das ist Treue.'::text),
(366739,40749,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він тримав кепку біля грудей, бо спершу ... її з голови. Це і є вірність.'::text,'зняв'::text,'зняв'::text,'знімає'::text,'Він тримав кепку біля грудей, бо спершу зняв її з голови. Це і є вірність.'::text),
(366738,40749,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sostenía la gorra contra el pecho porque antes se la ... de la cabeza. Eso es lealtad.'::text,'había quitado'::text,'ha quitado'::text,'quita'::text,'Sostenía la gorra contra el pecho porque antes se la había quitado de la cabeza. Eso es lealtad.'::text),
(366737,40749,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il tenait sa casquette contre sa poitrine parce qu''il ... de sa tête avant. C''est ça, la loyauté.'::text,'l''avait retirée'::text,'l''a retirée'::text,'la retire'::text,'Il tenait sa casquette contre sa poitrine parce qu''il l''avait retirée de sa tête avant. C''est ça, la loyauté.'::text),
(366740,40749,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kasketi önce başından ... için göğsünde tutuyordu. Bu sadakattir.'::text,'çıkarmış olduğu'::text,'çıkardığı'::text,'çıkardığı'::text,'Kasketi önce başından çıkarmış olduğu için göğsünde tutuyordu. Bu sadakattir.'::text),
(366741,40749,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mellkasához tartotta a sapkáját, mert előbb ... a fejéről. Ez a hűség.'::text,'levette'::text,'levette'::text,'leveszi'::text,'A mellkasához tartotta a sapkáját, mert előbb levette a fejéről. Ez a hűség.'::text),
(366753,40751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Junge ... er nie ein Spiel, und seine Treue hat sich kein einziges Mal geändert!'::text,'verpasste'::text,'verpasste'::text,'war gewohnt zu verpassen'::text,'Als Junge verpasste er nie ein Spiel, und seine Treue hat sich kein einziges Mal geändert!'::text),
(366757,40751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопчиком він ... жодного матчу, і його вірність жодного разу не змінилася!'::text,'не пропускав'::text,'не пропускав'::text,'не звик пропускати'::text,'Хлопчиком він не пропускав жодного матчу, і його вірність жодного разу не змінилася!'::text),
(366756,40751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡De niño nunca ... un partido, y su lealtad no ha cambiado ni una vez!'::text,'se perdía'::text,'solía perderse'::text,'estaba acostumbrado a perderse'::text,'¡De niño nunca se perdía un partido, y su lealtad no ha cambiado ni una vez!'::text),
(366755,40751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Petit, il ne ... jamais un match, et sa loyauté n''a pas changé une seule fois !'::text,'ratait'::text,'ratait'::text,'était habitué à rater'::text,'Petit, il ne ratait jamais un match, et sa loyauté n''a pas changé une seule fois !'::text),
(366758,40751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken hiçbir maçı ... ve sadakati bir kez bile değişmedi!'::text,'kaçırmazdı'::text,'kaçırmazdı'::text,'kaçırmaya alışkındı'::text,'Çocukken hiçbir maçı kaçırmazdı ve sadakati bir kez bile değişmedi!'::text),
(366759,40751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekként soha egy meccset sem ..., és a hűsége egyszer sem változott!'::text,'hagyott ki'::text,'hagyott ki'::text,'volt hozzászokva kihagyni'::text,'Gyerekként soha egy meccset sem hagyott ki, és a hűsége egyszer sem változott!'::text),
(366762,40752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er weigert sich, seine Mütze während der Hymne ..., denn Treue ist alles!'::text,'aufzubehalten'::text,'Aufbehalten'::text,'aufbehalten'::text,'Er weigert sich, seine Mütze während der Hymne aufzubehalten, denn Treue ist alles!'::text),
(366766,40752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він відмовляється ... кепку на голові під час гімну, бо вірність — це все!'::text,'залишати'::text,'залишання'::text,'залишати'::text,'Він відмовляється залишати кепку на голові під час гімну, бо вірність — це все!'::text),
(366765,40752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se niega ... la gorra puesta durante el himno, porque la lealtad lo es todo!'::text,'a dejarse'::text,'dejándose'::text,'dejarse'::text,'¡Se niega a dejarse la gorra puesta durante el himno, porque la lealtad lo es todo!'::text),
(366764,40752,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il refuse ... sa casquette pendant l''hymne, parce que la loyauté, c''est tout !'::text,'de garder'::text,'gardant'::text,'garder'::text,'Il refuse de garder sa casquette pendant l''hymne, parce que la loyauté, c''est tout !'::text),
(366767,40752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Marş sırasında kasketini başında ... reddediyor, çünkü sadakat her şeydir!'::text,'tutmayı'::text,'tutmayı'::text,'tutmak'::text,'Marş sırasında kasketini başında tutmayı reddediyor, çünkü sadakat her şeydir!'::text),
(366768,40752,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hajlandó a fején ... a sapkáját a himnusz alatt, mert a hűség minden!'::text,'tartani'::text,'tartás'::text,'tart'::text,'Nem hajlandó a fején tartani a sapkáját a himnusz alatt, mert a hűség minden!'::text),
(366771,40753,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist für diese Fans alles, und sie werden sie nie vergessen!'::text,'Treue'::text,'Die Treue'::text,'Eine Treue'::text,'Treue ist für diese Fans alles, und sie werden sie nie vergessen!'::text),
(366775,40753,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... для цих фанатів — усе, і вони ніколи цього не забудуть!'::text,'Вірність'::text,'Вірність'::text,'Вірність'::text,'Вірність для цих фанатів — усе, і вони ніколи цього не забудуть!'::text),
(366774,40753,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... lo es todo para estos aficionados, y nunca lo olvidarán!'::text,'La lealtad'::text,'La lealtad'::text,'Una lealtad'::text,'¡La lealtad lo es todo para estos aficionados, y nunca lo olvidarán!'::text),
(366773,40753,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est tout pour ces fans, et ils ne l''oublieront jamais !'::text,'La loyauté'::text,'La loyauté'::text,'Une loyauté'::text,'La loyauté est tout pour ces fans, et ils ne l''oublieront jamais !'::text),
(366776,40753,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bu taraftarlar için her şeydir ve bunu asla unutmayacaklar!'::text,'Sadakat'::text,'Sadakat'::text,'Bir sadakat'::text,'Sadakat bu taraftarlar için her şeydir ve bunu asla unutmayacaklar!'::text),
(366777,40753,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mindent jelent ezeknek a szurkolóknak, és soha nem fogják elfelejteni!'::text,'A hűség'::text,'A hűség'::text,'Egy hűség'::text,'A hűség mindent jelent ezeknek a szurkolóknak, és soha nem fogják elfelejteni!'::text),
(366789,40755,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Hymne begann, hatte er seine Mütze als Zeichen der Treue schon ...'::text,'abgenommen'::text,'abgenommen'::text,'nimmt ab'::text,'Als die Hymne begann, hatte er seine Mütze als Zeichen der Treue schon abgenommen.'::text),
(366793,40755,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли почався гімн, він уже ... кепку на знак вірності.'::text,'зняв'::text,'зняв'::text,'знімає'::text,'Коли почався гімн, він уже зняв кепку на знак вірності.'::text),
(366792,40755,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando empezó el himno, ya se ... la gorra en señal de lealtad.'::text,'había quitado'::text,'ha quitado'::text,'quita'::text,'Cuando empezó el himno, ya se había quitado la gorra en señal de lealtad.'::text),
(366791,40755,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''hymne a commencé, il ... sa casquette en signe de loyauté.'::text,'avait déjà enlevé'::text,'a déjà enlevé'::text,'enlève'::text,'Quand l''hymne a commencé, il avait déjà enlevé sa casquette en signe de loyauté.'::text),
(366794,40755,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Marş başladığında kasketini sadakat göstergesi olarak çoktan ...'::text,'çıkarmıştı'::text,'çıkardı'::text,'çıkarıyor'::text,'Marş başladığında kasketini sadakat göstergesi olarak çoktan çıkarmıştı.'::text),
(366795,40755,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a himnusz elkezdődött, a hűsége jeléül már ... a sapkáját.'::text,'levette'::text,'levette'::text,'leveszi'::text,'Mire a himnusz elkezdődött, a hűsége jeléül már levette a sapkáját.'::text),
(378246,42028,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er verspricht, dass er mit der Bahn zum Termin um 9 Uhr ...'::text,'fahren wird'::text,'fahren wird'::text,'fährt'::text,'Er verspricht, dass er mit der Bahn zum Termin um 9 Uhr fahren wird.'::text),
(378250,42028,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обіцяє, що ... на зустріч о 9:00 залізницею.'::text,'поїде'::text,'їхатиме'::text,'їде'::text,'Він обіцяє, що поїде на зустріч о 9:00 залізницею.'::text),
(378249,42028,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Promete que ... en tren a la reunión de las 9:00.'::text,'viajará'::text,'estará viajando'::text,'está viajando'::text,'Promete que viajará en tren a la reunión de las 9:00.'::text),
(378248,42028,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il promet qu''il ... en train à la réunion de 9 h.'::text,'se rendra'::text,'sera en route'::text,'se rend'::text,'Il promet qu''il se rendra en train à la réunion de 9 h.'::text),
(378251,42028,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 9''daki toplantıya trenle ... söz veriyor.'::text,'gideceğine'::text,'gidiyor olacağına'::text,'gittiğine'::text,'Saat 9''daki toplantıya trenle gideceğine söz veriyor.'::text),
(378252,42028,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígéri, hogy vonattal ... a reggel 9-es megbeszélésre.'::text,'fog menni'::text,'utazni fog'::text,'utazik'::text,'Megígéri, hogy vonattal fog menni a reggel 9-es megbeszélésre.'::text),
(378255,42029,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Person mit der Bahn ..., sitzt sie in einem Zug, weil Züge auf Schienen fahren.'::text,'fährt'::text,'fuhr'::text,'fahren wird'::text,'Wenn eine Person mit der Bahn fährt, sitzt sie in einem Zug, weil Züge auf Schienen fahren.'::text),
(378259,42029,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо людина ... залізницею, вона сидить у поїзді, бо поїзди їздять рейками.'::text,'подорожує'::text,'подорожувала'::text,'подорожуватиме'::text,'Якщо людина подорожує залізницею, вона сидить у поїзді, бо поїзди їздять рейками.'::text),
(378258,42029,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una persona ... en tren, va sentada en un tren, porque los trenes van sobre raíles.'::text,'viaja'::text,'viajó'::text,'viajará'::text,'Si una persona viaja en tren, va sentada en un tren, porque los trenes van sobre raíles.'::text),
(378257,42029,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une personne ... en train, elle est assise dans un train, parce que les trains roulent sur des rails.'::text,'voyage'::text,'voyageait'::text,'voyagera'::text,'Si une personne voyage en train, elle est assise dans un train, parce que les trains roulent sur des rails.'::text),
(378260,42029,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kişi demiryoluyla ..., trende oturur, çünkü trenler raylarda gider.'::text,'seyahat ederse'::text,'seyahat ettiyse'::text,'seyahat edecekse'::text,'Bir kişi demiryoluyla seyahat ederse, trende oturur, çünkü trenler raylarda gider.'::text),
(378261,42029,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha valaki vasúton ..., vonaton ül, mert a vonatok síneken járnak.'::text,'utazik'::text,'utazott'::text,'utazni fog'::text,'Ha valaki vasúton utazik, vonaton ül, mert a vonatok síneken járnak.'::text),
(378264,42030,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Zug pünktlich ankommt, ... das Subjekt seine Bahnreise annähernd planmäßig.'::text,'beginnt'::text,'würde beginnen'::text,'begann'::text,'Wenn der Zug pünktlich ankommt, beginnt das Subjekt seine Bahnreise annähernd planmäßig.'::text),
(378268,42030,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо поїзд прибуде вчасно, суб''єкт ... свою подорож залізницею приблизно за планом.'::text,'почне'::text,'почав би'::text,'почав'::text,'Якщо поїзд прибуде вчасно, суб''єкт почне свою подорож залізницею приблизно за планом.'::text),
(378267,42030,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el tren llega a tiempo, el sujeto ... su viaje en tren aproximadamente según lo previsto.'::text,'comenzará'::text,'comenzaría'::text,'comenzó'::text,'Si el tren llega a tiempo, el sujeto comenzará su viaje en tren aproximadamente según lo previsto.'::text),
(378266,42030,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le train arrive à l''heure, le sujet ... son voyage en train à peu près comme prévu.'::text,'commencera'::text,'commencerait'::text,'a commencé'::text,'Si le train arrive à l''heure, le sujet commencera son voyage en train à peu près comme prévu.'::text),
(378269,42030,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tren zamanında gelirse, özne tren yolculuğuna yaklaşık olarak planlandığı gibi ...'::text,'başlayacak'::text,'başlardı'::text,'başladı'::text,'Tren zamanında gelirse, özne tren yolculuğuna yaklaşık olarak planlandığı gibi başlayacak.'::text),
(378270,42030,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a vonat időben érkezik, az alany megközelítőleg a terv szerint ... vasúti útját.'::text,'kezdi meg'::text,'kezdené meg'::text,'kezdte meg'::text,'Ha a vonat időben érkezik, az alany megközelítőleg a terv szerint kezdi meg vasúti útját.'::text),
(378273,42031,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn ich mit deiner Energie Bahn fahren würde, würde ich jeden Weg zur Arbeit am Morgen ...'::text,'genießen'::text,'genießen'::text,'genoss'::text,'Ehrlich, wenn ich mit deiner Energie Bahn fahren würde, würde ich jeden Weg zur Arbeit am Morgen genießen.'::text),
(378277,42031,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби я їздив залізницею з твоєю енергією, я ... кожною ранковою поїздкою на роботу.'::text,'насолоджувався б'::text,'насолоджуватимуся'::text,'насолоджувався'::text,'Чесно, якби я їздив залізницею з твоєю енергією, я насолоджувався б кожною ранковою поїздкою на роботу.'::text),
(378276,42031,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si viajara en tren con tu energía, ... cada trayecto de la mañana.'::text,'disfrutaría'::text,'disfrutaré'::text,'disfruté'::text,'Sinceramente, si viajara en tren con tu energía, disfrutaría cada trayecto de la mañana.'::text),
(378275,42031,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si je voyageais en train avec ton énergie, je ... chaque trajet du matin.'::text,'savourerais'::text,'savourerai'::text,'savourais'::text,'Franchement, si je voyageais en train avec ton énergie, je savourerais chaque trajet du matin.'::text),
(378278,42031,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, senin enerjinle trenle yolculuk etseydim her sabah işe gidişin ...'::text,'tadını çıkarırdım'::text,'tadını çıkaracağım'::text,'tadını çıkardım'::text,'Açıkçası, senin enerjinle trenle yolculuk etseydim her sabah işe gidişin tadını çıkarırdım.'::text),
(378279,42031,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha a te energiáddal utaznék vasúton, ... minden reggeli ingázást.'::text,'élvezném'::text,'élvezni fogom'::text,'élveztem'::text,'Őszintén, ha a te energiáddal utaznék vasúton, élvezném minden reggeli ingázást.'::text),
(378282,42032,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Croissant ... am Bahnhof gekauft, bevor der Zug ankam.'::text,'wurde'::text,'hat'::text,'wird'::text,'Das Croissant wurde am Bahnhof gekauft, bevor der Zug ankam.'::text),
(378286,42032,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Круасан ... на залізничному вокзалі, перш ніж прибув поїзд.'::text,'був куплений'::text,'купив'::text,'купується'::text,'Круасан був куплений на залізничному вокзалі, перш ніж прибув поїзд.'::text),
(378285,42032,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cruasán ... en la estación antes de que llegara el tren.'::text,'fue comprado'::text,'compró'::text,'es comprado'::text,'El cruasán fue comprado en la estación antes de que llegara el tren.'::text),
(378284,42032,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le croissant ... à la gare avant l''arrivée du train.'::text,'a été acheté'::text,'a acheté'::text,'est acheté'::text,'Le croissant a été acheté à la gare avant l''arrivée du train.'::text),
(378287,42032,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kruvasan tren gelmeden önce tren istasyonunda ...'::text,'satın alındı'::text,'satın aldı'::text,'satın alınır'::text,'Kruvasan tren gelmeden önce tren istasyonunda satın alındı.'::text),
(378288,42032,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A croissant-t ... a vasútállomáson, mielőtt a vonat megérkezett.'::text,'vették meg'::text,'vette meg'::text,'veszik meg'::text,'A croissant-t vették meg a vasútállomáson, mielőtt a vonat megérkezett.'::text),
(378291,42033,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tausende Pendler ... jeden Tag mit der Bahn durch diesen belebten Bahnhof.'::text,'fahren'::text,'werden gefahren'::text,'fahrend'::text,'Tausende Pendler fahren jeden Tag mit der Bahn durch diesen belebten Bahnhof.'::text),
(378295,42033,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тисячі пасажирів щодня ... залізницею через цей жвавий вокзал.'::text,'їздять'::text,'перевозяться'::text,'їдучи'::text,'Тисячі пасажирів щодня їздять залізницею через цей жвавий вокзал.'::text),
(378294,42033,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miles de viajeros ... en tren por esta concurrida estación cada día.'::text,'pasan'::text,'son transportados'::text,'pasando'::text,'Miles de viajeros pasan en tren por esta concurrida estación cada día.'::text),
(378293,42033,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des milliers de navetteurs ... en train par cette gare animée chaque jour.'::text,'passent'::text,'sont transportés'::text,'passant'::text,'Des milliers de navetteurs passent en train par cette gare animée chaque jour.'::text),
(378296,42033,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her gün binlerce banliyö yolcusu bu kalabalık istasyondan trenle ...'::text,'geçiyor'::text,'geçiriliyor'::text,'geçerek'::text,'Her gün binlerce banliyö yolcusu bu kalabalık istasyondan trenle geçiyor.'::text),
(378297,42033,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ingázók ezrei ... vonattal naponta ezen a forgalmas állomáson keresztül.'::text,'utaznak'::text,'szállítják őket'::text,'utazva'::text,'Ingázók ezrei utaznak vonattal naponta ezen a forgalmas állomáson keresztül.'::text),
(378300,42034,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Abfahrtstafeln zeigen keine Verspätungen, also ... das Bahnfahren heute ja makellos sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Die Abfahrtstafeln zeigen keine Verspätungen, also muss das Bahnfahren heute ja makellos sein.'::text),
(378304,42034,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Табло відправлення не показують жодних затримок, тож подорож залізницею сьогодні ... бути бездоганною.'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Табло відправлення не показують жодних затримок, тож подорож залізницею сьогодні мусить бути бездоганною.'::text),
(378303,42034,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los paneles de salidas no muestran retrasos, así que viajar en tren hoy ... ser perfecto.'::text,'tiene que'::text,'no puede'::text,'no debe'::text,'Los paneles de salidas no muestran retrasos, así que viajar en tren hoy tiene que ser perfecto.'::text),
(378302,42034,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les panneaux des départs n''affichent aucun retard, donc le voyage en train ... être parfait aujourd''hui.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Les panneaux des départs n''affichent aucun retard, donc le voyage en train doit être parfait aujourd''hui.'::text),
(378305,42034,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalkış panolarında hiç rötar görünmüyor, yani bugün tren yolculuğu kusursuz ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Kalkış panolarında hiç rötar görünmüyor, yani bugün tren yolculuğu kusursuz olmalı.'::text),
(378306,42034,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az indulási táblák nem mutatnak késést, szóval a vasúti utazásnak ma tökéletesnek ...'::text,'kell lennie'::text,'nem lehet'::text,'nem szabad lennie'::text,'Az indulási táblák nem mutatnak késést, szóval a vasúti utazásnak ma tökéletesnek kell lennie.'::text),
(378309,42035,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Wahl: Der Bahnhof, ... er sein Croissant gekauft hat, ist der belebteste im ganzen Bahnnetz.'::text,'wo'::text,'den'::text,'dessen'::text,'Tolle Wahl: Der Bahnhof, wo er sein Croissant gekauft hat, ist der belebteste im ganzen Bahnnetz.'::text),
(378313,42035,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий вибір: вокзал, ... він купив свій круасан, — найжвавіший у всій залізничній мережі.'::text,'де'::text,'який'::text,'чий'::text,'Чудовий вибір: вокзал, де він купив свій круасан, — найжвавіший у всій залізничній мережі.'::text),
(378312,42035,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran elección: la estación ... compró su cruasán es la más concurrida de la red ferroviaria.'::text,'donde'::text,'que'::text,'cuya'::text,'Gran elección: la estación donde compró su cruasán es la más concurrida de la red ferroviaria.'::text),
(378311,42035,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Excellent choix : la gare ... il a acheté son croissant est la plus fréquentée du réseau ferroviaire.'::text,'où'::text,'que'::text,'dont'::text,'Excellent choix : la gare où il a acheté son croissant est la plus fréquentée du réseau ferroviaire.'::text),
(378314,42035,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika seçim: kruvasanını ... istasyon, demiryolu ağının en kalabalık istasyonu.'::text,'aldığı'::text,'hangi'::text,'kimin'::text,'Harika seçim: kruvasanını aldığı istasyon, demiryolu ağının en kalabalık istasyonu.'::text),
(378315,42035,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek választás: az állomás, ... a croissant-ját vette, a vasúthálózat legforgalmasabbja.'::text,'ahol'::text,'amely'::text,'akinek'::text,'Remek választás: az állomás, ahol a croissant-ját vette, a vasúthálózat legforgalmasabbja.'::text),
(378318,42036,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er erzählte seinen Followern, dass er den ganzen Tag mit Bahnfahren ...'::text,'verbracht hatte'::text,'verbracht hat'::text,'verbringt'::text,'Er erzählte seinen Followern, dass er den ganzen Tag mit Bahnfahren verbracht hatte.'::text),
(378322,42036,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він розповів своїм підписникам, що ... цілий день у подорожі залізницею.'::text,'провів'::text,'провів'::text,'проводить'::text,'Він розповів своїм підписникам, що провів цілий день у подорожі залізницею.'::text),
(378321,42036,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les contó a sus seguidores que ... todo el día viajando en tren.'::text,'había pasado'::text,'ha pasado'::text,'pasa'::text,'Les contó a sus seguidores que había pasado todo el día viajando en tren.'::text),
(378320,42036,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit à ses abonnés qu''il ... toute la journée à voyager en train.'::text,'avait passé'::text,'a passé'::text,'passe'::text,'Il a dit à ses abonnés qu''il avait passé toute la journée à voyager en train.'::text),
(378323,42036,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takipçilerine bütün günü trenle seyahat ederek ... söyledi.'::text,'geçirmiş olduğunu'::text,'geçirdiğini'::text,'geçirdiğini'::text,'Takipçilerine bütün günü trenle seyahat ederek geçirmiş olduğunu söyledi.'::text),
(378324,42036,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta a követőinek, hogy az egész napot vonatozással ...'::text,'töltötte'::text,'töltötte'::text,'tölti'::text,'Azt mondta a követőinek, hogy az egész napot vonatozással töltötte.'::text),
(378327,42037,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... ein Auto, aber jetzt fährt er überall mit der Bahn hin.'::text,'hatte früher'::text,'hatte'::text,'ist gewohnt zu haben'::text,'Er hatte früher ein Auto, aber jetzt fährt er überall mit der Bahn hin.'::text),
(378331,42037,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... машину, а тепер усюди їздить залізницею.'::text,'колись мав'::text,'мав'::text,'звик мати'::text,'Він колись мав машину, а тепер усюди їздить залізницею.'::text),
(378330,42037,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tener coche, pero ahora viaja a todas partes en tren.'::text,'Solía'::text,'Solía'::text,'Está acostumbrado a'::text,'Solía tener coche, pero ahora viaja a todas partes en tren.'::text),
(378329,42037,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ... une voiture, mais maintenant il voyage partout en train.'::text,'avait'::text,'avait'::text,'a l''habitude d''avoir'::text,'Avant, il avait une voiture, mais maintenant il voyage partout en train.'::text),
(378332,42037,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden bir arabası ..., ama şimdi her yere trenle gidiyor.'::text,'vardı'::text,'olurdu'::text,'olmasına alışkın'::text,'Eskiden bir arabası vardı, ama şimdi her yere trenle gidiyor.'::text),
(378333,42037,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... autója, de most mindenhová vonattal utazik.'::text,'volt'::text,'volt'::text,'hozzá van szokva, hogy legyen'::text,'Régen volt autója, de most mindenhová vonattal utazik.'::text),
(342345,38039,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber du ... das Buslenkrad so geschmeidig, als du angefangen hast zu grinsen. Beeindruckend.'::text,'steuertest'::text,'steuertest'::text,'hast gesteuert'::text,'Okay, aber du steuertest das Buslenkrad so geschmeidig, als du angefangen hast zu grinsen. Beeindruckend.'::text),
(342349,38039,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, але ти так плавно ... кермо автобуса, коли почала усміхатися. Вражає.'::text,'контролювала'::text,'проконтролювала'::text,'проконтролювала'::text,'Окей, але ти так плавно контролювала кермо автобуса, коли почала усміхатися. Вражає.'::text),
(342348,38039,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero ... el volante del bus con tanta suavidad cuando empezaste a sonreír. Impresionante.'::text,'estabas controlando'::text,'controlaste'::text,'has controlado'::text,'Vale, pero estabas controlando el volante del bus con tanta suavidad cuando empezaste a sonreír. Impresionante.'::text),
(342347,38039,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok mais tu ... le volant du bus tellement en douceur quand tu as commencé à sourire. Impressionnant.'::text,'maîtrisais'::text,'as maîtrisé'::text,'as maîtrisé'::text,'Ok mais tu maîtrisais le volant du bus tellement en douceur quand tu as commencé à sourire. Impressionnant.'::text),
(342350,38039,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam ama sırıtmaya başladığında otobüs direksiyonunu o kadar yumuşak ..., etkileyici.'::text,'kontrol ediyordun'::text,'kontrol ettin'::text,'kontrol ettin'::text,'Tamam ama sırıtmaya başladığında otobüs direksiyonunu o kadar yumuşak kontrol ediyordun, etkileyici.'::text),
(342351,38039,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de olyan simán ... a busz kormányát, amikor vigyorogni kezdtél. Lenyűgöző.'::text,'irányítottad'::text,'irányítottad'::text,'irányítottad'::text,'Oké, de olyan simán irányítottad a busz kormányát, amikor vigyorogni kezdtél. Lenyűgöző.'::text),
(342354,38040,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... das Auto jetzt seit fünf Minuten, und ehrlich, Respekt.'::text,'steuerst'::text,'steuerst'::text,'steuerst'::text,'Du steuerst das Auto jetzt seit fünf Minuten, und ehrlich, Respekt.'::text),
(342358,38040,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... автомобілем уже п''ять хвилин, і чесно, респект.'::text,'керуєш'::text,'керуєш'::text,'керуєш'::text,'Ти керуєш автомобілем уже п''ять хвилин, і чесно, респект.'::text),
(342357,38040,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el coche desde hace cinco minutos y, sinceramente, respeto.'::text,'Controlas'::text,'Estás controlando'::text,'Controlas'::text,'Controlas el coche desde hace cinco minutos y, sinceramente, respeto.'::text),
(342356,38040,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... la voiture depuis cinq minutes maintenant, et franchement, respect.'::text,'contrôles'::text,'es en train de contrôler'::text,'contrôles'::text,'Tu contrôles la voiture depuis cinq minutes maintenant, et franchement, respect.'::text),
(342359,38040,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beş dakikadır arabayı ... ve açıkçası, saygı.'::text,'kontrol ediyorsun'::text,'kontrol ediyorsun'::text,'kontrol edersin'::text,'Beş dakikadır arabayı kontrol ediyorsun ve açıkçası, saygı.'::text),
(342360,38040,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már öt perce ... az autót, és őszintén, respekt.'::text,'irányítod'::text,'irányítod'::text,'irányítod'::text,'Már öt perce irányítod az autót, és őszintén, respekt.'::text),
(342363,38041,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während du dieses riesige Buslenkrad ..., hast du gegrinst, und ehrlich, das war ikonisch.'::text,'steuertest'::text,'steuertest'::text,'gesteuert hast'::text,'Während du dieses riesige Buslenkrad steuertest, hast du gegrinst, und ehrlich, das war ikonisch.'::text),
(342367,38041,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ти ... тим величезним кермом автобуса, ти усміхалася, і чесно, це було культово.'::text,'керувала'::text,'скерувала'::text,'скерувала'::text,'Поки ти керувала тим величезним кермом автобуса, ти усміхалася, і чесно, це було культово.'::text),
(342366,38041,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... ese volante enorme del bus, sonreíste y, sinceramente, fue icónico.'::text,'controlabas'::text,'controlaste'::text,'has controlado'::text,'Mientras controlabas ese volante enorme del bus, sonreíste y, sinceramente, fue icónico.'::text),
(342365,38041,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que tu ... cet énorme volant de bus, tu as souri, et franchement, c''était iconique.'::text,'maîtrisais'::text,'as maîtrisé'::text,'as maîtrisé'::text,'Pendant que tu maîtrisais cet énorme volant de bus, tu as souri, et franchement, c''était iconique.'::text),
(342368,38041,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kocaman otobüs direksiyonunu ... sırıttın ve açıkçası efsaneydi.'::text,'kontrol ederken'::text,'kontrol ettiğinde'::text,'kontrol etmişken'::text,'O kocaman otobüs direksiyonunu kontrol ederken sırıttın ve açıkçası efsaneydi.'::text),
(342369,38041,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben azt a hatalmas buszkormányt ..., vigyorogtál, és őszintén, ikonikus volt.'::text,'irányítottad'::text,'irányítottad'::text,'irányítottad'::text,'Miközben azt a hatalmas buszkormányt irányítottad, vigyorogtál, és őszintén, ikonikus volt.'::text),
(342390,38044,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Auto war geparkt, also ... sie es nicht auf der Straße gesteuert haben. Super Arbeit.'::text,'kann'::text,'muss'::text,'sollte'::text,'Das Auto war geparkt, also kann sie es nicht auf der Straße gesteuert haben. Super Arbeit.'::text),
(342394,38044,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Машина була припаркована, тож вона ... нею на дорозі. Чудова робота.'::text,'не могла керувати'::text,'точно керувала'::text,'не мала керувати'::text,'Машина була припаркована, тож вона не могла керувати нею на дорозі. Чудова робота.'::text),
(342393,38044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche estaba aparcado, así que ... en la carretera. Buen trabajo.'::text,'no puede haberlo controlado'::text,'debe de haberlo controlado'::text,'no debería haberlo controlado'::text,'El coche estaba aparcado, así que no puede haberlo controlado en la carretera. Buen trabajo.'::text),
(342392,38044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture était garée, donc elle ... sur la route. Bravo.'::text,'ne peut pas l''avoir conduite'::text,'a dû la conduire'::text,'n''aurait pas dû la conduire'::text,'La voiture était garée, donc elle ne peut pas l''avoir conduite sur la route. Bravo.'::text),
(342395,38044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba park hâlindeydi, yani onu yolda ..., harika iş.'::text,'kullanmış olamaz'::text,'kullanmış olmalı'::text,'kullanmamalıydı'::text,'Araba park hâlindeydi, yani onu yolda kullanmış olamaz, harika iş.'::text),
(342396,38044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autó parkolt, szóval ... az úton. Szép munka.'::text,'nem irányíthatta'::text,'biztosan irányította'::text,'nem kellett volna irányítania'::text,'Az autó parkolt, szóval nem irányíthatta az úton. Szép munka.'::text),
(342399,38045,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ließ den Fahrlehrer den Bus für sie ..., sonst wäre das Depot zerstört worden!'::text,'steuern'::text,'zu steuern'::text,'gesteuert'::text,'Sie ließ den Fahrlehrer den Bus für sie steuern, sonst wäre das Depot zerstört worden!'::text),
(342403,38045,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона попросила інструктора ... автобусом замість неї, інакше депо було б знищене!'::text,'керувати'::text,'керувати'::text,'керував'::text,'Вона попросила інструктора керувати автобусом замість неї, інакше депо було б знищене!'::text),
(342402,38045,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Hizo que el instructor ... el autobús por ella, o la cochera quedaría destruida!'::text,'manejara'::text,'manejar'::text,'manejado'::text,'¡Hizo que el instructor manejara el autobús por ella, o la cochera quedaría destruida!'::text),
(342401,38045,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a fait ... le bus à l''instructeur à sa place, sinon le dépôt serait détruit !'::text,'conduire'::text,'de conduire'::text,'conduit'::text,'Elle a fait conduire le bus à l''instructeur à sa place, sinon le dépôt serait détruit !'::text),
(342404,38045,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Otobüsü onun yerine eğitmene ..., yoksa depo yerle bir olacaktı!'::text,'kullandırdı'::text,'kullanmasını sağladı'::text,'kullanılmış'::text,'Otobüsü onun yerine eğitmene kullandırdı, yoksa depo yerle bir olacaktı!'::text),
(342405,38045,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A buszt az oktatóval ... maga helyett, különben a remíz megsemmisült volna!'::text,'vezettette'::text,'vezettetni'::text,'vezetett'::text,'A buszt az oktatóval vezettette maga helyett, különben a remíz megsemmisült volna!'::text),
(342408,38046,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünschte, sie ... einen Bus so leicht steuern wie ein Auto.'::text,'könnte'::text,'kann'::text,'wird'::text,'Sie wünschte, sie könnte einen Bus so leicht steuern wie ein Auto.'::text),
(342412,38046,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона хотіла б ... автобусом так само легко, як автомобілем.'::text,'вміти керувати'::text,'могти керувати'::text,'керуватиме'::text,'Вона хотіла б вміти керувати автобусом так само легко, як автомобілем.'::text),
(342411,38046,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desearía ... un autobús tan fácilmente como un coche.'::text,'poder controlar'::text,'puede controlar'::text,'controlará'::text,'Desearía poder controlar un autobús tan fácilmente como un coche.'::text),
(342410,38046,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait ... un bus aussi facilement qu''une voiture.'::text,'pouvoir conduire'::text,'peut conduire'::text,'conduira'::text,'Elle aimerait pouvoir conduire un bus aussi facilement qu''une voiture.'::text),
(342413,38046,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke bir otobüsü de araba kadar kolay ... diye düşünüyor.'::text,'kontrol edebilse'::text,'kontrol edebilir'::text,'kontrol edecek'::text,'Keşke bir otobüsü de araba kadar kolay kontrol edebilse diye düşünüyor.'::text),
(342414,38046,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt szeretné, ha olyan könnyen ... egy buszt, mint egy autót.'::text,'tudna irányítani'::text,'tud irányítani'::text,'fog irányítani'::text,'Azt szeretné, ha olyan könnyen tudna irányítani egy buszt, mint egy autót.'::text),
(342417,38047,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bus, ... Lenkrad riesig ist, ist schwer zu steuern.'::text,'dessen'::text,'der'::text,'den'::text,'Der Bus, dessen Lenkrad riesig ist, ist schwer zu steuern.'::text),
(342421,38047,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Автобус, ... кермо величезне, важко контролювати.'::text,'чиє'::text,'який'::text,'що'::text,'Автобус, чиє кермо величезне, важко контролювати.'::text),
(342420,38047,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El autobús, ... volante es enorme, es difícil de controlar.'::text,'cuyo'::text,'que'::text,'el cual'::text,'El autobús, cuyo volante es enorme, es difícil de controlar.'::text),
(342419,38047,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bus, ... le volant est énorme, est difficile à conduire.'::text,'dont'::text,'qui'::text,'que'::text,'Le bus, dont le volant est énorme, est difficile à conduire.'::text),
(342422,38047,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Direksiyonu kocaman ... otobüsü kontrol etmek zor.'::text,'olan'::text,'hangi'::text,'ki'::text,'Direksiyonu kocaman olan otobüsü kontrol etmek zor.'::text),
(342423,38047,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A busz, ... kormánya hatalmas, nehezen irányítható.'::text,'amelynek'::text,'amely'::text,'ami'::text,'A busz, amelynek kormánya hatalmas, nehezen irányítható.'::text),
(342426,38048,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... das Lenkrad riesig ist, steuert sie den Bus mit einem Lächeln.'::text,'Obwohl'::text,'Trotz'::text,'Außer wenn'::text,'Obwohl das Lenkrad riesig ist, steuert sie den Bus mit einem Lächeln.'::text),
(342430,38048,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... кермо величезне, вона керує автобусом з усмішкою.'::text,'Хоча'::text,'Попри'::text,'Якщо не'::text,'Хоча кермо величезне, вона керує автобусом з усмішкою.'::text),
(342429,38048,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el volante es enorme, maneja el autobús con una sonrisa.'::text,'Aunque'::text,'A pesar de'::text,'A menos que'::text,'Aunque el volante es enorme, maneja el autobús con una sonrisa.'::text),
(342428,38048,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le volant soit énorme, elle conduit le bus avec le sourire.'::text,'Bien que'::text,'Malgré'::text,'À moins que'::text,'Bien que le volant soit énorme, elle conduit le bus avec le sourire.'::text),
(342431,38048,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Direksiyon kocaman ..., otobüsü gülümseyerek kontrol ediyor.'::text,'olmasına rağmen'::text,'rağmen'::text,'olmadıkça'::text,'Direksiyon kocaman olmasına rağmen, otobüsü gülümseyerek kontrol ediyor.'::text),
(342432,38048,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hatalmas a kormány, mosolyogva irányítja a buszt.'::text,'Bár'::text,'Annak ellenére'::text,'Hacsak nem'::text,'Bár hatalmas a kormány, mosolyogva irányítja a buszt.'::text),
(342435,38049,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Ausbildung wird das Subjekt einen Stadtbus etwa 20 Stunden lang ...'::text,'gesteuert haben'::text,'steuern'::text,'steuert'::text,'Bis zum Ende der Ausbildung wird das Subjekt einen Stadtbus etwa 20 Stunden lang gesteuert haben.'::text),
(342439,38049,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця навчання суб''єкт ... міським автобусом приблизно 20 годин.'::text,'керуватиме'::text,'керуватиме'::text,'керує'::text,'До кінця навчання суб''єкт керуватиме міським автобусом приблизно 20 годин.'::text),
(342438,38049,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final de la formación, el sujeto ... un autobús urbano durante aproximadamente 20 horas.'::text,'habrá manejado'::text,'manejará'::text,'maneja'::text,'Al final de la formación, el sujeto habrá manejado un autobús urbano durante aproximadamente 20 horas.'::text),
(342437,38049,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la formation, le sujet ... un bus urbain pendant environ 20 heures.'::text,'aura conduit'::text,'conduira'::text,'conduit'::text,'D''ici la fin de la formation, le sujet aura conduit un bus urbain pendant environ 20 heures.'::text),
(342440,38049,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğitimin sonunda özne yaklaşık 20 saat boyunca bir şehir otobüsü ...'::text,'kullanmış olacak'::text,'kullanacak'::text,'kullanıyor'::text,'Eğitimin sonunda özne yaklaşık 20 saat boyunca bir şehir otobüsü kullanmış olacak.'::text),
(342441,38049,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A képzés végére az alany megközelítőleg 20 órán át ... városi buszt.'::text,'irányított'::text,'irányítani fog'::text,'irányít'::text,'A képzés végére az alany megközelítőleg 20 órán át irányított városi buszt.'::text),
(370425,41159,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Mann die Schraube anzog, hatte der Junge das Brett schon an das Kart ...'::text,'genagelt'::text,'genagelt'::text,'nagelt'::text,'Als der Mann die Schraube anzog, hatte der Junge das Brett schon an das Kart genagelt.'::text),
(370429,41159,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки чоловік затягнув болт, хлопець уже ... дошку до карта.'::text,'прибив'::text,'прибив'::text,'прибиває'::text,'Поки чоловік затягнув болт, хлопець уже прибив дошку до карта.'::text),
(370428,41159,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el hombre apretó el perno, el chico ya ... la tabla al kart.'::text,'había clavado'::text,'ha clavado'::text,'clava'::text,'Para cuando el hombre apretó el perno, el chico ya había clavado la tabla al kart.'::text),
(370427,41159,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''homme a serré le boulon, le garçon ... la planche au kart.'::text,'avait cloué'::text,'a cloué'::text,'cloue'::text,'Quand l''homme a serré le boulon, le garçon avait cloué la planche au kart.'::text),
(370430,41159,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam cıvatayı sıktığında çocuk tahtayı karta çoktan ...'::text,'çakmıştı'::text,'çaktı'::text,'çakıyor'::text,'Adam cıvatayı sıktığında çocuk tahtayı karta çoktan çakmıştı.'::text),
(370431,41159,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a férfi meghúzta a csavart, a fiú már ... a deszkát a gokarthoz.'::text,'odaszögelte'::text,'odaszögelte'::text,'odaszögeli'::text,'Mire a férfi meghúzta a csavart, a fiú már odaszögelte a deszkát a gokarthoz.'::text),
(397281,44143,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, dass das Mädchen zwei Cupcakes ..., bevor das Frosting überhaupt ihre Zunge berührt hat.'::text,'gegessen hatte'::text,'gegessen hat'::text,'isst'::text,'Hör mal, ich hab gehört, dass das Mädchen zwei Cupcakes gegessen hatte, bevor das Frosting überhaupt ihre Zunge berührt hat.'::text),
(397285,44143,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що дівчинка ... два капкейки ще до того, як глазур узагалі торкнулася її язика.'::text,'з''їла'::text,'з''їла'::text,'їсть'::text,'Слухай, я чула, що дівчинка з''їла два капкейки ще до того, як глазур узагалі торкнулася її язика.'::text),
(397284,44143,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que la niña ... dos cupcakes antes de que el glaseado le tocara siquiera la lengua.'::text,'se había comido'::text,'se ha comido'::text,'se come'::text,'Oye, me han dicho que la niña se había comido dos cupcakes antes de que el glaseado le tocara siquiera la lengua.'::text),
(397283,44143,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que la petite ... deux cupcakes avant même que le glaçage touche sa langue.'::text,'avait mangé'::text,'a mangé'::text,'mange'::text,'Écoute, j''ai entendu dire que la petite avait mangé deux cupcakes avant même que le glaçage touche sa langue.'::text),
(397286,44143,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre kız, krema diline değmeden önce iki cupcake ...'::text,'yemişti'::text,'yedi'::text,'yiyor'::text,'Dinle, duyduğuma göre kız, krema diline değmeden önce iki cupcake yemişti.'::text),
(397287,44143,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a kislány két cupcake-et ..., mielőtt a máz egyáltalán a nyelvéhez ért.'::text,'megevett'::text,'megevett'::text,'eszik'::text,'Figyelj, azt hallottam, hogy a kislány két cupcake-et megevett, mielőtt a máz egyáltalán a nyelvéhez ért.'::text),
(397290,44144,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie noch mal die Zunge rausstreckt, ... sie mehr Frosting.'::text,'bekommt'::text,'würde bekommen'::text,'bekam'::text,'Wenn sie noch mal die Zunge rausstreckt, bekommt sie mehr Frosting.'::text),
(397294,44144,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона знову висуне язик, то ... ще глазурі.'::text,'отримає'::text,'отримала б'::text,'отримала'::text,'Якщо вона знову висуне язик, то отримає ще глазурі.'::text),
(397293,44144,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si vuelve a sacar la lengua, ... más glaseado.'::text,'recibirá'::text,'recibiría'::text,'recibió'::text,'Si vuelve a sacar la lengua, recibirá más glaseado.'::text),
(397292,44144,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle tire encore la langue, elle ... plus de glaçage.'::text,'aura'::text,'aurait'::text,'a eu'::text,'Si elle tire encore la langue, elle aura plus de glaçage.'::text),
(397295,44144,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dilini yine çıkarırsa daha fazla krema ...'::text,'alacak'::text,'alırdı'::text,'aldı'::text,'Dilini yine çıkarırsa daha fazla krema alacak.'::text),
(397296,44144,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha megint kinyújtja a nyelvét, még több mázat ...'::text,'kap'::text,'kapna'::text,'kapott'::text,'Ha megint kinyújtja a nyelvét, még több mázat kap.'::text),
(397299,44145,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Frosting sauer wäre, ... ihre Zunge im Mund.'::text,'bliebe'::text,'wird bleiben'::text,'bleibt'::text,'Wenn das Frosting sauer wäre, bliebe ihre Zunge im Mund.'::text),
(397303,44145,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби глазур була кисла, її язик ... у роті.'::text,'залишився б'::text,'залишиться'::text,'залишається'::text,'Якби глазур була кисла, її язик залишився б у роті.'::text),
(397302,44145,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el glaseado fuera ácido, su lengua ... dentro de la boca.'::text,'se quedaría'::text,'se quedará'::text,'se queda'::text,'Si el glaseado fuera ácido, su lengua se quedaría dentro de la boca.'::text),
(397301,44145,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le glaçage était acide, sa langue ... dans sa bouche.'::text,'resterait'::text,'restera'::text,'reste'::text,'Si le glaçage était acide, sa langue resterait dans sa bouche.'::text),
(397304,44145,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Krema ekşi olsaydı dili ağzının içinde ...'::text,'kalırdı'::text,'kalacak'::text,'kalıyor'::text,'Krema ekşi olsaydı dili ağzının içinde kalırdı.'::text),
(397305,44145,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a máz savanyú lenne, a nyelve a szájában ...'::text,'maradna'::text,'marad majd'::text,'marad'::text,'Ha a máz savanyú lenne, a nyelve a szájában maradna.'::text),
(397308,44146,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz klar ein super gesunder Snack: Pinkes Frosting ... direkt auf ihre Zunge gegeben.'::text,'wurde'::text,'hat'::text,'gibt'::text,'Ganz klar ein super gesunder Snack: Pinkes Frosting wurde direkt auf ihre Zunge gegeben.'::text),
(397312,44146,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, дуже корисний перекус: рожеву глазур ... прямо їй на язик.'::text,'нанесли'::text,'нанесла'::text,'наносить'::text,'Очевидно, дуже корисний перекус: рожеву глазур нанесли прямо їй на язик.'::text),
(397311,44146,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente un snack muy sano: el glaseado rosa ... directamente en su lengua.'::text,'fue puesto'::text,'puso'::text,'está poniendo'::text,'Claramente un snack muy sano: el glaseado rosa fue puesto directamente en su lengua.'::text),
(397310,44146,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un goûter très sain : du glaçage rose ... directement sur sa langue.'::text,'a été mis'::text,'a mis'::text,'est en train de mettre'::text,'Clairement un goûter très sain : du glaçage rose a été mis directement sur sa langue.'::text),
(397313,44146,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki çok sağlıklı bir atıştırmalık: pembe krema doğrudan diline ...'::text,'kondu'::text,'koydu'::text,'koyuyor'::text,'Belli ki çok sağlıklı bir atıştırmalık: pembe krema doğrudan diline kondu.'::text),
(397314,44146,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván nagyon egészséges nasi: a rózsaszín mázat egyenesen a nyelvére ...'::text,'tették'::text,'tette'::text,'teszi'::text,'Nyilván nagyon egészséges nasi: a rózsaszín mázat egyenesen a nyelvére tették.'::text),
(397317,44147,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau ... pinkes Frosting auf die Zunge des Mädchens.'::text,'tupfte'::text,'wurde getupft'::text,'tupfend'::text,'Die Frau tupfte pinkes Frosting auf die Zunge des Mädchens.'::text),
(397321,44147,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка ... рожеву глазур на язик дівчинки.'::text,'нанесла'::text,'була нанесена'::text,'наносячи'::text,'Жінка нанесла рожеву глазур на язик дівчинки.'::text),
(397320,44147,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... glaseado rosa en la lengua de la niña.'::text,'puso'::text,'fue puesta'::text,'poniendo'::text,'La mujer puso glaseado rosa en la lengua de la niña.'::text),
(397319,44147,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... du glaçage rose sur la langue de la fillette.'::text,'a déposé'::text,'a été déposée'::text,'déposant'::text,'La femme a déposé du glaçage rose sur la langue de la fillette.'::text),
(397322,44147,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın kızın diline pembe krema ...'::text,'sürdü'::text,'sürüldü'::text,'sürerek'::text,'Kadın kızın diline pembe krema sürdü.'::text),
(397323,44147,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő rózsaszín mázat ... a kislány nyelvére.'::text,'nyomott'::text,'lett nyomva'::text,'nyomva'::text,'A nő rózsaszín mázat nyomott a kislány nyelvére.'::text),
(397326,44148,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lacht mit Frosting auf der Zunge, also ... es süß schmecken.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Sie lacht mit Frosting auf der Zunge, also muss es süß schmecken.'::text),
(397330,44148,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сміється з глазур''ю на язику, тож це ... бути солодким на смак.'::text,'мусить'::text,'не може'::text,'має'::text,'Вона сміється з глазур''ю на язику, тож це мусить бути солодким на смак.'::text),
(397329,44148,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se ríe con glaseado en la lengua, así que ... saber dulce.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Se ríe con glaseado en la lengua, así que debe de saber dulce.'::text),
(397328,44148,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle rit avec du glaçage sur la langue, donc ça ... avoir un goût sucré.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Elle rit avec du glaçage sur la langue, donc ça doit avoir un goût sucré.'::text),
(397331,44148,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dilinde kremayla gülüyor, demek ki tadı tatlı ...'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Dilinde kremayla gülüyor, demek ki tadı tatlı olmalı.'::text),
(397332,44148,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nyelvén mázzal nevet, szóval az íze ... édes.'::text,'biztosan'::text,'nem lehet'::text,'valószínűleg'::text,'A nyelvén mázzal nevet, szóval az íze biztosan édes.'::text),
(397335,44149,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Mädchen, ... Zunge voller pinkem Frosting ist, lacht.'::text,'dessen'::text,'das'::text,'welches'::text,'Das Mädchen, dessen Zunge voller pinkem Frosting ist, lacht.'::text),
(397339,44149,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчинка, ... язик вкритий рожевою глазур''ю, сміється.'::text,'чий'::text,'яка'::text,'котра'::text,'Дівчинка, чий язик вкритий рожевою глазур''ю, сміється.'::text),
(397338,44149,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La niña, ... lengua está cubierta de glaseado rosa, se ríe.'::text,'cuya'::text,'que'::text,'la cual'::text,'La niña, cuya lengua está cubierta de glaseado rosa, se ríe.'::text),
(397337,44149,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fillette, ... la langue est couverte de glaçage rose, rit.'::text,'dont'::text,'qui'::text,'que'::text,'La fillette, dont la langue est couverte de glaçage rose, rit.'::text),
(397340,44149,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dili pembe kremayla kaplı ... kız gülüyor.'::text,'olan'::text,'kim'::text,'hangi'::text,'Dili pembe kremayla kaplı olan kız gülüyor.'::text),
(397341,44149,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kislány, ... nyelvét rózsaszín máz borítja, nevet.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A kislány, akinek a nyelvét rózsaszín máz borítja, nevet.'::text),
(397353,44151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damals ... sie Frosting auf der Zunge! Ein kompletter Albtraum!'::text,'hasste'::text,'hasste'::text,'war gewohnt zu hassen'::text,'Damals hasste sie Frosting auf der Zunge! Ein kompletter Albtraum!'::text),
(397357,44151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тоді вона ... глазур на язику! Суцільний жах!'::text,'ненавиділа'::text,'ненавиділа'::text,'звикла ненавидіти'::text,'Тоді вона ненавиділа глазур на язику! Суцільний жах!'::text),
(397356,44151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡En aquella época ... odiar el glaseado en la lengua! ¡Una pesadilla total!'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'¡En aquella época solía odiar el glaseado en la lengua! ¡Una pesadilla total!'::text),
(397355,44151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À l''époque, elle ... le glaçage sur la langue ! Un vrai cauchemar !'::text,'détestait'::text,'détestait'::text,'avait l''habitude de détester'::text,'À l''époque, elle détestait le glaçage sur la langue ! Un vrai cauchemar !'::text),
(397358,44151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O zamanlar dilinde kremadan ...! Tam bir kâbus!'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'O zamanlar dilinde kremadan nefret ederdi! Tam bir kâbus!'::text),
(397359,44151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akkoriban ... a mázat a nyelvén! Totális rémálom!'::text,'utálta'::text,'utálta'::text,'hozzá volt szokva, hogy utálja'::text,'Akkoriban utálta a mázat a nyelvén! Totális rémálom!'::text),
(397362,44152,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie weigert sich total, ihre Zunge wieder ..., bis sie mehr Frosting bekommt!'::text,'einzuziehen'::text,'Einziehen'::text,'einziehen'::text,'Sie weigert sich total, ihre Zunge wieder einzuziehen, bis sie mehr Frosting bekommt!'::text),
(397366,44152,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона категорично відмовляється ... язик назад, поки не отримає ще глазурі!'::text,'сховати'::text,'ховання'::text,'сховати'::text,'Вона категорично відмовляється сховати язик назад, поки не отримає ще глазурі!'::text),
(397365,44152,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se niega en rotundo ... la lengua hasta que le den más glaseado!'::text,'a meter'::text,'metiendo'::text,'meter'::text,'¡Se niega en rotundo a meter la lengua hasta que le den más glaseado!'::text),
(397364,44152,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle refuse catégoriquement ... sa langue tant qu''elle n''a pas plus de glaçage !'::text,'de rentrer'::text,'rentrant'::text,'rentrer'::text,'Elle refuse catégoriquement de rentrer sa langue tant qu''elle n''a pas plus de glaçage !'::text),
(397367,44152,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha fazla krema alana kadar dilini içeri ... kesinlikle reddediyor!'::text,'sokmayı'::text,'sokmayı'::text,'sokmak'::text,'Daha fazla krema alana kadar dilini içeri sokmayı kesinlikle reddediyor!'::text),
(397368,44152,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyáltalán nem hajlandó ... a nyelvét, amíg nem kap még mázat!'::text,'visszahúzni'::text,'visszahúzás'::text,'visszahúz'::text,'Egyáltalán nem hajlandó visszahúzni a nyelvét, amíg nem kap még mázat!'::text),
(397371,44153,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie streckt ... raus, und in der Küche bricht das absolute Chaos aus!'::text,'ihre Zunge'::text,'die Zunge'::text,'eine Zunge'::text,'Sie streckt ihre Zunge raus, und in der Küche bricht das absolute Chaos aus!'::text),
(397375,44153,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона висовує ..., і на кухні починається повний хаос!'::text,'язик'::text,'язик'::text,'язик'::text,'Вона висовує язик, і на кухні починається повний хаос!'::text),
(397374,44153,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Saca ... y la cocina se sume en el caos absoluto!'::text,'la lengua'::text,'la lengua'::text,'una lengua'::text,'¡Saca la lengua y la cocina se sume en el caos absoluto!'::text),
(397373,44153,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle tire ..., et la cuisine sombre dans le chaos total !'::text,'la langue'::text,'la langue'::text,'une langue'::text,'Elle tire la langue, et la cuisine sombre dans le chaos total !'::text),
(397376,44153,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... çıkarıyor ve mutfak tam bir kaosa dönüyor!'::text,'Dilini'::text,'Dili'::text,'Bir dil'::text,'Dilini çıkarıyor ve mutfak tam bir kaosa dönüyor!'::text),
(397377,44153,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kinyújtja ..., és a konyhában teljes káosz tör ki!'::text,'a nyelvét'::text,'a nyelvet'::text,'egy nyelvet'::text,'Kinyújtja a nyelvét, és a konyhában teljes káosz tör ki!'::text),
(399261,44363,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich werden sie heute Abend um zehn auf ihren gleichen Betten ...'::text,'tanzen'::text,'tanzen'::text,'tanzen'::text,'Bestie, angeblich werden sie heute Abend um zehn auf ihren gleichen Betten tanzen.'::text),
(399265,44363,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, сьогодні о десятій вони ... на своїх однакових ліжках.'::text,'танцюватимуть'::text,'потанцюють'::text,'танцюють'::text,'Подружко, кажуть, сьогодні о десятій вони танцюватимуть на своїх однакових ліжках.'::text),
(399264,44363,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que esta noche a las diez ... en sus camas gemelas.'::text,'estarán bailando'::text,'bailarán'::text,'bailan'::text,'Amiga, parece que esta noche a las diez estarán bailando en sus camas gemelas.'::text),
(399263,44363,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment ce soir à dix heures, elles ... sur leurs lits jumeaux.'::text,'seront en train de danser'::text,'danseront'::text,'dansent'::text,'Ma belle, apparemment ce soir à dix heures, elles seront en train de danser sur leurs lits jumeaux.'::text),
(399266,44363,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre bu gece saat onda ikiz yataklarının üstünde ...'::text,'dans ediyor olacaklar'::text,'dans edecekler'::text,'dans ediyorlar'::text,'Kanka, duyduğuma göre bu gece saat onda ikiz yataklarının üstünde dans ediyor olacaklar.'::text),
(399267,44363,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ma este tízkor az ikerágyaikon ...'::text,'fognak táncolni'::text,'táncolnak majd'::text,'táncolnak'::text,'Csajszi, állítólag ma este tízkor az ikerágyaikon fognak táncolni.'::text),
(399270,44364,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz klar genau das, was wir brauchten: „Ich verspreche, wir ... wieder auf diesen gleichen Betten.“'::text,'springen'::text,'werden springen'::text,'springen gerade'::text,'Ganz klar genau das, was wir brauchten: „Ich verspreche, wir springen wieder auf diesen gleichen Betten.“'::text),
(399274,44364,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, саме те, що нам було треба: «Обіцяю, ми знову ... на цих однакових ліжках».'::text,'стрибнемо'::text,'будемо стрибати'::text,'стрибаємо'::text,'Очевидно, саме те, що нам було треба: «Обіцяю, ми знову стрибнемо на цих однакових ліжках».'::text),
(399273,44364,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente justo lo que necesitábamos: «Prometo que ... otra vez en esas camas gemelas».'::text,'saltaremos'::text,'estaremos saltando'::text,'estamos saltando'::text,'Claramente justo lo que necesitábamos: «Prometo que saltaremos otra vez en esas camas gemelas».'::text),
(399272,44364,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement exactement ce qu''il nous fallait : « Je promets qu''on ... encore sur ces lits jumeaux. »'::text,'sautera'::text,'sera en train de sauter'::text,'saute'::text,'Clairement exactement ce qu''il nous fallait : « Je promets qu''on sautera encore sur ces lits jumeaux. »'::text),
(399275,44364,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki tam ihtiyacımız olan şey: “Söz veriyorum, yine ... o ikiz yataklarda.”'::text,'zıplayacağız'::text,'zıplıyor olacağız'::text,'zıplıyoruz'::text,'Belli ki tam ihtiyacımız olan şey: “Söz veriyorum, yine zıplayacağız o ikiz yataklarda.”'::text),
(399276,44364,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván pont erre volt szükségünk: „Megígérem, hogy megint ... azokon az ikerágyakon.”'::text,'ugrálni fogunk'::text,'ugrálunk majd'::text,'ugrálunk'::text,'Nyilván pont erre volt szükségünk: „Megígérem, hogy megint ugrálni fogunk azokon az ikerágyakon.”'::text),
(399279,44365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Na klar, wenn ein Zimmer Zwillingsbetten ..., streitet sich niemand darum, wo man schläft.'::text,'hat'::text,'hatte'::text,'haben wird'::text,'Na klar, wenn ein Zimmer Zwillingsbetten hat, streitet sich niemand darum, wo man schläft.'::text),
(399283,44365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, якщо в кімнаті ... однакові ліжка, ніхто не свариться, де спати.'::text,'є'::text,'були'::text,'будуть'::text,'Звісно, якщо в кімнаті є однакові ліжка, ніхто не свариться, де спати.'::text),
(399282,44365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, si una habitación ... camas gemelas, nadie se pelea por dónde dormir.'::text,'tiene'::text,'tenía'::text,'tendrá'::text,'Obviamente, si una habitación tiene camas gemelas, nadie se pelea por dónde dormir.'::text),
(399281,44365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, si une chambre ... des lits jumeaux, personne ne se dispute pour savoir où dormir.'::text,'a'::text,'avait'::text,'aura'::text,'Évidemment, si une chambre a des lits jumeaux, personne ne se dispute pour savoir où dormir.'::text),
(399284,44365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki, bir odada ikiz yatak ..., kimse nerede uyuyacağı konusunda kavga etmez.'::text,'varsa'::text,'vardıysa'::text,'olacaksa'::text,'Tabii ki, bir odada ikiz yatak varsa, kimse nerede uyuyacağı konusunda kavga etmez.'::text),
(399285,44365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván, ha egy szobában ikerágy ..., senki sem veszekszik azon, hol aludjon.'::text,'van'::text,'volt'::text,'lesz'::text,'Nyilván, ha egy szobában ikerágy van, senki sem veszekszik azon, hol aludjon.'::text),
(399288,44366,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zwei Betten im Zimmer sind Zwillingsbetten, ...'::text,'nicht wahr?'::text,'oder?'::text,'oder?'::text,'Die zwei Betten im Zimmer sind Zwillingsbetten, nicht wahr?'::text),
(399292,44366,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Два ліжка в кімнаті однакові, ...'::text,'чи не так?'::text,'правда?'::text,'так?'::text,'Два ліжка в кімнаті однакові, чи не так?'::text),
(399291,44366,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las dos camas de la habitación son gemelas, ...'::text,'¿verdad?'::text,'¿no?'::text,'¿sí?'::text,'Las dos camas de la habitación son gemelas, ¿verdad?'::text),
(399290,44366,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux lits de la chambre sont des lits jumeaux, ...'::text,'n''est-ce pas ?'::text,'hein ?'::text,'c''est ça ?'::text,'Les deux lits de la chambre sont des lits jumeaux, n''est-ce pas ?'::text),
(399293,44366,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Odadaki iki yatak ikiz yatak, ...'::text,'değil mi?'::text,'değil mi?'::text,'öyle mi?'::text,'Odadaki iki yatak ikiz yatak, değil mi?'::text),
(399294,44366,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szobában lévő két ágy ikerágy, ...'::text,'ugye?'::text,'nem?'::text,'igaz?'::text,'A szobában lévő két ágy ikerágy, ugye?'::text),
(399306,44368,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zur Schlafenszeit werden sie auf ihren Zwillingsbetten zehn Armbänder ...'::text,'gemacht haben'::text,'machen'::text,'machen'::text,'Bis zur Schlafenszeit werden sie auf ihren Zwillingsbetten zehn Armbänder gemacht haben.'::text),
(399310,44368,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До сну вони ... десять браслетів на своїх однакових ліжках.'::text,'зроблять'::text,'зроблять'::text,'робитимуть'::text,'До сну вони зроблять десять браслетів на своїх однакових ліжках.'::text),
(399309,44368,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la hora de dormir, ... diez pulseras en sus camas gemelas.'::text,'habrán hecho'::text,'harán'::text,'estarán haciendo'::text,'Para la hora de dormir, habrán hecho diez pulseras en sus camas gemelas.'::text),
(399308,44368,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici l''heure du coucher, elles ... dix bracelets sur leurs lits jumeaux.'::text,'auront fait'::text,'feront'::text,'seront en train de faire'::text,'D''ici l''heure du coucher, elles auront fait dix bracelets sur leurs lits jumeaux.'::text),
(399311,44368,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yatma saatine kadar ikiz yataklarında on bileklik ...'::text,'yapmış olacaklar'::text,'yapacaklar'::text,'yapıyor olacaklar'::text,'Yatma saatine kadar ikiz yataklarında on bileklik yapmış olacaklar.'::text),
(399312,44368,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lefekvésig ... tíz karkötőt az ikerágyaikon.'::text,'elkészítenek'::text,'készítenek'::text,'készíteni fognak'::text,'Lefekvésig elkészítenek tíz karkötőt az ikerágyaikon.'::text),
(399315,44369,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Betten keine Zwillingsbetten gewesen wären, hätten sie sich um das bessere ...! Krieg!'::text,'gestritten'::text,'streiten'::text,'stritten'::text,'Wenn die Betten keine Zwillingsbetten gewesen wären, hätten sie sich um das bessere gestritten! Krieg!'::text),
(399319,44369,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ліжка не були однаковими, вони ... за краще! Війна!'::text,'побилися б'::text,'поб''ються'::text,'побилися'::text,'Якби ліжка не були однаковими, вони побилися б за краще! Війна!'::text),
(399318,44369,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si las camas no hubieran sido gemelas, ... por la mejor! ¡Guerra!'::text,'se habrían peleado'::text,'se pelearán'::text,'se pelearon'::text,'¡Si las camas no hubieran sido gemelas, se habrían peleado por la mejor! ¡Guerra!'::text),
(399317,44369,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les lits n''avaient pas été jumeaux, elles ... pour le meilleur ! La guerre !'::text,'se seraient battues'::text,'se battront'::text,'se sont battues'::text,'Si les lits n''avaient pas été jumeaux, elles se seraient battues pour le meilleur ! La guerre !'::text),
(399320,44369,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yataklar ikiz olmasaydı, daha iyisi için ...! Savaş!'::text,'kavga ederlerdi'::text,'kavga edecekler'::text,'kavga ettiler'::text,'Yataklar ikiz olmasaydı, daha iyisi için kavga ederlerdi! Savaş!'::text),
(399321,44369,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az ágyak nem lettek volna egyformák, ... a jobbikon! Háború!'::text,'összevesztek volna'::text,'össze fognak veszni'::text,'összevesztek'::text,'Ha az ágyak nem lettek volna egyformák, összevesztek volna a jobbikon! Háború!'::text),
(399324,44370,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie weigerte sich, ihr Zwillingsbett am Spiegel ...! Totales Drama, für immer!'::text,'aufzugeben'::text,'Aufgeben'::text,'aufgeben'::text,'Sie weigerte sich, ihr Zwillingsbett am Spiegel aufzugeben! Totales Drama, für immer!'::text),
(399328,44370,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона відмовилася ... своє однакове ліжко біля дзеркала! Повна драма, назавжди!'::text,'віддати'::text,'віддавання'::text,'віддати'::text,'Вона відмовилася віддати своє однакове ліжко біля дзеркала! Повна драма, назавжди!'::text),
(399327,44370,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se negó ... su cama gemela junto al espejo! ¡Drama total, para siempre!'::text,'a ceder'::text,'cediendo'::text,'ceder'::text,'¡Se negó a ceder su cama gemela junto al espejo! ¡Drama total, para siempre!'::text),
(399326,44370,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a refusé ... son lit jumeau près du miroir ! Drame total, pour toujours !'::text,'de céder'::text,'cédant'::text,'céder'::text,'Elle a refusé de céder son lit jumeau près du miroir ! Drame total, pour toujours !'::text),
(399329,44370,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aynanın yanındaki ikiz yatağından ... reddetti! Tam bir dram, sonsuza dek!'::text,'vazgeçmeyi'::text,'vazgeçmeyi'::text,'vazgeçmek'::text,'Aynanın yanındaki ikiz yatağından vazgeçmeyi reddetti! Tam bir dram, sonsuza dek!'::text),
(399330,44370,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem volt hajlandó ... a tükör melletti ikerágyáról! Totális dráma, örökre!'::text,'lemondani'::text,'lemondás'::text,'lemond'::text,'Nem volt hajlandó lemondani a tükör melletti ikerágyáról! Totális dráma, örökre!'::text),
(399333,44371,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jemand ... diese Zwillingsbetten perfekt geplant haben, sonst wäre das hier das komplette Chaos!'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Jemand muss diese Zwillingsbetten perfekt geplant haben, sonst wäre das hier das komplette Chaos!'::text),
(399337,44371,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хтось ... ідеально спланувати ці однакові ліжка, інакше тут був би повний хаос!'::text,'мусив'::text,'мав'::text,'не міг'::text,'Хтось мусив ідеально спланувати ці однакові ліжка, інакше тут був би повний хаос!'::text),
(399336,44371,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Alguien ... planeado esas camas gemelas a la perfección, o esto sería un caos total!'::text,'debe de haber'::text,'debería haber'::text,'no puede haber'::text,'¡Alguien debe de haber planeado esas camas gemelas a la perfección, o esto sería un caos total!'::text),
(399335,44371,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelqu''un ... ces lits jumeaux à la perfection, sinon ce serait le chaos total !'::text,'a dû prévoir'::text,'aurait dû prévoir'::text,'ne peut pas avoir prévu'::text,'Quelqu''un a dû prévoir ces lits jumeaux à la perfection, sinon ce serait le chaos total !'::text),
(399338,44371,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri bu ikiz yatakları kusursuzca ..., yoksa burası tam bir kaos olurdu!'::text,'planlamış olmalı'::text,'planlamalıydı'::text,'planlamış olamaz'::text,'Biri bu ikiz yatakları kusursuzca planlamış olmalı, yoksa burası tam bir kaos olurdu!'::text),
(399339,44371,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valaki ... tökéletesen ezeket az ikerágyakat, különben teljes káosz lenne itt!'::text,'biztosan megtervezte'::text,'meg kellett volna terveznie'::text,'nem tervezhette meg'::text,'Valaki biztosan megtervezte tökéletesen ezeket az ikerágyakat, különben teljes káosz lenne itt!'::text),
(399342,44372,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, ich hab gehört, dass sie diese Woche jede Nacht auf diesen Zwillingsbetten ...'::text,'geschlafen haben'::text,'schlafen'::text,'schlafen'::text,'Omg, ich hab gehört, dass sie diese Woche jede Nacht auf diesen Zwillingsbetten geschlafen haben.'::text),
(399346,44372,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже, я чула, що цього тижня вони щоночі ... на тих однакових ліжках.'::text,'спали'::text,'сплять'::text,'сплять'::text,'Боже, я чула, що цього тижня вони щоночі спали на тих однакових ліжках.'::text),
(399345,44372,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dios, me han dicho que esta semana ... cada noche en esas camas gemelas.'::text,'han dormido'::text,'duermen'::text,'están durmiendo'::text,'Dios, me han dicho que esta semana han dormido cada noche en esas camas gemelas.'::text),
(399344,44372,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, j''ai entendu dire qu''elles ... sur ces lits jumeaux toutes les nuits cette semaine.'::text,'ont dormi'::text,'dorment'::text,'sont en train de dormir'::text,'Omg, j''ai entendu dire qu''elles ont dormi sur ces lits jumeaux toutes les nuits cette semaine.'::text),
(399347,44372,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman tanrım, duydum ki bu hafta her gece o ikiz yataklarda ...'::text,'uyumuşlar'::text,'uyuyorlar'::text,'uyuyorlar'::text,'Aman tanrım, duydum ki bu hafta her gece o ikiz yataklarda uyumuşlar.'::text),
(399348,44372,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, azt hallottam, hogy ezen a héten minden éjjel azokon az ikerágyakon ...'::text,'aludtak'::text,'alszanak'::text,'alszanak'::text,'Úristen, azt hallottam, hogy ezen a héten minden éjjel azokon az ikerágyakon aludtak.'::text),
(377886,41988,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie haben den Quilt fertig ... und angefangen zu schreien, Digga, ohne Witz.'::text,'genäht'::text,'zu nähen'::text,'nähen'::text,'Sie haben den Quilt fertig genäht und angefangen zu schreien, Digga, ohne Witz.'::text),
(377890,41988,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони закінчили ... ковдру і почали верещати, бро, без жартів.'::text,'шити'::text,'шити'::text,'шиють'::text,'Вони закінчили шити ковдру і почали верещати, бро, без жартів.'::text),
(377889,41988,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Terminaron de ... la colcha y se pusieron a gritar, bro, en serio.'::text,'coser'::text,'coser'::text,'cosen'::text,'Terminaron de coser la colcha y se pusieron a gritar, bro, en serio.'::text),
(377888,41988,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ont fini ... la courtepointe et se sont mises à crier, frérot, sans mentir.'::text,'de coudre'::text,'coudre'::text,'cousent'::text,'Elles ont fini de coudre la courtepointe et se sont mises à crier, frérot, sans mentir.'::text),
(377891,41988,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yorganı ... bitirdiler ve çığlık atmaya başladılar, kanka, yemin ederim.'::text,'dikmeyi'::text,'dikmek'::text,'dikiyorlar'::text,'Yorganı dikmeyi bitirdiler ve çığlık atmaya başladılar, kanka, yemin ederim.'::text),
(377892,41988,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Befejezték a foltvarrott takaró ..., és sikítozni kezdtek, tesó, komolyan.'::text,'varrását'::text,'varrni'::text,'varrnak'::text,'Befejezték a foltvarrott takaró varrását, és sikítozni kezdtek, tesó, komolyan.'::text),
(377904,41990,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Frau hat ihr Quadrat für den Quilt fertig gemacht, und ...'::text,'die anderen auch'::text,'die anderen auch'::text,'die anderen auch nicht'::text,'Eine Frau hat ihr Quadrat für den Quilt fertig gemacht, und die anderen auch.'::text),
(377908,41990,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна жінка закінчила свій квадрат для ковдри, і ...'::text,'інші теж'::text,'інші теж'::text,'інші теж ні'::text,'Одна жінка закінчила свій квадрат для ковдри, і інші теж.'::text),
(377907,41990,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una mujer terminó su cuadrado para la colcha, y ...'::text,'las demás también'::text,'las demás también'::text,'las demás tampoco'::text,'Una mujer terminó su cuadrado para la colcha, y las demás también.'::text),
(377906,41990,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une femme a fini son carré pour la courtepointe, et ...'::text,'les autres aussi'::text,'les autres aussi'::text,'les autres non plus'::text,'Une femme a fini son carré pour la courtepointe, et les autres aussi.'::text),
(377909,41990,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kadın yorgan için karesini bitirdi ve ...'::text,'diğerleri de'::text,'diğerleri de'::text,'diğerleri de bitirmedi'::text,'Bir kadın yorgan için karesini bitirdi ve diğerleri de.'::text),
(377910,41990,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy nő befejezte a négyzetét a takaróhoz, és ...'::text,'a többiek is'::text,'a többiek is'::text,'a többiek sem'::text,'Egy nő befejezte a négyzetét a takaróhoz, és a többiek is.'::text),
(377913,41991,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... wochenlang Stoffquadrate zusammen, bevor der Quilt fertig war.'::text,'nähten'::text,'nähen'::text,'nähten'::text,'Sie nähten wochenlang Stoffquadrate zusammen, bevor der Quilt fertig war.'::text),
(377917,41991,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... тканинні квадрати тижнями, поки ковдра не була готова.'::text,'зшивали'::text,'зшивають'::text,'зшивали'::text,'Вони зшивали тканинні квадрати тижнями, поки ковдра не була готова.'::text),
(377916,41991,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cuadrados de tela durante semanas antes de que la colcha estuviera terminada.'::text,'Habían estado cosiendo'::text,'Han estado cosiendo'::text,'Estaban cosiendo'::text,'Habían estado cosiendo cuadrados de tela durante semanas antes de que la colcha estuviera terminada.'::text),
(377915,41991,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ... des carrés de tissu ensemble depuis des semaines avant que la courtepointe soit finie.'::text,'cousaient'::text,'cousent'::text,'étaient en train de coudre'::text,'Elles cousaient des carrés de tissu ensemble depuis des semaines avant que la courtepointe soit finie.'::text),
(377918,41991,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yorgan bitmeden önce haftalarca kumaş kareleri birbirine ...'::text,'dikiyorlardı'::text,'dikiyorlar'::text,'dikiyorlardı'::text,'Yorgan bitmeden önce haftalarca kumaş kareleri birbirine dikiyorlardı.'::text),
(377919,41991,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hetekig ... egymáshoz az anyagnégyzeteket, mielőtt a takaró elkészült.'::text,'varrták'::text,'varrják'::text,'varrták'::text,'Hetekig varrták egymáshoz az anyagnégyzeteket, mielőtt a takaró elkészült.'::text),
(377922,41992,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis nächstes Wochenende wird die Gruppe einen zweiten Patchwork-Quilt ...'::text,'genäht haben'::text,'nähen'::text,'nähen'::text,'Bis nächstes Wochenende wird die Gruppe einen zweiten Patchwork-Quilt genäht haben.'::text),
(377926,41992,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступних вихідних група ... другу клаптикову ковдру.'::text,'пошиє'::text,'пошиє'::text,'шитиме'::text,'До наступних вихідних група пошиє другу клаптикову ковдру.'::text),
(377925,41992,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el próximo fin de semana, el grupo ... una segunda colcha de patchwork.'::text,'habrá cosido'::text,'coserá'::text,'estará cosiendo'::text,'Para el próximo fin de semana, el grupo habrá cosido una segunda colcha de patchwork.'::text),
(377924,41992,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le week-end prochain, le groupe ... une deuxième courtepointe en patchwork.'::text,'aura cousu'::text,'coudra'::text,'sera en train de coudre'::text,'D''ici le week-end prochain, le groupe aura cousu une deuxième courtepointe en patchwork.'::text),
(377927,41992,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek hafta sonuna kadar grup ikinci bir patchwork yorgan ...'::text,'dikmiş olacak'::text,'dikecek'::text,'dikiyor olacak'::text,'Gelecek hafta sonuna kadar grup ikinci bir patchwork yorgan dikmiş olacak.'::text),
(377928,41992,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő hétvégére a csoport ... egy második patchwork takarót.'::text,'megvarr'::text,'varrni fog'::text,'varrni fog'::text,'Jövő hétvégére a csoport megvarr egy második patchwork takarót.'::text),
(377931,41993,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, angeblich ... sie im Juni schon seit fünf Jahren zusammen Quilts.'::text,'machen'::text,'machen'::text,'machen'::text,'Omg, angeblich machen sie im Juni schon seit fünf Jahren zusammen Quilts.'::text),
(377935,41993,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже, кажуть, що в червні вони вже п''ять років ... ковдри разом.'::text,'шитимуть'::text,'шитимуть'::text,'пошиють'::text,'Боже, кажуть, що в червні вони вже п''ять років шитимуть ковдри разом.'::text),
(377934,41993,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, al parecer en junio ya ... cinco años haciendo colchas juntas.'::text,'llevarán'::text,'estarán'::text,'harán'::text,'Omg, al parecer en junio ya llevarán cinco años haciendo colchas juntas.'::text),
(377933,41993,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, apparemment en juin, elles ... des courtepointes ensemble depuis cinq ans.'::text,'feront'::text,'seront en train de faire'::text,'feront'::text,'Omg, apparemment en juin, elles feront des courtepointes ensemble depuis cinq ans.'::text),
(377936,41993,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman tanrım, duyduğuma göre haziranda beş yıldır birlikte yorgan ...'::text,'yapıyor olacaklar'::text,'yapıyor olacaklar'::text,'yapacaklar'::text,'Aman tanrım, duyduğuma göre haziranda beş yıldır birlikte yorgan yapıyor olacaklar.'::text),
(377937,41993,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, állítólag júniusban már öt éve ... együtt takarókat.'::text,'készítenek'::text,'fognak készíteni'::text,'készítenek majd'::text,'Úristen, állítólag júniusban már öt éve készítenek együtt takarókat.'::text),
(377940,41994,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Quadrat gefehlt hätte, ... der Quilt heute nicht fertig geworden.'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn ein Quadrat gefehlt hätte, wäre der Quilt heute nicht fertig geworden.'::text),
(377944,41994,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби бракувало одного квадрата, ковдра ... готова сьогодні.'::text,'не була б'::text,'не буде'::text,'не була'::text,'Якби бракувало одного квадрата, ковдра не була б готова сьогодні.'::text),
(377943,41994,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera faltado un cuadrado, la colcha ... terminada hoy.'::text,'no habría estado'::text,'no estará'::text,'no estaba'::text,'Si hubiera faltado un cuadrado, la colcha no habría estado terminada hoy.'::text),
(377942,41994,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait manqué un carré, la courtepointe ... finie aujourd''hui.'::text,'n''aurait pas été'::text,'ne sera pas'::text,'n''était pas'::text,'S''il avait manqué un carré, la courtepointe n''aurait pas été finie aujourd''hui.'::text),
(377945,41994,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kare eksik olsaydı, yorgan bugün ...'::text,'bitmiş olmazdı'::text,'bitmeyecek'::text,'bitmedi'::text,'Bir kare eksik olsaydı, yorgan bugün bitmiş olmazdı.'::text),
(377946,41994,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha hiányzott volna egy négyzet, a takaró ma ... kész.'::text,'nem lett volna'::text,'nem lesz'::text,'nem volt'::text,'Ha hiányzott volna egy négyzet, a takaró ma nem lett volna kész.'::text),
(377949,41995,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dieser Quilt ... jetzt nicht so gut aus, wenn du nicht nähen gelernt hättest.'::text,'sähe'::text,'hätte ausgesehen'::text,'wird'::text,'Ehrlich, dieser Quilt sähe jetzt nicht so gut aus, wenn du nicht nähen gelernt hättest.'::text),
(377953,41995,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби ти не навчилася шити, ця ковдра зараз ... так класно.'::text,'не виглядала б'::text,'не виглядала б'::text,'не виглядатиме'::text,'Чесно, якби ти не навчилася шити, ця ковдра зараз не виглядала б так класно.'::text),
(377952,41995,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si no hubieras aprendido a coser, esta colcha ... tan bien ahora mismo.'::text,'no quedaría'::text,'no habría quedado'::text,'no quedará'::text,'Sinceramente, si no hubieras aprendido a coser, esta colcha no quedaría tan bien ahora mismo.'::text),
(377951,41995,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu n''avais pas appris à coudre, cette courtepointe ... aussi belle en ce moment.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'Franchement, si tu n''avais pas appris à coudre, cette courtepointe ne serait pas aussi belle en ce moment.'::text),
(377954,41995,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, dikiş dikmeyi öğrenmeseydin bu yorgan şu an bu kadar güzel ...'::text,'görünmezdi'::text,'görünmemiş olurdu'::text,'görünmeyecek'::text,'Açıkçası, dikiş dikmeyi öğrenmeseydin bu yorgan şu an bu kadar güzel görünmezdi.'::text),
(377955,41995,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha nem tanultál volna meg varrni, ez a takaró most ... ilyen jól.'::text,'nem nézne ki'::text,'nem nézett volna ki'::text,'nem fog kinézni'::text,'Őszintén, ha nem tanultál volna meg varrni, ez a takaró most nem nézne ki ilyen jól.'::text),
(377958,41996,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man geht davon aus, dass der Quilt aus über hundert Stoffquadraten ...'::text,'genäht wurde'::text,'nähen'::text,'nähend'::text,'Man geht davon aus, dass der Quilt aus über hundert Stoffquadraten genäht wurde.'::text),
(377962,41996,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що ковдру ... з понад сотні тканинних квадратів.'::text,'зшили'::text,'шити'::text,'шиючи'::text,'Вважається, що ковдру зшили з понад сотні тканинних квадратів.'::text),
(377961,41996,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la colcha ... con más de cien cuadrados de tela.'::text,'fue cosida'::text,'coser'::text,'cosiendo'::text,'Se cree que la colcha fue cosida con más de cien cuadrados de tela.'::text),
(377960,41996,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que la courtepointe ... à partir de plus de cent carrés de tissu.'::text,'a été cousue'::text,'coudre'::text,'cousant'::text,'On pense que la courtepointe a été cousue à partir de plus de cent carrés de tissu.'::text),
(377963,41996,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yorganın yüzden fazla kumaş kareden ... düşünülüyor.'::text,'dikildiği'::text,'dikmek'::text,'dikerek'::text,'Yorganın yüzden fazla kumaş kareden dikildiği düşünülüyor.'::text),
(377964,41996,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy gondolják, hogy a takarót több mint száz anyagnégyzetből ...'::text,'varrták'::text,'varrni'::text,'varrva'::text,'Úgy gondolják, hogy a takarót több mint száz anyagnégyzetből varrták.'::text),
(377976,41998,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leicht optimistisch: Sie ... so einen großen Quilt ohne Hilfe nicht fertig gemacht haben.'::text,'können'::text,'dürfen'::text,'sollten'::text,'Leicht optimistisch: Sie können so einen großen Quilt ohne Hilfe nicht fertig gemacht haben.'::text),
(377980,41998,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи оптимістично: вони ... закінчити таку велику ковдру без допомоги.'::text,'не могли'::text,'не мусили'::text,'не мали б'::text,'Трохи оптимістично: вони не могли закінчити таку велику ковдру без допомоги.'::text),
(377979,41998,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un poco optimista: ... terminado una colcha tan grande sin ayuda.'::text,'no pueden haber'::text,'no deben haber'::text,'no deberían haber'::text,'Un poco optimista: no pueden haber terminado una colcha tan grande sin ayuda.'::text),
(377978,41998,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Légèrement optimiste : elles ... finir une si grande courtepointe sans aide.'::text,'n''ont pas pu'::text,'n''ont pas dû'::text,'n''auraient pas dû'::text,'Légèrement optimiste : elles n''ont pas pu finir une si grande courtepointe sans aide.'::text),
(377981,41998,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz iyimser: bu kadar büyük bir yorganı yardım almadan ...'::text,'bitirmiş olamazlar'::text,'bitirmemiş olmalılar'::text,'bitirmemeliydiler'::text,'Biraz iyimser: bu kadar büyük bir yorganı yardım almadan bitirmiş olamazlar.'::text),
(377982,41998,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kicsit optimista: ... egy ilyen nagy takarót segítség nélkül.'::text,'nem fejezhették be'::text,'nem szabadott befejezniük'::text,'nem kellett volna befejezniük'::text,'Kicsit optimista: nem fejezhették be egy ilyen nagy takarót segítség nélkül.'::text),
(364935,40549,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich jetzt schon seit fünf Minuten an das weiße Geländer und hält sich die Seite.'::text,'lehnt'::text,'lehnt'::text,'lehnt'::text,'Sie lehnt sich jetzt schon seit fünf Minuten an das weiße Geländer und hält sich die Seite.'::text),
(364939,40549,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже п''ять хвилин ... на біле поруччя, тримаючись за бік.'::text,'спирається'::text,'спирається'::text,'спирається'::text,'Вона вже п''ять хвилин спирається на біле поруччя, тримаючись за бік.'::text),
(364938,40549,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se ... en la barandilla blanca desde hace cinco minutos, sujetándose el costado.'::text,'apoya'::text,'está apoyando'::text,'apoya'::text,'Se apoya en la barandilla blanca desde hace cinco minutos, sujetándose el costado.'::text),
(364937,40549,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sur la rambarde blanche depuis cinq minutes maintenant, en se tenant le côté.'::text,'s''appuie'::text,'est en train de s''appuyer'::text,'s''appuie'::text,'Elle s''appuie sur la rambarde blanche depuis cinq minutes maintenant, en se tenant le côté.'::text),
(364940,40549,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beş dakikadır böğrünü tutarak beyaz korkuluğa ...'::text,'yaslanıyor'::text,'yaslanıyor'::text,'yaslanır'::text,'Beş dakikadır böğrünü tutarak beyaz korkuluğa yaslanıyor.'::text),
(364941,40549,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már öt perce ... a fehér korlátra, és fogja az oldalát.'::text,'támaszkodik'::text,'támaszkodik'::text,'támaszkodik'::text,'Már öt perce támaszkodik a fehér korlátra, és fogja az oldalát.'::text),
(364944,40550,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst als der Schmerz in der Seite kam, ... an das Brückengeländer.'::text,'lehnte sie sich'::text,'sie lehnte sich'::text,'sie lehnte sich'::text,'Erst als der Schmerz in der Seite kam, lehnte sie sich an das Brückengeländer.'::text),
(364948,40550,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише коли її прихопило в боці, ... на поруччя мосту.'::text,'вона сперлася'::text,'вона сперлася'::text,'вона таки сперлася'::text,'Лише коли її прихопило в боці, вона сперлася на поруччя мосту.'::text),
(364947,40550,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo cuando le dio el dolor en el costado ... en la barandilla del puente.'::text,'se apoyó'::text,'ella se apoyó'::text,'sí se apoyó'::text,'Solo cuando le dio el dolor en el costado se apoyó en la barandilla del puente.'::text),
(364946,40550,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est que quand la douleur au côté est arrivée ... sur la rambarde du pont.'::text,'qu''elle s''est appuyée'::text,'elle s''est appuyée'::text,'elle s''est bien appuyée'::text,'Ce n''est que quand la douleur au côté est arrivée qu''elle s''est appuyée sur la rambarde du pont.'::text),
(364949,40550,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ancak böğründeki ağrı başlayınca köprü korkuluğuna ...'::text,'yaslandı'::text,'yaslandı'::text,'gerçekten yaslandı'::text,'Ancak böğründeki ağrı başlayınca köprü korkuluğuna yaslandı.'::text),
(364950,40550,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak amikor belenyilallt a fájdalom az oldalába, akkor ... a híd korlátjának.'::text,'dőlt neki'::text,'nekidőlt'::text,'tényleg nekidőlt'::text,'Csak amikor belenyilallt a fájdalom az oldalába, akkor dőlt neki a híd korlátjának.'::text),
(364962,40552,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich wünscht sich ihr Partner, dass sie sich nicht jeden einzelnen Kilometer an ein Geländer ...'::text,'lehnen würde'::text,'lehnt'::text,'lehnen wird'::text,'Girl, angeblich wünscht sich ihr Partner, dass sie sich nicht jeden einzelnen Kilometer an ein Geländer lehnen würde.'::text),
(364966,40552,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, її партнер хотів би, щоб вона ... на поруччя на кожному кілометрі.'::text,'не спиралася'::text,'не спирається'::text,'не буде спиратися'::text,'Подруго, кажуть, її партнер хотів би, щоб вона не спиралася на поруччя на кожному кілометрі.'::text),
(364965,40552,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer su compañero desearía que ... en una barandilla en cada kilómetro.'::text,'no se apoyara'::text,'no se apoya'::text,'no se apoyará'::text,'Tía, al parecer su compañero desearía que no se apoyara en una barandilla en cada kilómetro.'::text),
(364964,40552,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment son partenaire aimerait qu''elle ... sur une rambarde à chaque kilomètre.'::text,'ne s''appuie pas'::text,'ne s''appuie pas'::text,'ne s''appuiera pas'::text,'Meuf, apparemment son partenaire aimerait qu''elle ne s''appuie pas sur une rambarde à chaque kilomètre.'::text),
(364967,40552,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre partneri keşke her kilometrede bir korkuluğa ... diye düşünüyormuş.'::text,'yaslanmasa'::text,'yaslanmıyor'::text,'yaslanmayacak'::text,'Kızım, duyduğuma göre partneri keşke her kilometrede bir korkuluğa yaslanmasa diye düşünüyormuş.'::text),
(364968,40552,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a partnere azt szeretné, ha ... minden egyes kilométernél korlátnak.'::text,'nem dőlne neki'::text,'nem dől neki'::text,'nem fog nekidőlni'::text,'Csajszi, állítólag a partnere azt szeretné, ha nem dőlne neki minden egyes kilométernél korlátnak.'::text),
(364971,40553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, die Brücke, an ... Geländer du dich mitten beim Laufen gelehnt hast, sah noch nie so stylisch aus.'::text,'deren'::text,'die'::text,'wo'::text,'Ehrlich, die Brücke, an deren Geländer du dich mitten beim Laufen gelehnt hast, sah noch nie so stylisch aus.'::text),
(364975,40553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, міст, на ... поруччя ти сперлася посеред пробіжки, ще ніколи не виглядав так стильно.'::text,'чиє'::text,'який'::text,'де'::text,'Чесно, міст, на чиє поруччя ти сперлася посеред пробіжки, ще ніколи не виглядав так стильно.'::text),
(364974,40553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, el puente, en ... barandilla te apoyaste en plena carrera, nunca se vio tan estiloso.'::text,'cuya'::text,'que'::text,'donde'::text,'Sinceramente, el puente, en cuya barandilla te apoyaste en plena carrera, nunca se vio tan estiloso.'::text),
(364973,40553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, le pont, sur la rambarde ... tu t''es appuyée en pleine course, n''a jamais eu autant de style.'::text,'duquel'::text,'qui'::text,'où'::text,'Franchement, le pont, sur la rambarde duquel tu t''es appuyée en pleine course, n''a jamais eu autant de style.'::text),
(364976,40553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, koşunun ortasında korkuluğuna ... köprü hiç bu kadar şık görünmemişti.'::text,'yaslandığın'::text,'hangi'::text,'nerede'::text,'Açıkçası, koşunun ortasında korkuluğuna yaslandığın köprü hiç bu kadar şık görünmemişti.'::text),
(364977,40553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a híd, ... korlátjának futás közben nekidőltél, még sosem nézett ki ilyen stílusosan.'::text,'amelynek a'::text,'amely'::text,'ahol'::text,'Őszintén, a híd, amelynek a korlátjának futás közben nekidőltél, még sosem nézett ki ilyen stílusosan.'::text),
(364980,40554,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Schmerzen in der Seite lehnte sie sich ans Geländer, statt weiterzulaufen.'::text,'Wegen'::text,'Trotz'::text,'Vorausgesetzt'::text,'Wegen der Schmerzen in der Seite lehnte sie sich ans Geländer, statt weiterzulaufen.'::text),
(364984,40554,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... біль у боці, вона сперлася на поруччя замість того, щоб бігти далі.'::text,'Через'::text,'Попри'::text,'За умови, що'::text,'Через біль у боці, вона сперлася на поруччя замість того, щоб бігти далі.'::text),
(364983,40554,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el dolor en el costado, se apoyó en la barandilla en lugar de seguir corriendo.'::text,'Debido a'::text,'A pesar de'::text,'Siempre que'::text,'Debido a el dolor en el costado, se apoyó en la barandilla en lugar de seguir corriendo.'::text),
(364982,40554,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la douleur au côté, elle s''est appuyée sur la rambarde au lieu de continuer à courir.'::text,'En raison de'::text,'Malgré'::text,'Pourvu que'::text,'En raison de la douleur au côté, elle s''est appuyée sur la rambarde au lieu de continuer à courir.'::text),
(364985,40554,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Böğründeki ağrı ... koşmaya devam etmek yerine korkuluğa yaslandı.'::text,'nedeniyle'::text,'rağmen'::text,'şartıyla'::text,'Böğründeki ağrı nedeniyle koşmaya devam etmek yerine korkuluğa yaslandı.'::text),
(364986,40554,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az oldalában érzett fájdalom ... a korlátra támaszkodott ahelyett, hogy tovább futott volna.'::text,'miatt'::text,'ellenére'::text,'feltéve'::text,'Az oldalában érzett fájdalom miatt a korlátra támaszkodott ahelyett, hogy tovább futott volna.'::text),
(364989,40555,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super Start: Sie hat versprochen, dass sie sich diesmal nie an ein Geländer ...'::text,'lehnen würde'::text,'lehnen wird'::text,'lehnt'::text,'Super Start: Sie hat versprochen, dass sie sich diesmal nie an ein Geländer lehnen würde.'::text),
(364993,40555,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий початок: вона пообіцяла, що цього разу ... на поруччя.'::text,'ніколи не спиратиметься'::text,'ніколи не спиратиметься'::text,'ніколи не спирається'::text,'Чудовий початок: вона пообіцяла, що цього разу ніколи не спиратиметься на поруччя.'::text),
(364992,40555,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Empezamos genial: prometió que esta vez ... en una barandilla.'::text,'nunca se apoyaría'::text,'nunca se apoyará'::text,'nunca se apoya'::text,'Empezamos genial: prometió que esta vez nunca se apoyaría en una barandilla.'::text),
(364991,40555,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça commence super bien : elle a promis qu''elle ... sur une rambarde cette fois.'::text,'ne s''appuierait jamais'::text,'ne s''appuiera jamais'::text,'ne s''appuie jamais'::text,'Ça commence super bien : elle a promis qu''elle ne s''appuierait jamais sur une rambarde cette fois.'::text),
(364994,40555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika bir başlangıç: bu sefer asla bir korkuluğa ... söz verdi.'::text,'yaslanmayacağına'::text,'yaslanmayacağına'::text,'yaslanmadığına'::text,'Harika bir başlangıç: bu sefer asla bir korkuluğa yaslanmayacağına söz verdi.'::text),
(364995,40555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek kezdés: megígérte, hogy ezúttal ... korlátnak.'::text,'soha nem dől neki'::text,'soha nem fog nekidőlni'::text,'soha nem dől neki'::text,'Remek kezdés: megígérte, hogy ezúttal soha nem dől neki korlátnak.'::text),
(364998,40556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfekte Haltung, ganz klar: Gerade ... sie sich mit verzogenem Gesicht aufs Geländer.'::text,'stützt'::text,'stützt'::text,'hat gestützt'::text,'Perfekte Haltung, ganz klar: Gerade stützt sie sich mit verzogenem Gesicht aufs Geländer.'::text),
(365002,40556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганна форма, звісно: просто зараз вона ... на поруччя зі скривленим обличчям.'::text,'спирається'::text,'спирається'::text,'сперлася'::text,'Бездоганна форма, звісно: просто зараз вона спирається на поруччя зі скривленим обличчям.'::text),
(365001,40556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Forma impecable, obviamente: ahora mismo ... en la barandilla con la cara arrugada.'::text,'se está apoyando'::text,'se apoya'::text,'se ha apoyado'::text,'Forma impecable, obviamente: ahora mismo se está apoyando en la barandilla con la cara arrugada.'::text),
(365000,40556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Forme parfaite, évidemment : là, elle ... sur la rambarde en grimaçant.'::text,'est en train de s''appuyer'::text,'s''appuie'::text,'s''est appuyée'::text,'Forme parfaite, évidemment : là, elle est en train de s''appuyer sur la rambarde en grimaçant.'::text),
(365003,40556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz form, tabii ki: şu anda yüzünü buruşturmuş halde korkuluğa ...'::text,'yaslanıyor'::text,'yaslanır'::text,'yaslandı'::text,'Kusursuz form, tabii ki: şu anda yüzünü buruşturmuş halde korkuluğa yaslanıyor.'::text),
(365004,40556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan forma, nyilván: most épp eltorzult arccal ... a korlátra.'::text,'támaszkodik'::text,'támaszkodik'::text,'támaszkodott'::text,'Hibátlan forma, nyilván: most épp eltorzult arccal támaszkodik a korlátra.'::text),
(365007,40557,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... sich schon zwei ganze Minuten an das Geländer, als ihr Partner sich umdrehte, kein Witz.'::text,'lehnte'::text,'lehnte'::text,'lehnt'::text,'Bro, sie lehnte sich schon zwei ganze Minuten an das Geländer, als ihr Partner sich umdrehte, kein Witz.'::text),
(365011,40557,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона вже цілі дві хвилини ... на те поруччя, коли її партнер обернувся, без жартів.'::text,'спиралася'::text,'спиралася'::text,'спирається'::text,'Бро, вона вже цілі дві хвилини спиралася на те поруччя, коли її партнер обернувся, без жартів.'::text),
(365010,40557,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ya ... dos minutos enteros apoyada en esa barandilla cuando su compañero se dio la vuelta, en serio.'::text,'llevaba'::text,'estaba'::text,'lleva'::text,'Bro, ya llevaba dos minutos enteros apoyada en esa barandilla cuando su compañero se dio la vuelta, en serio.'::text),
(365009,40557,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... sur cette rambarde depuis deux bonnes minutes quand son partenaire s''est retourné, sans mentir.'::text,'s''appuyait'::text,'s''appuyait'::text,'s''appuie'::text,'Frérot, elle s''appuyait sur cette rambarde depuis deux bonnes minutes quand son partenaire s''est retourné, sans mentir.'::text),
(365012,40557,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, partneri arkasını döndüğünde o korkuluğa iki dakikadır ..., yemin ederim.'::text,'yaslanıyordu'::text,'yaslanıyordu'::text,'yaslanıyor'::text,'Kanka, partneri arkasını döndüğünde o korkuluğa iki dakikadır yaslanıyordu, yemin ederim.'::text),
(365013,40557,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, már két teljes perce ... annak a korlátnak, amikor a partnere megfordult, komolyan.'::text,'dőlt neki'::text,'dőlt neki'::text,'dől neki'::text,'Tesó, már két teljes perce dőlt neki annak a korlátnak, amikor a partnere megfordult, komolyan.'::text),
(365016,40558,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, bis zur nächsten Brücke ... sie sich an jedes Geländer der Stadt gelehnt haben, echt jetzt.'::text,'wird'::text,'wird'::text,'lehnt'::text,'Nee Bro, bis zur nächsten Brücke wird sie sich an jedes Geländer der Stadt gelehnt haben, echt jetzt.'::text),
(365020,40558,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, до наступного мосту вона ... на кожне поруччя в місті, чесно.'::text,'встигне спертися'::text,'спиратиметься'::text,'спирається'::text,'Не, бро, до наступного мосту вона встигне спертися на кожне поруччя в місті, чесно.'::text),
(365019,40558,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, bro, para el próximo puente ... en todas las barandillas de la ciudad, en serio.'::text,'se habrá apoyado'::text,'se apoyará'::text,'se está apoyando'::text,'Qué va, bro, para el próximo puente se habrá apoyado en todas las barandillas de la ciudad, en serio.'::text),
(365018,40558,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, d''ici le prochain pont, elle ... sur toutes les rambardes de la ville, sérieux.'::text,'se sera appuyée'::text,'s''appuiera'::text,'s''appuie'::text,'Nan frérot, d''ici le prochain pont, elle se sera appuyée sur toutes les rambardes de la ville, sérieux.'::text),
(365021,40558,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bir sonraki köprüye kadar şehirdeki her korkuluğa ..., cidden.'::text,'yaslanmış olacak'::text,'yaslanacak'::text,'yaslanıyor'::text,'Yok kanka, bir sonraki köprüye kadar şehirdeki her korkuluğa yaslanmış olacak, cidden.'::text),
(365022,40558,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ugyan, tesó, a következő hídig a város minden korlátjának ..., komolyan.'::text,'nekidől majd'::text,'neki fog dőlni'::text,'dől neki'::text,'Ugyan, tesó, a következő hídig a város minden korlátjának nekidől majd, komolyan.'::text),
(332418,36936,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Ende ... die Offizierin ihm so viele Orden verliehen, dass seine Brust voll war. Leicht bescheiden.'::text,'hatte'::text,'hat'::text,'verleiht'::text,'Am Ende hatte die Offizierin ihm so viele Orden verliehen, dass seine Brust voll war. Leicht bescheiden.'::text),
(332422,36936,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зрештою офіцерка ... йому стільки медалей, що в нього були повні груди. Трохи скромно.'::text,'вручила'::text,'вручила'::text,'вручає'::text,'Зрештою офіцерка вручила йому стільки медалей, що в нього були повні груди. Трохи скромно.'::text),
(332421,36936,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final, la oficial le ... tantas medallas que tenía el pecho lleno. Un pelín modesto.'::text,'había concedido'::text,'ha concedido'::text,'concede'::text,'Al final, la oficial le había concedido tantas medallas que tenía el pecho lleno. Un pelín modesto.'::text),
(332420,36936,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À la fin, l''officière lui ... tant de médailles que sa poitrine était pleine. Légèrement modeste.'::text,'avait décerné'::text,'a décerné'::text,'décerne'::text,'À la fin, l''officière lui avait décerné tant de médailles que sa poitrine était pleine. Légèrement modeste.'::text),
(332423,36936,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonunda subay ona o kadar çok madalya ... ki göğsü dolmuştu. Birazcık mütevazı.'::text,'vermişti'::text,'verdi'::text,'veriyor'::text,'Sonunda subay ona o kadar çok madalya vermişti ki göğsü dolmuştu. Birazcık mütevazı.'::text),
(332424,36936,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A végére a tiszt annyi érmet ... neki, hogy tele lett a mellkasa. Kicsit szerény.'::text,'adományozott'::text,'adományozott'::text,'adományoz'::text,'A végére a tiszt annyi érmet adományozott neki, hogy tele lett a mellkasa. Kicsit szerény.'::text),
(332427,36937,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn sie ihm noch einen Orden verleihen, ... er um, kein Witz.'::text,'kippt'::text,'würde kippen'::text,'kippte'::text,'Bro, wenn sie ihm noch einen Orden verleihen, kippt er um, kein Witz.'::text),
(332431,36937,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо йому вручать ще одну медаль, він ..., без жартів.'::text,'впаде'::text,'впав би'::text,'впав'::text,'Бро, якщо йому вручать ще одну медаль, він впаде, без жартів.'::text),
(332430,36937,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si le dan una medalla más, ..., en serio.'::text,'se caerá'::text,'se caería'::text,'se cayó'::text,'Bro, si le dan una medalla más, se caerá, en serio.'::text),
(332429,36937,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, s''ils lui décernent encore une médaille, il ..., sans mentir.'::text,'tombera'::text,'tomberait'::text,'est tombé'::text,'Frérot, s''ils lui décernent encore une médaille, il tombera, sans mentir.'::text),
(332432,36937,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ona bir madalya daha verirlerse ..., yemin ederim.'::text,'devrilecek'::text,'devrilirdi'::text,'devrildi'::text,'Kanka, ona bir madalya daha verirlerse devrilecek, yemin ederim.'::text),
(332433,36937,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha még egy érmet adnak neki, ..., komolyan.'::text,'felborul'::text,'felborulna'::text,'felborult'::text,'Tesó, ha még egy érmet adnak neki, felborul, komolyan.'::text),
(332436,36938,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, wenn sie mir so viele Orden verleihen würden, würde ich das Sakko nie wieder ...'::text,'ausziehen'::text,'ausziehen'::text,'auszog'::text,'Ehrlich gesagt, wenn sie mir so viele Orden verleihen würden, würde ich das Sakko nie wieder ausziehen.'::text),
(332440,36938,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби мені вручили стільки медалей, я ... цей піджак.'::text,'ніколи б не зняв'::text,'ніколи не зніму'::text,'ніколи не знімав'::text,'Чесно, якби мені вручили стільки медалей, я ніколи б не зняв цей піджак.'::text),
