(332441,36938,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bana o kadar madalya verseler ceketi asla ...'::text,'çıkarmazdım'::text,'çıkarmayacağım'::text,'çıkarmadım'::text,'Yalan yok, bana o kadar madalya verseler ceketi asla çıkarmazdım.'::text),
(332442,36938,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ha nekem adnának ennyi érmet, soha ... a zakót.'::text,'nem venném le'::text,'nem fogom levenni'::text,'nem vettem le'::text,'Nem hazudok, ha nekem adnának ennyi érmet, soha nem venném le a zakót.'::text),
