(392785,43643,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти вже ... повз п''ять ліхтарів і досі смієшся.'::text,'пройшла'::text,'ідеш'::text,'ходиш'::text,'Не буду брехати, ти вже пройшла повз п''ять ліхтарів і досі смієшся.'::text),
(392784,43643,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ya ... cinco farolas y sigues riéndote.'::text,'has pasado'::text,'llevas pasando'::text,'pasas'::text,'No voy a mentir, ya has pasado cinco farolas y sigues riéndote.'::text),
(392783,43643,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... déjà devant cinq réverbères, et tu ris encore.'::text,'es passée'::text,'passes'::text,'passes'::text,'Je vais pas mentir, tu es passée déjà devant cinq réverbères, et tu ris encore.'::text),
(392786,43643,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, şimdiden beş sokak lambasının önünden ... ve hâlâ gülüyorsun.'::text,'geçtin'::text,'geçiyorsun'::text,'geçersin'::text,'Yalan yok, şimdiden beş sokak lambasının önünden geçtin ve hâlâ gülüyorsun.'::text),
(392787,43643,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, már öt utcai lámpa mellett ..., és még mindig nevetsz.'::text,'elsétáltál'::text,'sétálsz'::text,'sétálsz'::text,'Nem hazudok, már öt utcai lámpa mellett elsétáltál, és még mindig nevetsz.'::text),
(392790,43644,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, als du am Platz ankamst, war jede Straßenlaterne schon ...'::text,'angegangen'::text,'angegangen'::text,'geht an'::text,'Ehrlich, als du am Platz ankamst, war jede Straßenlaterne schon angegangen.'::text),
(392794,43644,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, поки ти дійшла до площі, кожен ліхтар уже ...'::text,'засвітився'::text,'засвітився'::text,'засвічується'::text,'Чесно, поки ти дійшла до площі, кожен ліхтар уже засвітився.'::text),
(392793,43644,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, para cuando llegaste a la plaza, cada farola ya ...'::text,'se había encendido'::text,'se ha encendido'::text,'se enciende'::text,'Sinceramente, para cuando llegaste a la plaza, cada farola ya se había encendido.'::text),
(392792,43644,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, quand tu es arrivée sur la place, chaque réverbère ...'::text,'s''était allumé'::text,'s''est allumé'::text,'s''allume'::text,'Franchement, quand tu es arrivée sur la place, chaque réverbère s''était allumé.'::text),
(392795,43644,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, meydana vardığında her sokak lambası ...'::text,'yanmıştı'::text,'yandı'::text,'yanıyor'::text,'Açıkçası, meydana vardığında her sokak lambası yanmıştı.'::text),
(392796,43644,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, mire a térre értél, már minden utcai lámpa ...'::text,'felkapcsolódott'::text,'felkapcsolódott'::text,'felkapcsolódik'::text,'Őszintén, mire a térre értél, már minden utcai lámpa felkapcsolódott.'::text),
(392799,43645,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht: Die Stadt ließ jede Straßenlaterne ..., bevor es überhaupt dunkel war.'::text,'einschalten'::text,'einschalten'::text,'einschaltend'::text,'Super gemacht: Die Stadt ließ jede Straßenlaterne einschalten, bevor es überhaupt dunkel war.'::text),
(392803,43645,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота: місто наказало ... кожен ліхтар ще до того, як стемніло.'::text,'увімкнути'::text,'вмикати'::text,'вмикаючи'::text,'Чудова робота: місто наказало увімкнути кожен ліхтар ще до того, як стемніло.'::text),
(392802,43645,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo: el ayuntamiento hizo ... cada farola antes de que siquiera anocheciera.'::text,'encender'::text,'encender'::text,'encendiendo'::text,'Buen trabajo: el ayuntamiento hizo encender cada farola antes de que siquiera anocheciera.'::text),
(392801,43645,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo : la ville a fait ... chaque réverbère avant même qu''il fasse nuit.'::text,'allumer'::text,'allumer'::text,'allumant'::text,'Bravo : la ville a fait allumer chaque réverbère avant même qu''il fasse nuit.'::text),
(392804,43645,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş: belediye daha hava kararmadan her sokak lambasını ...'::text,'yaktırdı'::text,'yaktırdı'::text,'yaktırarak'::text,'Harika iş: belediye daha hava kararmadan her sokak lambasını yaktırdı.'::text),
(392805,43645,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka: a város minden utcai lámpát ..., mielőtt egyáltalán besötétedett.'::text,'felkapcsoltatott'::text,'felkapcsoltatott'::text,'felkapcsoltatva'::text,'Szép munka: a város minden utcai lámpát felkapcsoltatott, mielőtt egyáltalán besötétedett.'::text),
(392808,43646,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünschte, sie ... eine bessere Kamera, um die Straßenlaternen zu filmen.'::text,'hätte'::text,'hat'::text,'wird haben'::text,'Sie wünschte, sie hätte eine bessere Kamera, um die Straßenlaternen zu filmen.'::text),
(392812,43646,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй хотілося б, щоб у неї ... краща камера, щоб знімати ліхтарі.'::text,'була'::text,'є'::text,'буде'::text,'Їй хотілося б, щоб у неї була краща камера, щоб знімати ліхтарі.'::text),
(392811,43646,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ojalá ... una cámara mejor para grabar las farolas.'::text,'tuviera'::text,'tiene'::text,'tendrá'::text,'Ojalá tuviera una cámara mejor para grabar las farolas.'::text),
(392810,43646,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait ... une meilleure caméra pour filmer les réverbères.'::text,'avoir'::text,'a'::text,'aura'::text,'Elle aimerait avoir une meilleure caméra pour filmer les réverbères.'::text),
(392813,43646,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke sokak lambalarını çekmek için daha iyi bir kamerası ... diye düşünüyor.'::text,'olsa'::text,'var'::text,'olacak'::text,'Keşke sokak lambalarını çekmek için daha iyi bir kamerası olsa diye düşünüyor.'::text),
(392814,43646,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt szeretné, ha jobb kamerája ..., hogy lefilmezze az utcai lámpákat.'::text,'lenne'::text,'van'::text,'lesz'::text,'Azt szeretné, ha jobb kamerája lenne, hogy lefilmezze az utcai lámpákat.'::text),
(392817,43647,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Straßenlaterne, ... orangefarbenes Licht auf die Straße fällt, steht hinter ihr.'::text,'deren'::text,'die'::text,'welche'::text,'Die Straßenlaterne, deren orangefarbenes Licht auf die Straße fällt, steht hinter ihr.'::text),
(392821,43647,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вуличний ліхтар, ... помаранчеве світло падає на дорогу, стоїть позаду неї.'::text,'чиє'::text,'який'::text,'що'::text,'Вуличний ліхтар, чиє помаранчеве світло падає на дорогу, стоїть позаду неї.'::text),
(392820,43647,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La farola, ... resplandor naranja cae sobre la calle, está detrás de ella.'::text,'cuyo'::text,'que'::text,'la cual'::text,'La farola, cuyo resplandor naranja cae sobre la calle, está detrás de ella.'::text),
(392819,43647,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le réverbère, ... la lueur orange tombe sur la route, se dresse derrière elle.'::text,'dont'::text,'qui'::text,'que'::text,'Le réverbère, dont la lueur orange tombe sur la route, se dresse derrière elle.'::text),
(392822,43647,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Turuncu ışığı yola ... sokak lambası onun arkasında duruyor.'::text,'düşen'::text,'hangi'::text,'ki'::text,'Turuncu ışığı yola düşen sokak lambası onun arkasında duruyor.'::text),
(392823,43647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utcai lámpa, ... narancssárga fénye az útra esik, mögötte áll.'::text,'amelynek'::text,'amely'::text,'ami'::text,'Az utcai lámpa, amelynek narancssárga fénye az útra esik, mögötte áll.'::text),
(392826,43648,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gehen in den meisten Städten in der Dämmerung an.'::text,'Straßenlaternen'::text,'Die Straßenlaternen'::text,'Eine Straßenlaterne'::text,'Straßenlaternen gehen in den meisten Städten in der Dämmerung an.'::text),
(392830,43648,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У більшості міст ... вмикаються в сутінках.'::text,'вуличні ліхтарі'::text,'вуличні ліхтарі'::text,'вуличні ліхтарі'::text,'У більшості міст вуличні ліхтарі вмикаються в сутінках.'::text),
(392829,43648,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la mayoría de las ciudades, ... se encienden al anochecer.'::text,'las farolas'::text,'las farolas'::text,'una farola'::text,'En la mayoría de las ciudades, las farolas se encienden al anochecer.'::text),
(392828,43648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans la plupart des villes, ... s''allument au crépuscule.'::text,'les réverbères'::text,'les réverbères'::text,'un réverbère'::text,'Dans la plupart des villes, les réverbères s''allument au crépuscule.'::text),
(392831,43648,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çoğu şehirde ... alacakaranlıkta yanar.'::text,'sokak lambaları'::text,'sokak lambaları'::text,'bir sokak lambası'::text,'Çoğu şehirde sokak lambaları alacakaranlıkta yanar.'::text),
(392832,43648,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legtöbb városban ... szürkületkor felkapcsolódnak.'::text,'az utcai lámpák'::text,'az utcai lámpák'::text,'egy utcai lámpa'::text,'A legtöbb városban az utcai lámpák szürkületkor felkapcsolódnak.'::text),
(392844,43650,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 2030 wird die Stadt laut Roadmap jede Straßenlaterne hier ...'::text,'ersetzt haben'::text,'ersetzen'::text,'ersetzt'::text,'Bis 2030 wird die Stadt laut Roadmap jede Straßenlaterne hier ersetzt haben.'::text),
(392848,43650,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 2030 року, як сказано в дорожній карті, місто ... тут кожен ліхтар.'::text,'замінить'::text,'замінюватиме'::text,'замінює'::text,'До 2030 року, як сказано в дорожній карті, місто замінить тут кожен ліхтар.'::text),
(392847,43650,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para 2030, según la hoja de ruta, la ciudad ... todas las farolas de aquí.'::text,'habrá sustituido'::text,'sustituirá'::text,'está sustituyendo'::text,'Para 2030, según la hoja de ruta, la ciudad habrá sustituido todas las farolas de aquí.'::text),
(392846,43650,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici 2030, selon la feuille de route, la ville ... chaque réverbère ici.'::text,'aura remplacé'::text,'remplacera'::text,'remplace'::text,'D''ici 2030, selon la feuille de route, la ville aura remplacé chaque réverbère ici.'::text),
(392849,43650,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yol haritasına göre 2030''a kadar belediye buradaki her sokak lambasını ...'::text,'değiştirmiş olacak'::text,'değiştirecek'::text,'değiştiriyor'::text,'Yol haritasına göre 2030''a kadar belediye buradaki her sokak lambasını değiştirmiş olacak.'::text),
(392850,43650,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'2030-ra, ahogy az ütemterv mondja, a város itt minden utcai lámpát ...'::text,'le fog cserélni'::text,'lecserél majd'::text,'cseréli'::text,'2030-ra, ahogy az ütemterv mondja, a város itt minden utcai lámpát le fog cserélni.'::text),
(356727,39637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... mit einem Bleistift zwischen den Zähnen, als der Frust kam. Ikonisch.'::text,'tipptest'::text,'hast getippt'::text,'hast getippt'::text,'Ehrlich gesagt, du tipptest mit einem Bleistift zwischen den Zähnen, als der Frust kam. Ikonisch.'::text),
(356731,39637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ... з олівцем у зубах, коли накрила фрустрація. Культово.'::text,'друкувала'::text,'надрукувала'::text,'надрукувала'::text,'Не буду брехати, ти друкувала з олівцем у зубах, коли накрила фрустрація. Культово.'::text),
(356730,39637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ... con un lápiz entre los dientes cuando llegó la frustración. Icónico.'::text,'estabas escribiendo'::text,'escribiste'::text,'has escrito'::text,'No voy a mentir, estabas escribiendo con un lápiz entre los dientes cuando llegó la frustración. Icónico.'::text),
(356729,39637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... avec un crayon entre les dents quand la frustration est arrivée. Iconique.'::text,'tapais'::text,'as tapé'::text,'as tapé'::text,'Je vais pas mentir, tu tapais avec un crayon entre les dents quand la frustration est arrivée. Iconique.'::text),
(356732,39637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, hayal kırıklığı bastırdığında dişlerinin arasında kalemle ..., efsaneydi.'::text,'yazıyordun'::text,'yazdın'::text,'yazdın'::text,'Yalan yok, hayal kırıklığı bastırdığında dişlerinin arasında kalemle yazıyordun, efsaneydi.'::text),
(356733,39637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ceruzával a fogaid között ..., amikor rád tört a frusztráció. Ikonikus.'::text,'gépeltél'::text,'begépelted'::text,'gépeltél'::text,'Nem hazudok, ceruzával a fogaid között gépeltél, amikor rád tört a frusztráció. Ikonikus.'::text),
(356736,39638,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... die ganze Nacht mit diesem Frust, und du tippst immer noch. Respekt.'::text,'kämpfst'::text,'kämpftest'::text,'kämpfst'::text,'Ehrlich, du kämpfst die ganze Nacht mit diesem Frust, und du tippst immer noch. Respekt.'::text),
(356740,39638,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... з цією фрустрацією всю ніч і досі друкуєш. Респект.'::text,'борешся'::text,'боролася'::text,'борешся'::text,'Чесно, ти борешся з цією фрустрацією всю ніч і досі друкуєш. Респект.'::text),
(356739,39638,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... con esta frustración toda la noche y sigues escribiendo. Respeto.'::text,'has estado luchando'::text,'luchaste'::text,'estás luchando'::text,'Sinceramente, has estado luchando con esta frustración toda la noche y sigues escribiendo. Respeto.'::text),
(356738,39638,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... contre cette frustration toute la nuit, et tu tapes encore. Respect.'::text,'luttes'::text,'as lutté'::text,'es en train de lutter'::text,'Franchement, tu luttes contre cette frustration toute la nuit, et tu tapes encore. Respect.'::text),
(356741,39638,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bütün gece bu hayal kırıklığıyla ... ve hâlâ yazıyorsun. Saygı.'::text,'savaşıyorsun'::text,'savaştın'::text,'savaşıyorsun'::text,'Açıkçası bütün gece bu hayal kırıklığıyla savaşıyorsun ve hâlâ yazıyorsun. Saygı.'::text),
(356742,39638,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, egész éjjel ... ezzel a frusztrációval, és még mindig gépelsz. Respekt.'::text,'küzdesz'::text,'küzdöttél'::text,'küzdesz'::text,'Őszintén, egész éjjel küzdesz ezzel a frusztrációval, és még mindig gépelsz. Respekt.'::text),
(356745,39639,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du den ganzen Frust in deine Arbeit ..., wird sie ehrlich genial.'::text,'steckst'::text,'stecken wirst'::text,'stecktest'::text,'Wenn du den ganzen Frust in deine Arbeit steckst, wird sie ehrlich genial.'::text),
(356749,39639,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти ... всю цю фрустрацію в роботу, це чесно буде геніально.'::text,'вкладеш'::text,'вкладатимеш'::text,'вклала'::text,'Якщо ти вкладеш всю цю фрустрацію в роботу, це чесно буде геніально.'::text),
(356748,39639,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... toda esa frustración en tu trabajo, sinceramente quedará brillante.'::text,'canalizas'::text,'canalizarás'::text,'canalizaste'::text,'Si canalizas toda esa frustración en tu trabajo, sinceramente quedará brillante.'::text),
(356747,39639,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu ... toute cette frustration dans ton travail, franchement ce sera génial.'::text,'mets'::text,'mettras'::text,'mettais'::text,'Si tu mets toute cette frustration dans ton travail, franchement ce sera génial.'::text),
(356750,39639,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün o hayal kırıklığını işine ..., açıkçası harika olacak.'::text,'yansıtırsan'::text,'yansıtacaksan'::text,'yansıttıysan'::text,'Bütün o hayal kırıklığını işine yansıtırsan, açıkçası harika olacak.'::text),
(356751,39639,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha azt a sok frusztrációt a munkádba ..., őszintén zseniális lesz.'::text,'fekteted'::text,'fogod fektetni'::text,'fektetted'::text,'Ha azt a sok frusztrációt a munkádba fekteted, őszintén zseniális lesz.'::text),
(356754,39640,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich eine ruhige Nacht: Wenn ihr Frust noch lauter ..., würden sich die Nachbarn beschweren.'::text,'würde'::text,'wird'::text,'werden wird'::text,'Offensichtlich eine ruhige Nacht: Wenn ihr Frust noch lauter würde, würden sich die Nachbarn beschweren.'::text),
(356758,39640,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, спокійна ніч: якби її фрустрація ... ще гучнішою, сусіди б поскаржилися.'::text,'стала'::text,'стає'::text,'стане'::text,'Очевидно, спокійна ніч: якби її фрустрація стала ще гучнішою, сусіди б поскаржилися.'::text),
(356757,39640,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente una noche tranquila: si su frustración ... más ruidosa, los vecinos se quejarían.'::text,'se volviera'::text,'se vuelve'::text,'se volverá'::text,'Obviamente una noche tranquila: si su frustración se volviera más ruidosa, los vecinos se quejarían.'::text),
(356756,39640,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment une nuit calme : si sa frustration ... plus bruyante, les voisins se plaindraient.'::text,'devenait'::text,'devient'::text,'deviendra'::text,'Évidemment une nuit calme : si sa frustration devenait plus bruyante, les voisins se plaindraient.'::text),
(356759,39640,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki sakin bir gece: hayal kırıklığı daha da gürültülü ..., komşular şikâyet ederdi.'::text,'olsa'::text,'oluyorsa'::text,'olacaksa'::text,'Belli ki sakin bir gece: hayal kırıklığı daha da gürültülü olsa, komşular şikâyet ederdi.'::text),
(356760,39640,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván nyugis éjszaka: ha a frusztrációja még hangosabb ..., a szomszédok panaszkodnának.'::text,'lenne'::text,'lesz'::text,'lesz majd'::text,'Nyilván nyugis éjszaka: ha a frusztrációja még hangosabb lenne, a szomszédok panaszkodnának.'::text),
(356763,39641,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine perfekte Nacht, offensichtlich: Ihr Frust ... um Mitternacht vom ganzen Haus gehört.'::text,'wurde'::text,'hat'::text,'wird'::text,'Eine perfekte Nacht, offensichtlich: Ihr Frust wurde um Mitternacht vom ganzen Haus gehört.'::text),
(356767,39641,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганна ніч, очевидно: її фрустрацію опівночі ... на весь будинок.'::text,'було чути'::text,'почула'::text,'чути'::text,'Бездоганна ніч, очевидно: її фрустрацію опівночі було чути на весь будинок.'::text),
(356766,39641,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una noche perfecta, obviamente: su frustración ... en todo el edificio a medianoche.'::text,'se oyó'::text,'oyó'::text,'se oye'::text,'Una noche perfecta, obviamente: su frustración se oyó en todo el edificio a medianoche.'::text),
(356765,39641,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une nuit parfaite, évidemment : sa frustration ... par tout l''immeuble à minuit.'::text,'a été entendue'::text,'a entendu'::text,'est entendue'::text,'Une nuit parfaite, évidemment : sa frustration a été entendue par tout l''immeuble à minuit.'::text),
(356768,39641,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz bir gece, belli ki: hayal kırıklığı gece yarısı bütün binada ...'::text,'duyuldu'::text,'duydu'::text,'duyuluyor'::text,'Kusursuz bir gece, belli ki: hayal kırıklığı gece yarısı bütün binada duyuldu.'::text),
(356769,39641,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván hibátlan éjszaka: a frusztrációját éjfélkor az egész ház ...'::text,'hallotta'::text,'hallotta'::text,'hallja'::text,'Nyilván hibátlan éjszaka: a frusztrációját éjfélkor az egész ház hallotta.'::text),
(356772,39642,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Frust ..., als sie das Blatt Papier las.'::text,'wuchs'::text,'wurde gesteigert'::text,'wachsend'::text,'Ihr Frust wuchs, als sie das Blatt Papier las.'::text),
(356776,39642,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її фрустрація ..., коли вона прочитала аркуш паперу.'::text,'зросла'::text,'була вирощена'::text,'зростаючи'::text,'Її фрустрація зросла, коли вона прочитала аркуш паперу.'::text),
(356775,39642,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su frustración ... cuando leyó la hoja de papel.'::text,'creció'::text,'fue cultivada'::text,'creciendo'::text,'Su frustración creció cuando leyó la hoja de papel.'::text),
(356774,39642,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa frustration ... quand elle a lu la feuille de papier.'::text,'a grandi'::text,'a été cultivée'::text,'grandissant'::text,'Sa frustration a grandi quand elle a lu la feuille de papier.'::text),
(356777,39642,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâğıdı okuduğunda hayal kırıklığı ...'::text,'büyüdü'::text,'büyütüldü'::text,'büyüyerek'::text,'Kâğıdı okuduğunda hayal kırıklığı büyüdü.'::text),
(356778,39642,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A frusztrációja ..., amikor elolvasta a papírlapot.'::text,'nőtt'::text,'termesztették'::text,'növekedve'::text,'A frusztrációja nőtt, amikor elolvasta a papírlapot.'::text),
(356790,39644,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Blatt Papier, ... sie las, löste bei ihr plötzlichen Frust aus.'::text,'das'::text,'wer'::text,'dessen'::text,'Das Blatt Papier, das sie las, löste bei ihr plötzlichen Frust aus.'::text),
(356794,39644,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Аркуш паперу, ... вона прочитала, викликав у неї раптову фрустрацію.'::text,'який'::text,'хто'::text,'чий'::text,'Аркуш паперу, який вона прочитала, викликав у неї раптову фрустрацію.'::text),
(356793,39644,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La hoja de papel ... leyó le provocó una frustración repentina.'::text,'que'::text,'quien'::text,'cuya'::text,'La hoja de papel que leyó le provocó una frustración repentina.'::text),
(356792,39644,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La feuille de papier ... a provoqué sa frustration soudaine.'::text,'qu''elle a lue'::text,'qui a lu'::text,'dont elle a lu'::text,'La feuille de papier qu''elle a lue a provoqué sa frustration soudaine.'::text),
(356795,39644,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kâğıt parçası ona ani bir hayal kırıklığı yaşattı.'::text,'Okuduğu'::text,'Kim'::text,'Kimin'::text,'Okuduğu kâğıt parçası ona ani bir hayal kırıklığı yaşattı.'::text),
(356796,39644,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A papírlap, ... elolvasott, hirtelen frusztrációt okozott neki.'::text,'amelyet'::text,'aki'::text,'amelynek'::text,'A papírlap, amelyet elolvasott, hirtelen frusztrációt okozott neki.'::text),
(356799,39645,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte ihrem Team, dass ihr Frust nach der Deadline um 9 Uhr ...'::text,'enden würde'::text,'enden wird'::text,'endet'::text,'Sie sagte ihrem Team, dass ihr Frust nach der Deadline um 9 Uhr enden würde.'::text),
(356803,39645,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала команді, що її фрустрація ... після дедлайну о 9:00.'::text,'закінчиться'::text,'закінчиться'::text,'закінчується'::text,'Вона сказала команді, що її фрустрація закінчиться після дедлайну о 9:00.'::text),
(356802,39645,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dijo a su equipo que su frustración ... después del plazo de las 9:00.'::text,'terminaría'::text,'terminará'::text,'termina'::text,'Le dijo a su equipo que su frustración terminaría después del plazo de las 9:00.'::text),
(356801,39645,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit à son équipe que sa frustration ... après la deadline de 9 h.'::text,'prendrait fin'::text,'prendra fin'::text,'prend fin'::text,'Elle a dit à son équipe que sa frustration prendrait fin après la deadline de 9 h.'::text),
(356804,39645,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekibine hayal kırıklığının saat 9''daki teslim tarihinden sonra ... söyledi.'::text,'biteceğini'::text,'biteceğini'::text,'bittiğini'::text,'Ekibine hayal kırıklığının saat 9''daki teslim tarihinden sonra biteceğini söyledi.'::text),
(356805,39645,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta a csapatának, hogy a frusztrációja a reggel 9-es határidő után ...'::text,'véget ér majd'::text,'véget fog érni'::text,'véget ér'::text,'Azt mondta a csapatának, hogy a frusztrációja a reggel 9-es határidő után véget ér majd.'::text),
(356808,39646,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Frust ... früher leiser, weil sie damals nicht geschrien hat.'::text,'war'::text,'war'::text,'war gewohnt zu sein'::text,'Ihr Frust war früher leiser, weil sie damals nicht geschrien hat.'::text),
(356812,39646,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її фрустрація колись ... тихішою, бо тоді вона не кричала.'::text,'бувала'::text,'бувала'::text,'звикла бути'::text,'Її фрустрація колись бувала тихішою, бо тоді вона не кричала.'::text),
(356811,39646,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su frustración ... ser más silenciosa, porque entonces no gritaba.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Su frustración solía ser más silenciosa, porque entonces no gritaba.'::text),
(356810,39646,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, sa frustration ... plus discrète, parce qu''à l''époque elle ne criait pas.'::text,'était'::text,'était'::text,'avait l''habitude d''être'::text,'Avant, sa frustration était plus discrète, parce qu''à l''époque elle ne criait pas.'::text),
(356813,39646,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayal kırıklığı eskiden daha sessiz ..., çünkü o zamanlar bağırmıyordu.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Hayal kırıklığı eskiden daha sessiz olurdu, çünkü o zamanlar bağırmıyordu.'::text),
(356814,39646,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A frusztrációja régen csendesebb ..., mert akkoriban nem kiabált.'::text,'volt'::text,'volt'::text,'volt hozzászokva'::text,'A frusztrációja régen csendesebb volt, mert akkoriban nem kiabált.'::text),
(372603,41401,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, morgen um diese Zeit ... du diesen Papierkram mit derselben ruhigen Sicherheit.'::text,'machst'::text,'wirst machen'::text,'machst'::text,'Ehrlich, morgen um diese Zeit machst du diesen Papierkram mit derselben ruhigen Sicherheit.'::text),
(372607,41401,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, завтра в цей час ти ... цю паперову роботу з такою ж спокійною впевненістю.'::text,'робитимеш'::text,'зробиш'::text,'робиш'::text,'Чесно, завтра в цей час ти робитимеш цю паперову роботу з такою ж спокійною впевненістю.'::text),
(372606,41401,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, mañana a esta hora ... este papeleo con la misma seguridad tranquila.'::text,'estarás haciendo'::text,'harás'::text,'haces'::text,'Sinceramente, mañana a esta hora estarás haciendo este papeleo con la misma seguridad tranquila.'::text),
(372605,41401,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, demain à la même heure, tu ... cette paperasse avec la même assurance tranquille.'::text,'seras en train de faire'::text,'feras'::text,'fais'::text,'Franchement, demain à la même heure, tu seras en train de faire cette paperasse avec la même assurance tranquille.'::text),
(372608,41401,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, yarın bu saatlerde bu evrak işini aynı sakin özgüvenle ...'::text,'yapıyor olacaksın'::text,'yapacaksın'::text,'yapıyorsun'::text,'Açıkçası, yarın bu saatlerde bu evrak işini aynı sakin özgüvenle yapıyor olacaksın.'::text),
(372609,41401,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, holnap ilyenkor ugyanazzal a nyugodt magabiztossággal ... ezt a papírmunkát.'::text,'fogod intézni'::text,'intézed majd'::text,'intézed'::text,'Őszintén, holnap ilyenkor ugyanazzal a nyugodt magabiztossággal fogod intézni ezt a papírmunkát.'::text),
(372612,41402,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genau das, was sie brauchte: Ihr Chef verspricht, dass der Papierkram morgen weniger ...'::text,'wird'::text,'werden wird'::text,'wird gerade'::text,'Genau das, was sie brauchte: Ihr Chef verspricht, dass der Papierkram morgen weniger wird.'::text),
(372616,41402,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме те, що їй було треба: бос обіцяє, що завтра паперової роботи ... менше.'::text,'стане'::text,'ставатиме'::text,'стає'::text,'Саме те, що їй було треба: бос обіцяє, що завтра паперової роботи стане менше.'::text),
(372615,41402,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Justo lo que necesitaba: su jefe le promete que mañana el papeleo ...'::text,'se reducirá'::text,'se estará reduciendo'::text,'se está reduciendo'::text,'Justo lo que necesitaba: su jefe le promete que mañana el papeleo se reducirá.'::text),
(372614,41402,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Exactement ce qu''il lui fallait : son chef promet que la paperasse ... demain.'::text,'diminuera'::text,'sera en train de diminuer'::text,'diminue'::text,'Exactement ce qu''il lui fallait : son chef promet que la paperasse diminuera demain.'::text),
(372617,41402,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam da ihtiyacı olan şey: patronu evrak işinin yarın ... söz veriyor.'::text,'azalacağına'::text,'azalıyor olacağına'::text,'azaldığına'::text,'Tam da ihtiyacı olan şey: patronu evrak işinin yarın azalacağına söz veriyor.'::text),
(372618,41402,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pont erre volt szüksége: a főnöke megígéri, hogy holnap a papírmunka ...'::text,'csökkenni fog'::text,'épp csökkenni fog'::text,'csökken'::text,'Pont erre volt szüksége: a főnöke megígéri, hogy holnap a papírmunka csökkenni fog.'::text),
(372630,41404,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie genießt es offensichtlich, Papierkram ..., bis er sich über ihrem Kopf stapelt.'::text,'zu erledigen'::text,'zu erledigen'::text,'erledigen'::text,'Sie genießt es offensichtlich, Papierkram zu erledigen, bis er sich über ihrem Kopf stapelt.'::text),
(372634,41404,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй явно подобається ... паперову роботу, поки та не виросте вище її голови.'::text,'робити'::text,'робити'::text,'робить'::text,'Їй явно подобається робити паперову роботу, поки та не виросте вище її голови.'::text),
(372633,41404,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que disfruta ... papeleo hasta que le llega por encima de la cabeza.'::text,'haciendo'::text,'hacer'::text,'hace'::text,'Está claro que disfruta haciendo papeleo hasta que le llega por encima de la cabeza.'::text),
(372632,41404,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle adore clairement ... de la paperasse jusqu''à ce qu''elle s''empile au-dessus de sa tête.'::text,'faire'::text,'faire'::text,'fait'::text,'Elle adore clairement faire de la paperasse jusqu''à ce qu''elle s''empile au-dessus de sa tête.'::text),
(372635,41404,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki evrak işi başının üstüne yığılana kadar ... seviyor.'::text,'yapmayı'::text,'yapmayı'::text,'yapar'::text,'Belli ki evrak işi başının üstüne yığılana kadar yapmayı seviyor.'::text),
(372636,41404,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Láthatóan élvezi ... a papírmunkát, amíg az a feje fölé nem tornyosul.'::text,'intézni'::text,'intézni'::text,'intézi'::text,'Láthatóan élvezi intézni a papírmunkát, amíg az a feje fölé nem tornyosul.'::text),
(372639,41405,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Papierkram stapelt sich immer weiter um ihren Schreibtisch, ...'::text,'oder?'::text,'nicht wahr?'::text,'oder?'::text,'Der Papierkram stapelt sich immer weiter um ihren Schreibtisch, oder?'::text),
(372643,41405,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Паперова робота постійно накопичується навколо її столу, ...'::text,'чи не так?'::text,'правда?'::text,'так?'::text,'Паперова робота постійно накопичується навколо її столу, чи не так?'::text),
(372642,41405,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El papeleo no para de acumularse alrededor de su escritorio, ...'::text,'¿verdad?'::text,'¿no?'::text,'¿verdad?'::text,'El papeleo no para de acumularse alrededor de su escritorio, ¿verdad?'::text),
(372641,41405,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La paperasse n''arrête pas de s''empiler autour de son bureau, ...'::text,'n''est-ce pas ?'::text,'hein ?'::text,'pas vrai ?'::text,'La paperasse n''arrête pas de s''empiler autour de son bureau, n''est-ce pas ?'::text),
(372644,41405,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evrak işi masasının etrafında birikip duruyor, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Evrak işi masasının etrafında birikip duruyor, değil mi?'::text),
(372645,41405,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A papírmunka egyre csak halmozódik az asztala körül, ...'::text,'ugye?'::text,'nem?'::text,'igaz?'::text,'A papírmunka egyre csak halmozódik az asztala körül, ugye?'::text),
(372648,41406,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat den Papierkram satt, und ihre Kollegen ...'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Sie hat den Papierkram satt, und ihre Kollegen auch.'::text),
(372652,41406,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона втомилася від паперової роботи, і її колеги ...'::text,'теж'::text,'теж'::text,'теж ні'::text,'Вона втомилася від паперової роботи, і її колеги теж.'::text),
(372651,41406,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está harta del papeleo, y sus compañeros ...'::text,'también'::text,'también'::text,'tampoco'::text,'Está harta del papeleo, y sus compañeros también.'::text),
(372650,41406,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle en a marre de la paperasse, et ses collègues ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Elle en a marre de la paperasse, et ses collègues aussi.'::text),
(372653,41406,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evrak işinden bıkmış, iş arkadaşları ...'::text,'da öyle'::text,'da öyle'::text,'da değil'::text,'Evrak işinden bıkmış, iş arkadaşları da öyle.'::text),
(372654,41406,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elege van a papírmunkából, és a kollégáinak ...'::text,'is'::text,'is'::text,'sem'::text,'Elege van a papírmunkából, és a kollégáinak is.'::text),
(372657,41407,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Freitag wird sie den ganzen Papierkram auf ihrem Schreibtisch ...'::text,'erledigt haben'::text,'erledigen'::text,'erledigen'::text,'Bis Freitag wird sie den ganzen Papierkram auf ihrem Schreibtisch erledigt haben.'::text),
(372661,41407,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До п''ятниці вона ... всю паперову роботу на своєму столі.'::text,'закінчить'::text,'закінчить'::text,'закінчуватиме'::text,'До п''ятниці вона закінчить всю паперову роботу на своєму столі.'::text),
(372660,41407,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el viernes, ... todo el papeleo de su escritorio.'::text,'habrá terminado'::text,'terminará'::text,'estará terminando'::text,'Para el viernes, habrá terminado todo el papeleo de su escritorio.'::text),
(372659,41407,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici vendredi, elle ... toute la paperasse sur son bureau.'::text,'aura terminé'::text,'terminera'::text,'sera en train de terminer'::text,'D''ici vendredi, elle aura terminé toute la paperasse sur son bureau.'::text),
(372662,41407,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cumaya kadar masasındaki bütün evrak işini ...'::text,'bitirmiş olacak'::text,'bitirecek'::text,'bitiriyor olacak'::text,'Cumaya kadar masasındaki bütün evrak işini bitirmiş olacak.'::text),
(372663,41407,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Péntekre ... az összes papírmunkát az asztalán.'::text,'befejezi'::text,'be fogja fejezni'::text,'fogja befejezni'::text,'Péntekre befejezi az összes papírmunkát az asztalán.'::text),
(372675,41409,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Subjekt bestritt, mit dem Papierkram in Rückstand ..., doch die Stapel deuten auf das Gegenteil hin.'::text,'geraten zu sein'::text,'zu geraten'::text,'geriet'::text,'Das Subjekt bestritt, mit dem Papierkram in Rückstand geraten zu sein, doch die Stapel deuten auf das Gegenteil hin.'::text),
(372679,41409,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт заперечив ... з паперовою роботою, однак стоси свідчать про протилежне.'::text,'відставання'::text,'відставати'::text,'відстав'::text,'Суб''єкт заперечив відставання з паперовою роботою, однак стоси свідчать про протилежне.'::text),
(372678,41409,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto negó ... con el papeleo, pero las pilas indican lo contrario.'::text,'haberse retrasado'::text,'retrasarse'::text,'se retrasó'::text,'El sujeto negó haberse retrasado con el papeleo, pero las pilas indican lo contrario.'::text),
(372677,41409,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet a nié ... du retard dans sa paperasse, pourtant les piles indiquent le contraire.'::text,'avoir pris'::text,'prendre'::text,'a pris'::text,'Le sujet a nié avoir pris du retard dans sa paperasse, pourtant les piles indiquent le contraire.'::text),
(372680,41409,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Özne evrak işinde ... inkâr etti, ancak yığınlar aksini gösteriyor.'::text,'geride kaldığını'::text,'geride kalmayı'::text,'geride kaldı'::text,'Özne evrak işinde geride kaldığını inkâr etti, ancak yığınlar aksini gösteriyor.'::text),
(372681,41409,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany tagadta, hogy ... a papírmunkával, a halmok azonban mást jeleznek.'::text,'lemaradt'::text,'lemaradni'::text,'lemaradt'::text,'Az alany tagadta, hogy lemaradt a papírmunkával, a halmok azonban mást jeleznek.'::text),
(372684,41410,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, gerade ... du Papierkram und ein Telefonat gleichzeitig.'::text,'stemmst'::text,'stemmst'::text,'hast gestemmt'::text,'Ehrlich gesagt, gerade stemmst du Papierkram und ein Telefonat gleichzeitig.'::text),
(372688,41410,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, просто зараз ти ... і з паперами, і з дзвінком одночасно.'::text,'справляєшся'::text,'справляєшся'::text,'впоралася'::text,'Не буду брехати, просто зараз ти справляєшся і з паперами, і з дзвінком одночасно.'::text),
(372687,41410,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ahora mismo ... papeleo y una llamada a la vez.'::text,'estás llevando'::text,'llevas'::text,'has llevado'::text,'No voy a mentir, ahora mismo estás llevando papeleo y una llamada a la vez.'::text),
(372686,41410,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, là tout de suite, tu ... la paperasse et un appel en même temps.'::text,'gères'::text,'gères'::text,'as géré'::text,'Je vais pas mentir, là tout de suite, tu gères la paperasse et un appel en même temps.'::text),
(372689,41410,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, şu anda evrak işini ve bir telefon görüşmesini aynı anda ...'::text,'idare ediyorsun'::text,'idare edersin'::text,'idare ettin'::text,'Yalan yok, şu anda evrak işini ve bir telefon görüşmesini aynı anda idare ediyorsun.'::text),
(372690,41410,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, most épp egyszerre ... a papírmunkát és egy telefonhívást.'::text,'intézed'::text,'intézed'::text,'intézted'::text,'Nem hazudok, most épp egyszerre intézed a papírmunkát és egy telefonhívást.'::text),
(372693,41411,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als du das Telefon aufgelegt hast, ... du schon seit sechs Stunden Papierkram. Respekt.'::text,'machtest'::text,'machtest'::text,'machst'::text,'Als du das Telefon aufgelegt hast, machtest du schon seit sechs Stunden Papierkram. Respekt.'::text),
(372697,41411,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли ти поклала слухавку, ти вже шість годин ... паперову роботу. Респект.'::text,'робила'::text,'робила'::text,'робиш'::text,'Коли ти поклала слухавку, ти вже шість годин робила паперову роботу. Респект.'::text),
(372696,41411,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando colgaste el teléfono, ya ... seis horas haciendo papeleo. Respeto.'::text,'llevabas'::text,'estabas'::text,'llevas'::text,'Cuando colgaste el teléfono, ya llevabas seis horas haciendo papeleo. Respeto.'::text),
(372695,41411,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand tu as raccroché, tu ... de la paperasse depuis six heures. Respect.'::text,'faisais'::text,'faisais'::text,'fais'::text,'Quand tu as raccroché, tu faisais de la paperasse depuis six heures. Respect.'::text),
(372698,41411,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefonu kapattığında altı saattir evrak işi ..., saygı.'::text,'yapıyordun'::text,'yapıyordun'::text,'yapıyorsun'::text,'Telefonu kapattığında altı saattir evrak işi yapıyordun, saygı.'::text),
(372699,41411,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire letetted a telefont, már hat órája ... a papírmunkát. Respekt.'::text,'intézted'::text,'intézted'::text,'intézed'::text,'Mire letetted a telefont, már hat órája intézted a papírmunkát. Respekt.'::text),
(398037,44227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du weiter so leitest, ... du die beste Trainerin im Park.'::text,'bist'::text,'wärst'::text,'warst'::text,'Ehrlich, wenn du weiter so leitest, bist du die beste Trainerin im Park.'::text),
(398041,44227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якщо ти й далі так вестимеш, ти ... найкращою тренеркою в парку.'::text,'будеш'::text,'була б'::text,'була'::text,'Чесно, якщо ти й далі так вестимеш, ти будеш найкращою тренеркою в парку.'::text),
(398040,44227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si sigues liderando así, ... la mejor entrenadora del parque.'::text,'serás'::text,'serías'::text,'eras'::text,'Sinceramente, si sigues liderando así, serás la mejor entrenadora del parque.'::text),
(398039,44227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu continues à mener comme ça, tu ... la meilleure coach du parc.'::text,'seras'::text,'serais'::text,'étais'::text,'Franchement, si tu continues à mener comme ça, tu seras la meilleure coach du parc.'::text),
(398042,44227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, böyle yönetmeye devam edersen parktaki en iyi eğitmen ...'::text,'olacaksın'::text,'olurdun'::text,'idin'::text,'Açıkçası, böyle yönetmeye devam edersen parktaki en iyi eğitmen olacaksın.'::text),
(398043,44227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha így vezeted tovább, te ... a legjobb edző a parkban.'::text,'leszel'::text,'lennél'::text,'voltál'::text,'Őszintén, ha így vezeted tovább, te leszel a legjobb edző a parkban.'::text),
(398046,44228,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich eine Trainerin wie dich hätte, ... ich mich jeden Morgen dehnen, ehrlich.'::text,'würde'::text,'werde'::text,'dehne'::text,'Wenn ich eine Trainerin wie dich hätte, würde ich mich jeden Morgen dehnen, ehrlich.'::text),
(398050,44228,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в мене була така тренерка, як ти, я ... щоранку, чесно.'::text,'б розтягувався'::text,'розтягуватимусь'::text,'розтягуюся'::text,'Якби в мене була така тренерка, як ти, я б розтягувався щоранку, чесно.'::text),
(398049,44228,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tuviera una entrenadora como tú, ... todas las mañanas, en serio.'::text,'me estiraría'::text,'me estiraré'::text,'me estiro'::text,'Si tuviera una entrenadora como tú, me estiraría todas las mañanas, en serio.'::text),
(398048,44228,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si j''avais une coach comme toi, je ... tous les matins, franchement.'::text,'m''étirerais'::text,'m''étirerai'::text,'m''étire'::text,'Si j''avais une coach comme toi, je m''étirerais tous les matins, franchement.'::text),
(398051,44228,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senin gibi bir eğitmenim olsaydı her sabah ..., açıkçası.'::text,'esneme yapardım'::text,'esneme yapacağım'::text,'esneme yaparım'::text,'Senin gibi bir eğitmenim olsaydı her sabah esneme yapardım, açıkçası.'::text),
(398052,44228,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha olyan edzőm lenne, mint te, minden reggel ..., őszintén.'::text,'nyújtanék'::text,'nyújtani fogok'::text,'nyújtok'::text,'Ha olyan edzőm lenne, mint te, minden reggel nyújtanék, őszintén.'::text),
(398064,44230,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Trainerin ... die ganze Gruppe durch die Dehnübungen.'::text,'führte'::text,'wurde geführt'::text,'führend'::text,'Die Trainerin führte die ganze Gruppe durch die Dehnübungen.'::text),
(398068,44230,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тренерка ... всю групу через розтяжку.'::text,'провела'::text,'була проведена'::text,'проводячи'::text,'Тренерка провела всю групу через розтяжку.'::text),
(398067,44230,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La entrenadora ... a todo el grupo en los estiramientos.'::text,'guio'::text,'fue guiada'::text,'guiando'::text,'La entrenadora guio a todo el grupo en los estiramientos.'::text),
(398066,44230,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La coach ... tout le groupe pendant les étirements.'::text,'a guidé'::text,'a été guidée'::text,'guidant'::text,'La coach a guidé tout le groupe pendant les étirements.'::text),
(398069,44230,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğitmen bütün gruba esneme hareketlerini ...'::text,'yaptırdı'::text,'yaptırıldı'::text,'yaptırarak'::text,'Eğitmen bütün gruba esneme hareketlerini yaptırdı.'::text),
(398070,44230,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edző ... az egész csoportot a nyújtás során.'::text,'vezette'::text,'vezetve lett'::text,'vezetve'::text,'Az edző vezette az egész csoportot a nyújtás során.'::text),
(398073,44231,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Katze macht jede Bewegung nach, also ... sie denken, dass sie ihre Trainerin ist.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Die Katze macht jede Bewegung nach, also muss sie denken, dass sie ihre Trainerin ist.'::text),
(398077,44231,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кіт повторює кожен рух, тож він ..., що вона його тренерка.'::text,'напевно думає'::text,'не може думати'::text,'мав би думати'::text,'Кіт повторює кожен рух, тож він напевно думає, що вона його тренерка.'::text),
(398076,44231,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gato copia cada movimiento, así que ... pensar que ella es su entrenadora.'::text,'debe de'::text,'no puede'::text,'debería'::text,'El gato copia cada movimiento, así que debe de pensar que ella es su entrenadora.'::text),
(398075,44231,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat copie chaque mouvement, donc il ... penser qu''elle est sa coach.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Le chat copie chaque mouvement, donc il doit penser qu''elle est sa coach.'::text),
(398078,44231,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi her hareketi taklit ediyor, demek ki onun kendi eğitmeni olduğunu ...'::text,'düşünüyor olmalı'::text,'düşünüyor olamaz'::text,'düşünmeli'::text,'Kedi her hareketi taklit ediyor, demek ki onun kendi eğitmeni olduğunu düşünüyor olmalı.'::text),
(398079,44231,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A macska minden mozdulatot utánoz, szóval ... azt hiszi, hogy ő az edzője.'::text,'biztosan'::text,'nem lehet, hogy'::text,'valószínűleg'::text,'A macska minden mozdulatot utánoz, szóval biztosan azt hiszi, hogy ő az edzője.'::text),
(398082,44232,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Park, ... die Trainerin arbeitet, ist absolut der schlimmste Ort für eine Katze!'::text,'wo'::text,'der'::text,'wer'::text,'Der Park, wo die Trainerin arbeitet, ist absolut der schlimmste Ort für eine Katze!'::text),
(398086,44232,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Парк, ... працює тренерка, — це абсолютно найгірше місце для кота!'::text,'де'::text,'який'::text,'хто'::text,'Парк, де працює тренерка, — це абсолютно найгірше місце для кота!'::text),
(398085,44232,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El parque ... trabaja la entrenadora es sin duda el peor sitio para un gato!'::text,'donde'::text,'que'::text,'quien'::text,'¡El parque donde trabaja la entrenadora es sin duda el peor sitio para un gato!'::text),
(398084,44232,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le parc ... travaille la coach est carrément le pire endroit pour un chat !'::text,'où'::text,'que'::text,'qui'::text,'Le parc où travaille la coach est carrément le pire endroit pour un chat !'::text),
(398087,44232,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğitmenin ... park, bir kedi için kesinlikle en kötü yer!'::text,'çalıştığı'::text,'hangi'::text,'kim'::text,'Eğitmenin çalıştığı park, bir kedi için kesinlikle en kötü yer!'::text),
(398088,44232,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A park, ... az edző dolgozik, abszolút a legrosszabb hely egy macskának!'::text,'ahol'::text,'amely'::text,'aki'::text,'A park, ahol az edző dolgozik, abszolút a legrosszabb hely egy macskának!'::text),
(398091,44233,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Trainerin sagte, dass die Katze ihre ganze Stunde für immer ...!'::text,'ruiniert hatte'::text,'ruiniert hat'::text,'ruiniert'::text,'Die Trainerin sagte, dass die Katze ihre ganze Stunde für immer ruiniert hatte!'::text),
(398095,44233,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тренерка сказала, що кіт назавжди ... їй усе заняття!'::text,'зіпсував'::text,'зіпсував'::text,'псує'::text,'Тренерка сказала, що кіт назавжди зіпсував їй усе заняття!'::text),
(398094,44233,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La entrenadora dijo que el gato ... toda su clase para siempre!'::text,'había arruinado'::text,'ha arruinado'::text,'arruina'::text,'¡La entrenadora dijo que el gato había arruinado toda su clase para siempre!'::text),
(398093,44233,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La coach a dit que le chat ... tout son cours pour toujours !'::text,'avait gâché'::text,'a gâché'::text,'gâche'::text,'La coach a dit que le chat avait gâché tout son cours pour toujours !'::text),
(398096,44233,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğitmen, kedinin bütün dersini sonsuza dek ... söyledi!'::text,'mahvetmiş olduğunu'::text,'mahvettiğini'::text,'mahvettiğini'::text,'Eğitmen, kedinin bütün dersini sonsuza dek mahvetmiş olduğunu söyledi!'::text),
(398097,44233,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edző azt mondta, hogy a macska örökre ... az egész óráját!'::text,'tönkretette'::text,'tönkretette'::text,'tönkreteszi'::text,'Az edző azt mondta, hogy a macska örökre tönkretette az egész óráját!'::text),
(398100,44234,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Trainerin ... früher eine ruhige Stunde, bevor diese Katze kam! Ende!'::text,'hatte'::text,'hatte'::text,'war gewohnt zu haben'::text,'Die Trainerin hatte früher eine ruhige Stunde, bevor diese Katze kam! Ende!'::text),
(398104,44234,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тренерка колись ... спокійне заняття, поки не з''явився той кіт! Кінець!'::text,'мала'::text,'мала'::text,'звикла мати'::text,'Тренерка колись мала спокійне заняття, поки не з''явився той кіт! Кінець!'::text),
(398103,44234,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La entrenadora ... tener una clase tranquila antes de que llegara ese gato! ¡Fin!'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'¡La entrenadora solía tener una clase tranquila antes de que llegara ese gato! ¡Fin!'::text),
(398102,44234,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Autrefois, la coach ... un cours tranquille avant l''arrivée de ce chat ! Fin !'::text,'avait'::text,'avait'::text,'avait l''habitude d''avoir'::text,'Autrefois, la coach avait un cours tranquille avant l''arrivée de ce chat ! Fin !'::text),
(398105,44234,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kedi gelmeden önce eğitmenin sakin bir dersi ...! Son!'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'O kedi gelmeden önce eğitmenin sakin bir dersi olurdu! Son!'::text),
(398106,44234,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edzőnek régen nyugis órája ..., mielőtt az a macska megjelent! Vége!'::text,'volt'::text,'volt'::text,'volt hozzászokva'::text,'Az edzőnek régen nyugis órája volt, mielőtt az a macska megjelent! Vége!'::text),
(398109,44235,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, ich hab gehört, die Trainerin hat sich geweigert, die Katze aus ihrer Stunde ...'::text,'rauszuwerfen'::text,'Rauswerfen'::text,'rauswerfen'::text,'Girl, ich hab gehört, die Trainerin hat sich geweigert, die Katze aus ihrer Stunde rauszuwerfen.'::text),
(398113,44235,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що тренерка відмовилася ... кота зі свого заняття.'::text,'вигнати'::text,'вигнання'::text,'вигнати'::text,'Подруго, я чула, що тренерка відмовилася вигнати кота зі свого заняття.'::text),
(398112,44235,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me han dicho que la entrenadora se negó ... al gato de su clase.'::text,'a echar'::text,'echando'::text,'echar'::text,'Tía, me han dicho que la entrenadora se negó a echar al gato de su clase.'::text),
(398111,44235,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu dire que la coach a refusé ... le chat de son cours.'::text,'de virer'::text,'virant'::text,'virer'::text,'Meuf, j''ai entendu dire que la coach a refusé de virer le chat de son cours.'::text),
(398114,44235,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre eğitmen kediyi dersinden ... reddetmiş.'::text,'çıkarmayı'::text,'çıkarmayı'::text,'çıkarmak'::text,'Kızım, duyduğuma göre eğitmen kediyi dersinden çıkarmayı reddetmiş.'::text),
(398115,44235,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy az edző nem volt hajlandó ... a macskát az órájáról.'::text,'elküldeni'::text,'elküldés'::text,'elküld'::text,'Csajszi, azt hallottam, hogy az edző nem volt hajlandó elküldeni a macskát az órájáról.'::text),
(398118,44236,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... die Trainerin diesen Kurs seit zehn Jahren jeden Morgen.'::text,'leitet'::text,'leitet'::text,'leitet'::text,'Bestie, angeblich leitet die Trainerin diesen Kurs seit zehn Jahren jeden Morgen.'::text),
(398122,44236,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, тренерка вже десять років щоранку ... це заняття.'::text,'веде'::text,'веде'::text,'веде'::text,'Подружко, кажуть, тренерка вже десять років щоранку веде це заняття.'::text),
(398121,44236,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer la entrenadora ... esta clase cada mañana desde hace diez años.'::text,'dirige'::text,'dirige'::text,'está dirigiendo'::text,'Amiga, al parecer la entrenadora dirige esta clase cada mañana desde hace diez años.'::text),
(398120,44236,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment la coach ... ce cours tous les matins depuis dix ans.'::text,'anime'::text,'anime'::text,'est en train d''animer'::text,'Ma belle, apparemment la coach anime ce cours tous les matins depuis dix ans.'::text),
(398123,44236,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre eğitmen on yıldır her sabah bu dersi ...'::text,'veriyor'::text,'verir'::text,'veriyor'::text,'Kanka, duyduğuma göre eğitmen on yıldır her sabah bu dersi veriyor.'::text),
(398124,44236,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az edző tíz éve minden reggel ... ezt az órát.'::text,'tartja'::text,'tartja'::text,'tartja'::text,'Csajszi, állítólag az edző tíz éve minden reggel tartja ezt az órát.'::text),
(404121,44903,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, dass sie Yoga auf dem Dach ..., als die Sonne unterging.'::text,'machte'::text,'gemacht hat'::text,'gemacht hat'::text,'Rate mal, ich hab gehört, dass sie Yoga auf dem Dach machte, als die Sonne unterging.'::text),
(404125,44903,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що, я чула, що вона ... йогою на даху, коли сідало сонце.'::text,'займалася'::text,'позаймалася'::text,'позаймалася'::text,'Вгадай що, я чула, що вона займалася йогою на даху, коли сідало сонце.'::text),
(404124,44903,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? Me han dicho que ... yoga en la azotea cuando se puso el sol.'::text,'estaba haciendo'::text,'hizo'::text,'ha hecho'::text,'¿Sabes qué? Me han dicho que estaba haciendo yoga en la azotea cuando se puso el sol.'::text),
(404123,44903,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu dire qu''elle ... du yoga sur le toit quand le soleil s''est couché.'::text,'faisait'::text,'a fait'::text,'a fait'::text,'Devine quoi, j''ai entendu dire qu''elle faisait du yoga sur le toit quand le soleil s''est couché.'::text),
(404126,44903,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, duyduğuma göre güneş batarken çatıda yoga ...'::text,'yapıyormuş'::text,'yapmış'::text,'yapmış'::text,'Tahmin et ne oldu, duyduğuma göre güneş batarken çatıda yoga yapıyormuş.'::text),
(404127,44903,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy ... jógát a tetőn, amikor lement a nap.'::text,'gyakorolt'::text,'gyakorolt'::text,'gyakorolt'::text,'Képzeld, azt hallottam, hogy gyakorolt jógát a tetőn, amikor lement a nap.'::text),
(404130,44904,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit einem Jahr jeden Abend Yoga auf dieser Dachterrasse.'::text,'macht'::text,'macht'::text,'macht'::text,'Sie macht seit einem Jahr jeden Abend Yoga auf dieser Dachterrasse.'::text),
(404134,44904,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже рік щовечора ... йогою на цьому даху.'::text,'займається'::text,'займається'::text,'займається'::text,'Вона вже рік щовечора займається йогою на цьому даху.'::text),
(404133,44904,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... yoga en esta azotea cada tarde desde hace un año.'::text,'Hace'::text,'Está haciendo'::text,'Hace'::text,'Hace yoga en esta azotea cada tarde desde hace un año.'::text),
(404132,44904,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... du yoga sur ce toit tous les soirs depuis un an.'::text,'fait'::text,'est en train de faire'::text,'fait'::text,'Elle fait du yoga sur ce toit tous les soirs depuis un an.'::text),
(404135,44904,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yıldır her akşam bu çatıda yoga ...'::text,'yapıyor'::text,'yapıyor'::text,'yapar'::text,'Bir yıldır her akşam bu çatıda yoga yapıyor.'::text),
(404136,44904,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy éve minden este ... a jógát ezen a tetőn.'::text,'gyakorolja'::text,'gyakorolja'::text,'gyakorolja'::text,'Egy éve minden este gyakorolja a jógát ezen a tetőn.'::text),
(404139,44905,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihre Yogamatte aus, beugte sich nach vorne und schaute hoch in die Kamera.'::text,'rollte'::text,'rollte gerade'::text,'rollt'::text,'Sie rollte ihre Yogamatte aus, beugte sich nach vorne und schaute hoch in die Kamera.'::text),
(404143,44905,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... свій килимок для йоги, нахилилася вперед і подивилася вгору в камеру.'::text,'розгорнула'::text,'розгортала'::text,'розгортає'::text,'Вона розгорнула свій килимок для йоги, нахилилася вперед і подивилася вгору в камеру.'::text),
(404142,44905,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su esterilla de yoga, se inclinó hacia delante y miró hacia arriba a la cámara.'::text,'Desenrolló'::text,'Estaba desenrollando'::text,'Desenrolla'::text,'Desenrolló su esterilla de yoga, se inclinó hacia delante y miró hacia arriba a la cámara.'::text),
(404141,44905,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son tapis de yoga, s''est penchée en avant et a levé les yeux vers la caméra.'::text,'a déroulé'::text,'déroulait'::text,'déroule'::text,'Elle a déroulé son tapis de yoga, s''est penchée en avant et a levé les yeux vers la caméra.'::text),
(404144,44905,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yoga matını ..., öne eğildi ve yukarı, kameraya baktı.'::text,'açtı'::text,'açıyordu'::text,'açar'::text,'Yoga matını açtı, öne eğildi ve yukarı, kameraya baktı.'::text),
(404145,44905,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a jógamatracát, előrehajolt, és felnézett a kamerába.'::text,'Kiterítette'::text,'Épp terítette ki'::text,'Kiteríti'::text,'Kiterítette a jógamatracát, előrehajolt, és felnézett a kamerába.'::text),
(404157,44907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Sonne unterging, ... du alle deine Yoga-Posen schon beendet. Respekt.'::text,'hattest'::text,'hast'::text,'beendest'::text,'Als die Sonne unterging, hattest du alle deine Yoga-Posen schon beendet. Respekt.'::text),
(404161,44907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки сонце сіло, ти вже ... всі свої пози йоги. Респект.'::text,'завершила'::text,'завершила'::text,'завершуєш'::text,'Поки сонце сіло, ти вже завершила всі свої пози йоги. Респект.'::text),
(404160,44907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se puso el sol, ya ... todas tus posturas de yoga. Respeto.'::text,'habías terminado'::text,'has terminado'::text,'terminas'::text,'Para cuando se puso el sol, ya habías terminado todas tus posturas de yoga. Respeto.'::text),
(404159,44907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le soleil s''est couché, tu ... toutes tes postures de yoga. Respect.'::text,'avais terminé'::text,'as terminé'::text,'termines'::text,'Quand le soleil s''est couché, tu avais terminé toutes tes postures de yoga. Respect.'::text),
(404162,44907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş battığında tüm yoga pozlarını ..., saygı.'::text,'bitirmiştin'::text,'bitirdin'::text,'bitirirsin'::text,'Güneş battığında tüm yoga pozlarını bitirmiştin, saygı.'::text),
(404163,44907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire lement a nap, már ... az összes jógapózodat. Respekt.'::text,'befejezted'::text,'befejezted'::text,'befejezed'::text,'Mire lement a nap, már befejezted az összes jógapózodat. Respekt.'::text),
(404166,44908,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, morgen um diese Zeit ... du wieder Yoga auf diesem Dach, so ikonisch.'::text,'machst'::text,'wirst machen'::text,'machst'::text,'Ehrlich, morgen um diese Zeit machst du wieder Yoga auf diesem Dach, so ikonisch.'::text),
(404170,44908,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, завтра в цей час ти знову ... йогою на цьому даху, так культово.'::text,'займатимешся'::text,'позаймаєшся'::text,'займаєшся'::text,'Чесно, завтра в цей час ти знову займатимешся йогою на цьому даху, так культово.'::text),
(404169,44908,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, mañana a esta hora ... yoga otra vez en esta azotea, qué icónico.'::text,'estarás haciendo'::text,'harás'::text,'haces'::text,'Sinceramente, mañana a esta hora estarás haciendo yoga otra vez en esta azotea, qué icónico.'::text),
(404168,44908,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, demain à la même heure, tu ... encore du yoga sur ce toit, trop iconique.'::text,'seras en train de faire'::text,'feras'::text,'fais'::text,'Franchement, demain à la même heure, tu seras en train de faire encore du yoga sur ce toit, trop iconique.'::text),
(404171,44908,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası yarın bu saatlerde yine bu çatıda yoga ..., çok efsane.'::text,'yapıyor olacaksın'::text,'yapacaksın'::text,'yapıyorsun'::text,'Açıkçası yarın bu saatlerde yine bu çatıda yoga yapıyor olacaksın, çok efsane.'::text),
(404172,44908,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, holnap ilyenkor megint ... a jógát ezen a tetőn, annyira ikonikus.'::text,'gyakorolni fogod'::text,'gyakorlod majd'::text,'gyakorlod'::text,'Őszintén, holnap ilyenkor megint gyakorolni fogod a jógát ezen a tetőn, annyira ikonikus.'::text),
(404175,44909,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz klar mühelos: „Das war’s, ich ... morgen wieder Yoga“, beschließt sie.'::text,'mache'::text,'werde machen'::text,'mache gerade'::text,'Ganz klar mühelos: „Das war’s, ich mache morgen wieder Yoga“, beschließt sie.'::text),
(404179,44909,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, без жодних зусиль: «Усе, завтра я знову ... йогою», — вирішує вона.'::text,'позаймаюся'::text,'займатимуся'::text,'займаюся'::text,'Очевидно, без жодних зусиль: «Усе, завтра я знову позаймаюся йогою», — вирішує вона.'::text),
(404178,44909,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente sin esfuerzo: «Ya está, mañana ... yoga otra vez», decide.'::text,'haré'::text,'estaré haciendo'::text,'estoy haciendo'::text,'Claramente sin esfuerzo: «Ya está, mañana haré yoga otra vez», decide.'::text),
(404177,44909,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement sans effort : « C''est bon, je ... du yoga encore demain », décide-t-elle.'::text,'ferai'::text,'serai en train de faire'::text,'fais'::text,'Clairement sans effort : « C''est bon, je ferai du yoga encore demain », décide-t-elle.'::text),
(404180,44909,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki hiç zorlanmadan: “Tamam, yarın yine yoga ...” diye karar veriyor.'::text,'yapacağım'::text,'yapıyor olacağım'::text,'yapıyorum'::text,'Belli ki hiç zorlanmadan: “Tamam, yarın yine yoga yapacağım” diye karar veriyor.'::text),
(404181,44909,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván erőfeszítés nélkül: „Ennyi, holnap újra ... a jógát” – dönti el.'::text,'gyakorlom'::text,'gyakorolni fogom'::text,'épp gyakorlom'::text,'Nyilván erőfeszítés nélkül: „Ennyi, holnap újra gyakorlom a jógát” – dönti el.'::text),
(404184,44910,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, wenn du bei Sonnenuntergang Yoga ..., siehst du so entspannt aus.'::text,'machst'::text,'machtest'::text,'machen wirst'::text,'Klar, wenn du bei Sonnenuntergang Yoga machst, siehst du so entspannt aus.'::text),
(404188,44910,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, якщо ти ... йогою на заході сонця, ти виглядаєш так спокійно.'::text,'займаєшся'::text,'займалася'::text,'займатимешся'::text,'Звісно, якщо ти займаєшся йогою на заході сонця, ти виглядаєш так спокійно.'::text),
(404187,44910,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, si ... yoga al atardecer, te ves así de tranquila.'::text,'haces'::text,'hiciste'::text,'harás'::text,'Obviamente, si haces yoga al atardecer, te ves así de tranquila.'::text),
(404186,44910,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, si tu ... du yoga au coucher du soleil, tu as l''air aussi calme.'::text,'fais'::text,'faisais'::text,'feras'::text,'Évidemment, si tu fais du yoga au coucher du soleil, tu as l''air aussi calme.'::text),
(404189,44910,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki, gün batımında yoga ..., bu kadar sakin görünürsün.'::text,'yaparsan'::text,'yaptıysan'::text,'yapacaksan'::text,'Tabii ki, gün batımında yoga yaparsan, bu kadar sakin görünürsün.'::text),
(404190,44910,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván, ha naplementekor ... a jógát, ilyen nyugodtnak tűnsz.'::text,'gyakorlod'::text,'gyakoroltad'::text,'gyakorolni fogod'::text,'Nyilván, ha naplementekor gyakorlod a jógát, ilyen nyugodtnak tűnsz.'::text),
(404193,44911,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz klar leicht: Wenn sie sich noch weiter nach hinten lehnt, ... ihr Yoga zur Zirkusnummer.'::text,'wird'::text,'würde'::text,'wurde'::text,'Ganz klar leicht: Wenn sie sich noch weiter nach hinten lehnt, wird ihr Yoga zur Zirkusnummer.'::text),
(404197,44911,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, легко: якщо вона ще більше відхилиться назад, її йога ... на циркову виставу.'::text,'перетвориться'::text,'перетворилася б'::text,'перетворилася'::text,'Очевидно, легко: якщо вона ще більше відхилиться назад, її йога перетвориться на циркову виставу.'::text),
(404196,44911,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente fácil: si se inclina un poco más hacia atrás, su yoga ... un número de circo.'::text,'se convertirá en'::text,'se convertiría en'::text,'se convirtió en'::text,'Claramente fácil: si se inclina un poco más hacia atrás, su yoga se convertirá en un número de circo.'::text),
(404195,44911,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement facile : si elle se penche encore plus en arrière, son yoga ... un numéro de cirque.'::text,'deviendra'::text,'deviendrait'::text,'est devenu'::text,'Clairement facile : si elle se penche encore plus en arrière, son yoga deviendra un numéro de cirque.'::text),
(404198,44911,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki kolay: biraz daha geriye yaslanırsa yogası bir sirk gösterisine ...'::text,'dönüşecek'::text,'dönüşürdü'::text,'dönüştü'::text,'Belli ki kolay: biraz daha geriye yaslanırsa yogası bir sirk gösterisine dönüşecek.'::text),
(404199,44911,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván könnyű: ha még jobban hátrahajol, a jógája cirkuszi mutatvánnyá ...'::text,'válik'::text,'válna'::text,'vált'::text,'Nyilván könnyű: ha még jobban hátrahajol, a jógája cirkuszi mutatvánnyá válik.'::text),
(404202,44912,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Sonne verschwinden würde, ... ihre Yogastunde in völliger Dunkelheit enden!'::text,'würde'::text,'wird'::text,'endet'::text,'Wenn die Sonne verschwinden würde, würde ihre Yogastunde in völliger Dunkelheit enden!'::text),
(404206,44912,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби сонце зникло, її заняття йогою ... в повній темряві!'::text,'закінчилося б'::text,'закінчиться'::text,'закінчується'::text,'Якби сонце зникло, її заняття йогою закінчилося б в повній темряві!'::text),
(404205,44912,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si el sol desapareciera, su sesión de yoga ... en total oscuridad!'::text,'terminaría'::text,'terminará'::text,'termina'::text,'¡Si el sol desapareciera, su sesión de yoga terminaría en total oscuridad!'::text),
(404204,44912,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le soleil disparaissait, sa séance de yoga ... dans le noir total !'::text,'finirait'::text,'finira'::text,'finit'::text,'Si le soleil disparaissait, sa séance de yoga finirait dans le noir total !'::text),
(404207,44912,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş kaybolsaydı yoga seansı zifiri karanlıkta ...!'::text,'biterdi'::text,'bitecek'::text,'bitiyor'::text,'Güneş kaybolsaydı yoga seansı zifiri karanlıkta biterdi!'::text),
(404208,44912,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha eltűnne a nap, a jógaórája teljes sötétségben ...!'::text,'érne véget'::text,'ér majd véget'::text,'ér véget'::text,'Ha eltűnne a nap, a jógaórája teljes sötétségben érne véget!'::text),
(404211,44913,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Yogamatte ... bis ganz nach oben auf diese Dachterrasse getragen! Absolut heldenhaft!'::text,'wurde'::text,'wird'::text,'trug'::text,'Ihre Yogamatte wurde bis ganz nach oben auf diese Dachterrasse getragen! Absolut heldenhaft!'::text),
(404215,44913,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її килимок для йоги ... аж на цей дах! Абсолютно героїчно!'::text,'було винесено'::text,'виносять'::text,'винесла'::text,'Її килимок для йоги було винесено аж на цей дах! Абсолютно героїчно!'::text),
(404214,44913,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su esterilla de yoga ... hasta esta azotea! ¡Absolutamente heroico!'::text,'fue subida'::text,'es subida'::text,'subió'::text,'¡Su esterilla de yoga fue subida hasta esta azotea! ¡Absolutamente heroico!'::text),
(404213,44913,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tapis de yoga ... jusqu''en haut de ce toit ! Carrément héroïque !'::text,'a été porté'::text,'est porté'::text,'a porté'::text,'Son tapis de yoga a été porté jusqu''en haut de ce toit ! Carrément héroïque !'::text),
(404216,44913,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yoga matı ta bu çatıya kadar ...! Kesinlikle kahramanca!'::text,'taşındı'::text,'taşınıyor'::text,'taşıdı'::text,'Yoga matı ta bu çatıya kadar taşındı! Kesinlikle kahramanca!'::text),
(404217,44913,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jógamatracát egészen a tetőig ...! Abszolút hősies!'::text,'felvitték'::text,'felviszik'::text,'felvitte'::text,'A jógamatracát egészen a tetőig felvitték! Abszolút hősies!'::text),
(373620,41514,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie durch die Lücke zwischen den Büchern ..., arbeiteten die anderen Studierenden weiter.'::text,'lugte'::text,'gelugt hat'::text,'gelugt hat'::text,'Während sie durch die Lücke zwischen den Büchern lugte, arbeiteten die anderen Studierenden weiter.'::text),
(373624,41514,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... крізь щілину між книжками, інші студенти працювали далі.'::text,'підглядала'::text,'зазирнула'::text,'зазирнула'::text,'Поки вона підглядала крізь щілину між книжками, інші студенти працювали далі.'::text),
(373623,41514,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... por el hueco entre los libros, los demás estudiantes seguían trabajando.'::text,'espiaba'::text,'espió'::text,'ha espiado'::text,'Mientras espiaba por el hueco entre los libros, los demás estudiantes seguían trabajando.'::text),
(373622,41514,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... par l''espace entre les livres, les autres étudiants continuaient à travailler.'::text,'jetait un œil'::text,'a jeté un œil'::text,'a jeté un œil'::text,'Pendant qu''elle jetait un œil par l''espace entre les livres, les autres étudiants continuaient à travailler.'::text),
(373625,41514,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kitapların arasındaki boşluktan ... diğer öğrenciler çalışmaya devam etti.'::text,'gizlice bakarken'::text,'gizlice baktığında'::text,'gizlice bakmışken'::text,'O kitapların arasındaki boşluktan gizlice bakarken diğer öğrenciler çalışmaya devam etti.'::text),
(373626,41514,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amíg ő ... a könyvek közötti résen, a többi diák tovább dolgozott.'::text,'kukucskált'::text,'kikukucskált'::text,'kikukucskált'::text,'Amíg ő kukucskált a könyvek közötti résen, a többi diák tovább dolgozott.'::text),
(373629,41515,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den ganzen Nachmittag hinter ihrer Bücherwand zu den anderen Studierenden hervor.'::text,'lugt'::text,'lugt'::text,'lugt'::text,'Sie lugt den ganzen Nachmittag hinter ihrer Bücherwand zu den anderen Studierenden hervor.'::text),
(373633,41515,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... на інших студентів з-за своєї стіни з книжок усе пообіддя.'::text,'визирає'::text,'визирає'::text,'визирає'::text,'Вона визирає на інших студентів з-за своєї стіни з книжок усе пообіддя.'::text),
(373632,41515,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a los otros estudiantes desde detrás de su muro de libros toda la tarde.'::text,'Lleva espiando'::text,'Está espiando'::text,'Espía'::text,'Lleva espiando a los otros estudiantes desde detrás de su muro de libros toda la tarde.'::text),
(373631,41515,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les autres étudiants derrière son mur de livres depuis tout l''après-midi.'::text,'épie'::text,'est en train d''épier'::text,'épie'::text,'Elle épie les autres étudiants derrière son mur de livres depuis tout l''après-midi.'::text),
(373634,41515,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün öğleden sonra kitap duvarının arkasından diğer öğrencilere ...'::text,'gizlice bakıyor'::text,'gizlice bakıyor'::text,'gizlice bakar'::text,'Bütün öğleden sonra kitap duvarının arkasından diğer öğrencilere gizlice bakıyor.'::text),
(373635,41515,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész délután ... a többi diákra a könyvfala mögül.'::text,'kukucskál ki'::text,'kukucskál ki'::text,'kukucskál ki'::text,'Egész délután kukucskál ki a többi diákra a könyvfala mögül.'::text),
(373647,41517,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi: Sie ... seit dem Mittagessen durch diese Lücke, statt zu lesen.'::text,'lugt'::text,'lugte'::text,'lugt gerade'::text,'Ein echter Profi: Sie lugt seit dem Mittagessen durch diese Lücke, statt zu lesen.'::text),
(373651,41517,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжня професіоналка: вона ... крізь ту щілину ще з обіду замість того, щоб читати.'::text,'підглядає'::text,'підглянула'::text,'підглядає'::text,'Справжня професіоналка: вона підглядає крізь ту щілину ще з обіду замість того, щоб читати.'::text),
(373650,41517,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toda una profesional: ... por ese hueco desde el almuerzo en lugar de leer.'::text,'lleva espiando'::text,'espió'::text,'está espiando'::text,'Toda una profesional: lleva espiando por ese hueco desde el almuerzo en lugar de leer.'::text),
(373649,41517,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une vraie pro : elle ... par cet espace depuis le déjeuner au lieu de lire.'::text,'épie'::text,'a épié'::text,'est en train d''épier'::text,'Une vraie pro : elle épie par cet espace depuis le déjeuner au lieu de lire.'::text),
(373652,41517,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçek bir profesyonel: okumak yerine öğle yemeğinden beri o boşluktan ...'::text,'gizlice bakıyor'::text,'gizlice baktı'::text,'gizlice bakıyor'::text,'Gerçek bir profesyonel: okumak yerine öğle yemeğinden beri o boşluktan gizlice bakıyor.'::text),
(373653,41517,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi: ebéd óta ... azon a résen olvasás helyett.'::text,'kukucskál'::text,'kikukucskált'::text,'kukucskál'::text,'Igazi profi: ebéd óta kukucskál azon a résen olvasás helyett.'::text),
(373656,41518,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toller Lernplan: Als die Wand fertig war, ... sie nur zweimal in ihr Lehrbuch geschaut.'::text,'hatte'::text,'hat'::text,'schaute'::text,'Toller Lernplan: Als die Wand fertig war, hatte sie nur zweimal in ihr Lehrbuch geschaut.'::text),
(373660,41518,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий план навчання: на той час, як стіну добудували, вона ... в підручник лише двічі.'::text,'зазирнула'::text,'зазирнула'::text,'зазирнула'::text,'Чудовий план навчання: на той час, як стіну добудували, вона зазирнула в підручник лише двічі.'::text),
(373659,41518,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran plan de estudio: para cuando el muro estuvo terminado, solo le ... un vistazo al libro de texto dos veces.'::text,'había echado'::text,'ha echado'::text,'echó'::text,'Gran plan de estudio: para cuando el muro estuvo terminado, solo le había echado un vistazo al libro de texto dos veces.'::text),
(373658,41518,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super plan de révision : quand le mur a été fini, elle ... que deux fois dans son manuel.'::text,'n''avait jeté un œil'::text,'n''a jeté un œil'::text,'ne jetait un œil'::text,'Super plan de révision : quand le mur a été fini, elle n''avait jeté un œil que deux fois dans son manuel.'::text),
(373661,41518,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika çalışma planı: duvar bittiğinde ders kitabına sadece iki kez ...'::text,'göz atmıştı'::text,'göz attı'::text,'göz attı'::text,'Harika çalışma planı: duvar bittiğinde ders kitabına sadece iki kez göz atmıştı.'::text),
(373662,41518,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek tanulási terv: mire a fal elkészült, csak kétszer ... bele a tankönyvébe.'::text,'kukkantott'::text,'kukkantott'::text,'kukkantott'::text,'Remek tanulási terv: mire a fal elkészült, csak kétszer kukkantott bele a tankönyvébe.'::text),
(373665,41519,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... nicht durch die Lücke lugen sollen! Jetzt hat ihr Lernpartner sie gesehen, und alles ist ruiniert!'::text,'hätte'::text,'durfte'::text,'konnte'::text,'Sie hätte nicht durch die Lücke lugen sollen! Jetzt hat ihr Lernpartner sie gesehen, und alles ist ruiniert!'::text),
(373669,41519,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй ... крізь щілину! Тепер її напарник по навчанню її побачив, і все зіпсовано!'::text,'не варто було підглядати'::text,'не можна було підглядати'::text,'не вдалося підглянути'::text,'Їй не варто було підглядати крізь щілину! Тепер її напарник по навчанню її побачив, і все зіпсовано!'::text),
(373668,41519,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... por el hueco! Ahora su compañero de estudio la ha visto, ¡y todo se ha arruinado!'::text,'No debería haber espiado'::text,'No debe haber espiado'::text,'No pudo espiar'::text,'¡No debería haber espiado por el hueco! Ahora su compañero de estudio la ha visto, ¡y todo se ha arruinado!'::text),
(373667,41519,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... par l''espace ! Maintenant son partenaire de révision l''a vue, et tout est fichu !'::text,'n''aurait pas dû regarder'::text,'ne doit pas avoir regardé'::text,'n''a pas pu regarder'::text,'Elle n''aurait pas dû regarder par l''espace ! Maintenant son partenaire de révision l''a vue, et tout est fichu !'::text),
(373670,41519,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boşluktan ...! Şimdi çalışma arkadaşı onu gördü ve her şey mahvoldu!'::text,'bakmamalıydı'::text,'bakmamış olmalı'::text,'bakamadı'::text,'Boşluktan bakmamalıydı! Şimdi çalışma arkadaşı onu gördü ve her şey mahvoldu!'::text),
(373671,41519,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a résen! Most a tanulótársa meglátta, és minden tönkrement!'::text,'Nem kellett volna kukucskálnia'::text,'Biztos nem kukucskált'::text,'Nem tudott kukucskálni'::text,'Nem kellett volna kukucskálnia a résen! Most a tanulótársa meglátta, és minden tönkrement!'::text),
(373674,41520,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Verzweifelt ließ sie eine Freundin über die Bücherwand ..., um nach der Bibliothekarin zu schauen!'::text,'lugen'::text,'zu lugen'::text,'gelugt'::text,'Verzweifelt ließ sie eine Freundin über die Bücherwand lugen, um nach der Bibliothekarin zu schauen!'::text),
(373678,41520,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У відчаї вона попросила подругу ... через стіну з книжок, чи не йде бібліотекарка!'::text,'зазирнути'::text,'зазирнути'::text,'зазирнула'::text,'У відчаї вона попросила подругу зазирнути через стіну з книжок, чи не йде бібліотекарка!'::text),
(373677,41520,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desesperada, hizo que una amiga ... por encima del muro de libros para ver si venía la bibliotecaria!'::text,'se asomara'::text,'asomarse'::text,'asomada'::text,'¡Desesperada, hizo que una amiga se asomara por encima del muro de libros para ver si venía la bibliotecaria!'::text),
(373676,41520,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Désespérée, elle a fait ... une amie par-dessus le mur de livres pour guetter la bibliothécaire !'::text,'regarder'::text,'de regarder'::text,'regardé'::text,'Désespérée, elle a fait regarder une amie par-dessus le mur de livres pour guetter la bibliothécaire !'::text),
(373679,41520,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çaresiz kalınca kütüphaneciyi kontrol etmek için bir arkadaşına kitap duvarının üstünden ...!'::text,'baktırdı'::text,'bakmasını sağladı'::text,'bakılmış'::text,'Çaresiz kalınca kütüphaneciyi kontrol etmek için bir arkadaşına kitap duvarının üstünden baktırdı!'::text),
(373680,41520,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kétségbeesésében ... egy barátnőjével a könyvfal fölött, hogy jön-e a könyvtáros!'::text,'kukucskáltatott'::text,'kukucskálni'::text,'kukucskált'::text,'Kétségbeesésében kukucskáltatott egy barátnőjével a könyvfal fölött, hogy jön-e a könyvtáros!'::text),
(373683,41521,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich wünscht sie sich, sie ... über diese Bücherwand lugen, ohne dass sie jemand sieht.'::text,'könnte'::text,'kann'::text,'lugt'::text,'Bestie, angeblich wünscht sie sich, sie könnte über diese Bücherwand lugen, ohne dass sie jemand sieht.'::text),
(373687,41521,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, вона хотіла б, щоб ... через ту стіну з книжок і ніхто її не побачив.'::text,'могла зазирнути'::text,'може зазирнути'::text,'зазирає'::text,'Подружко, кажуть, вона хотіла б, щоб могла зазирнути через ту стіну з книжок і ніхто її не побачив.'::text),
(373686,41521,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer desearía ... por encima de ese muro de libros sin que nadie la viera.'::text,'poder asomarse'::text,'puede asomarse'::text,'se asoma'::text,'Amiga, al parecer desearía poder asomarse por encima de ese muro de libros sin que nadie la viera.'::text),
(373685,41521,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment elle aimerait ... par-dessus ce mur de livres sans que personne la voie.'::text,'pouvoir regarder'::text,'peut regarder'::text,'regarde'::text,'Ma belle, apparemment elle aimerait pouvoir regarder par-dessus ce mur de livres sans que personne la voie.'::text),
(373688,41521,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre keşke kimse görmeden o kitap duvarının üstünden ... diye düşünüyormuş.'::text,'bakabilse'::text,'bakabilir'::text,'bakıyor'::text,'Kanka, duyduğuma göre keşke kimse görmeden o kitap duvarının üstünden bakabilse diye düşünüyormuş.'::text),
(373689,41521,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag azt szeretné, ha ... azon a könyvfalon át anélkül, hogy bárki meglátná.'::text,'kikukucskálhatna'::text,'kikukucskálhat'::text,'kikukucskál'::text,'Csajszi, állítólag azt szeretné, ha kikukucskálhatna azon a könyvfalon át anélkül, hogy bárki meglátná.'::text),
(373701,41523,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie baute eine Wand aus Büchern, ... sie in den Raum lugen konnte, ohne gesehen zu werden.'::text,'damit'::text,'falls'::text,'es sei denn'::text,'Sie baute eine Wand aus Büchern, damit sie in den Raum lugen konnte, ohne gesehen zu werden.'::text),
(373705,41523,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона збудувала стіну з книжок, ... могла підглядати за кімнатою непомітно.'::text,'щоб'::text,'на випадок, якщо'::text,'хіба що'::text,'Вона збудувала стіну з книжок, щоб могла підглядати за кімнатою непомітно.'::text),
(373704,41523,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Construyó un muro de libros ... pudiera espiar la sala sin ser vista.'::text,'para que'::text,'por si'::text,'a menos que'::text,'Construyó un muro de libros para que pudiera espiar la sala sin ser vista.'::text),
(373703,41523,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a construit un mur de livres ... pouvoir épier la salle sans être vue.'::text,'pour'::text,'au cas où'::text,'à moins de'::text,'Elle a construit un mur de livres pour pouvoir épier la salle sans être vue.'::text),
(373706,41523,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görünmeden odaya gizlice bakabilmek ... kitaplardan bir duvar ördü.'::text,'için'::text,'ihtimaline karşı'::text,'olmadıkça'::text,'Görünmeden odaya gizlice bakabilmek için kitaplardan bir duvar ördü.'::text),
(373707,41523,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Könyvekből falat épített, ... kikukucskálhasson a terembe anélkül, hogy látnák.'::text,'hogy'::text,'arra az esetre, ha'::text,'hacsak nem'::text,'Könyvekből falat épített, hogy kikukucskálhasson a terembe anélkül, hogy látnák.'::text),
(373710,41524,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Tages wird sie mindestens fünfzigmal über diese Bücher ...'::text,'gelugt haben'::text,'lugen'::text,'lugt'::text,'Bis zum Ende des Tages wird sie mindestens fünfzigmal über diese Bücher gelugt haben.'::text),
(373714,41524,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця дня вона ... через ці книжки щонайменше п''ятдесят разів.'::text,'зазирне'::text,'зазиратиме'::text,'зазирає'::text,'До кінця дня вона зазирне через ці книжки щонайменше п''ятдесят разів.'::text),
(373713,41524,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final del día, ... por encima de esos libros al menos cincuenta veces.'::text,'se habrá asomado'::text,'se asomará'::text,'se asoma'::text,'Al final del día, se habrá asomado por encima de esos libros al menos cincuenta veces.'::text),
(373712,41524,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la journée, elle ... par-dessus ces livres au moins cinquante fois.'::text,'aura regardé'::text,'regardera'::text,'regarde'::text,'D''ici la fin de la journée, elle aura regardé par-dessus ces livres au moins cinquante fois.'::text),
(373715,41524,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün sonuna kadar o kitapların üstünden en az elli kez ...'::text,'bakmış olacak'::text,'bakacak'::text,'bakıyor'::text,'Gün sonuna kadar o kitapların üstünden en az elli kez bakmış olacak.'::text),
(373716,41524,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nap végére legalább ötvenszer ... át azokon a könyveken.'::text,'kukucskál'::text,'kukucskál majd'::text,'kukucskál'::text,'A nap végére legalább ötvenszer kukucskál át azokon a könyveken.'::text),
(368733,40971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er wieder zur Rushhour die U-Bahn ..., wird er die Menschenmassen natürlich lieben.'::text,'nimmt'::text,'nehmen wird'::text,'nahm'::text,'Wenn er wieder zur Rushhour die U-Bahn nimmt, wird er die Menschenmassen natürlich lieben.'::text),
(368737,40971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він знову ... на метро в годину пік, то, звісно, полюбить натовпи.'::text,'поїде'::text,'їхатиме'::text,'поїхав'::text,'Якщо він знову поїде на метро в годину пік, то, звісно, полюбить натовпи.'::text),
(368736,40971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... el metro otra vez en hora punta, obviamente le encantarán las multitudes.'::text,'toma'::text,'tomará'::text,'tomó'::text,'Si toma el metro otra vez en hora punta, obviamente le encantarán las multitudes.'::text),
(368735,40971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ... le métro à l''heure de pointe encore une fois, il va évidemment adorer la foule.'::text,'prend'::text,'prendra'::text,'a pris'::text,'S''il prend le métro à l''heure de pointe encore une fois, il va évidemment adorer la foule.'::text),
(368738,40971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yine iş çıkış saatinde metroya ..., kalabalığa bayılacağı kesin.'::text,'binerse'::text,'binecekse'::text,'bindiyse'::text,'Yine iş çıkış saatinde metroya binerse, kalabalığa bayılacağı kesin.'::text),
(368739,40971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha megint csúcsidőben ... metróval, nyilván imádni fogja a tömeget.'::text,'megy'::text,'fog menni'::text,'ment'::text,'Ha megint csúcsidőben megy metróval, nyilván imádni fogja a tömeget.'::text),
(368742,40972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die U-Bahn noch voller ..., wäre das der absolute Albtraum!'::text,'würde'::text,'wird'::text,'werden wird'::text,'Wenn die U-Bahn noch voller würde, wäre das der absolute Albtraum!'::text),
(368746,40972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби метро ... ще переповненішим, це був би абсолютний жах!'::text,'стало'::text,'стає'::text,'стане'::text,'Якби метро стало ще переповненішим, це був би абсолютний жах!'::text),
(368745,40972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si el metro ... todavía más lleno, sería una pesadilla absoluta!'::text,'se pusiera'::text,'se pone'::text,'se pondrá'::text,'¡Si el metro se pusiera todavía más lleno, sería una pesadilla absoluta!'::text),
(368744,40972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le métro ... encore plus bondé, ce serait un cauchemar absolu !'::text,'devenait'::text,'devient'::text,'deviendra'::text,'Si le métro devenait encore plus bondé, ce serait un cauchemar absolu !'::text),
(368747,40972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Metro daha da kalabalık ..., tam bir kâbus olurdu!'::text,'olsa'::text,'oluyorsa'::text,'olacaksa'::text,'Metro daha da kalabalık olsa, tam bir kâbus olurdu!'::text),
(368748,40972,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a metró még zsúfoltabb ..., az abszolút rémálom lenne!'::text,'lenne'::text,'lesz'::text,'lesz majd'::text,'Ha a metró még zsúfoltabb lenne, az abszolút rémálom lenne!'::text),
(368751,40973,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen ... der U-Bahn-Gang von Wand zu Wand mit Pendlern vollgestopft! Totales Chaos!'::text,'war'::text,'hat'::text,'ist'::text,'Heute Morgen war der U-Bahn-Gang von Wand zu Wand mit Pendlern vollgestopft! Totales Chaos!'::text),
(368755,40973,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вранці коридор метро ... пасажирами від стіни до стіни! Повний хаос!'::text,'був забитий'::text,'забив'::text,'забитий'::text,'Сьогодні вранці коридор метро був забитий пасажирами від стіни до стіни! Повний хаос!'::text),
(368754,40973,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esta mañana el pasillo del metro ... de viajeros de pared a pared! ¡Caos total!'::text,'estaba abarrotado'::text,'abarrotó'::text,'está abarrotado'::text,'¡Esta mañana el pasillo del metro estaba abarrotado de viajeros de pared a pared! ¡Caos total!'::text),
(368753,40973,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce matin, le couloir du métro ... de navetteurs d''un mur à l''autre ! Chaos total !'::text,'était bondé'::text,'a rempli'::text,'est bondé'::text,'Ce matin, le couloir du métro était bondé de navetteurs d''un mur à l''autre ! Chaos total !'::text),
(368756,40973,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah metro koridoru duvardan duvara yolcularla ...! Tam bir kaos!'::text,'doluydu'::text,'doldurdu'::text,'dolu'::text,'Bu sabah metro koridoru duvardan duvara yolcularla doluydu! Tam bir kaos!'::text),
(368757,40973,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel a metró folyosója fáltól falig ... ingázókkal! Totális káosz!'::text,'tele volt'::text,'megtöltötte'::text,'tele van'::text,'Ma reggel a metró folyosója fáltól falig tele volt ingázókkal! Totális káosz!'::text),
(368760,40974,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, die U-Bahn ... genau pünktlich, hat er mir erzählt, und er sah trotzdem total geschockt aus.'::text,'kam'::text,'war angekommen'::text,'ankommend'::text,'Rate mal, die U-Bahn kam genau pünktlich, hat er mir erzählt, und er sah trotzdem total geschockt aus.'::text),
(368764,40974,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що, метро ... точно вчасно, він мені сказав, і все одно виглядав таким шокованим.'::text,'прибуло'::text,'прибуло'::text,'прибуваючи'::text,'Вгадай що, метро прибуло точно вчасно, він мені сказав, і все одно виглядав таким шокованим.'::text),
(368763,40974,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? El metro ... justo a tiempo, me dijo, y aun así parecía súper sorprendido.'::text,'llegó'::text,'había llegado'::text,'llegando'::text,'¿Sabes qué? El metro llegó justo a tiempo, me dijo, y aun así parecía súper sorprendido.'::text),
(368762,40974,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, le métro ... pile à l''heure, il m''a dit, et il avait quand même l''air choqué.'::text,'est arrivé'::text,'était arrivé'::text,'arrivant'::text,'Devine quoi, le métro est arrivé pile à l''heure, il m''a dit, et il avait quand même l''air choqué.'::text),
(368765,40974,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et, metro tam zamanında ..., dedi bana, yine de çok şaşkın görünüyordu.'::text,'geldi'::text,'gelmişti'::text,'gelerek'::text,'Tahmin et, metro tam zamanında geldi, dedi bana, yine de çok şaşkın görünüyordu.'::text),
(368766,40974,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, a metró pontosan időben ..., mondta nekem, és mégis annyira sokkoltnak tűnt.'::text,'érkezett'::text,'érkezett meg'::text,'érkezve'::text,'Képzeld, a metró pontosan időben érkezett, mondta nekem, és mégis annyira sokkoltnak tűnt.'::text),
(368769,40975,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, er hat mir gesagt, diese U-Bahn ... die vollste der Stadt sein. Schau dir diesen Gang an!'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Hör mal, er hat mir gesagt, diese U-Bahn muss die vollste der Stadt sein. Schau dir diesen Gang an!'::text),
(368773,40975,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що це метро ... бути найзавантаженішим у місті. Глянь на той коридор!'::text,'мусить'::text,'може'::text,'не може'::text,'Слухай, він сказав мені, що це метро мусить бути найзавантаженішим у місті. Глянь на той коридор!'::text),
(368772,40975,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que este metro ... ser el más concurrido de la ciudad. ¡Mira ese pasillo!'::text,'debe de'::text,'podría'::text,'no puede'::text,'Oye, me dijo que este metro debe de ser el más concurrido de la ciudad. ¡Mira ese pasillo!'::text),
(368771,40975,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que ce métro ... être le plus fréquenté de la ville. Regarde ce couloir !'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Écoute, il m''a dit que ce métro doit être le plus fréquenté de la ville. Regarde ce couloir !'::text),
(368774,40975,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana bu metronun şehrin en kalabalığı ... söyledi. Şu koridora bak!'::text,'olması gerektiğini'::text,'olabileceğini'::text,'olamayacağını'::text,'Dinle, bana bu metronun şehrin en kalabalığı olması gerektiğini söyledi. Şu koridora bak!'::text),
(368775,40975,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy ez a metró ... a legforgalmasabb a városban. Nézd azt a folyosót!'::text,'biztosan'::text,'talán'::text,'nem lehet'::text,'Figyelj, azt mondta, hogy ez a metró biztosan a legforgalmasabb a városban. Nézd azt a folyosót!'::text),
(368787,40977,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er hat gesagt, er ... nie wieder um 8 Uhr morgens U-Bahn fahren, kein Witz.'::text,'würde'::text,'wird'::text,'will'::text,'Alter, er hat gesagt, er würde nie wieder um 8 Uhr morgens U-Bahn fahren, kein Witz.'::text),
(368791,40977,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він сказав, що більше ніколи ... на метро о восьмій ранку, без жартів.'::text,'не поїде'::text,'не поїде'::text,'не хоче їхати'::text,'Чувак, він сказав, що більше ніколи не поїде на метро о восьмій ранку, без жартів.'::text),
(368790,40977,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, dijo que nunca más ... el metro a las 8 de la mañana, en serio.'::text,'tomaría'::text,'tomará'::text,'quiere tomar'::text,'Tío, dijo que nunca más tomaría el metro a las 8 de la mañana, en serio.'::text),
(368789,40977,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il a dit qu''il ne ... plus jamais le métro à 8 h du matin, sans mentir.'::text,'prendrait'::text,'prendra'::text,'veut prendre'::text,'Mec, il a dit qu''il ne prendrait plus jamais le métro à 8 h du matin, sans mentir.'::text),
(368792,40977,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir daha asla sabah 8''de metroya ... söyledi, yemin ederim.'::text,'binmeyeceğini'::text,'binmeyeceğini'::text,'binmek istemediğini'::text,'Kanka, bir daha asla sabah 8''de metroya binmeyeceğini söyledi, yemin ederim.'::text),
(368793,40977,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, azt mondta, hogy soha többé nem ... metróval reggel 8-kor, komolyan.'::text,'menne'::text,'megy'::text,'akar menni'::text,'Haver, azt mondta, hogy soha többé nem menne metróval reggel 8-kor, komolyan.'::text),
(368796,40978,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Laut dem Bericht der Stadt ... die U-Bahn vor 2019 halb leer.'::text,'war'::text,'war'::text,'war gewohnt zu sein'::text,'Laut dem Bericht der Stadt war die U-Bahn vor 2019 halb leer.'::text),
(368800,40978,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'За звітом міста, до 2019 року метро ... напівпорожнім.'::text,'бувало'::text,'бувало'::text,'звикло бути'::text,'За звітом міста, до 2019 року метро бувало напівпорожнім.'::text),
(368799,40978,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según el informe municipal, el metro ... estar medio vacío antes de 2019.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Según el informe municipal, el metro solía estar medio vacío antes de 2019.'::text),
(368798,40978,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''après le rapport de la ville, le métro ... à moitié vide avant 2019.'::text,'était'::text,'était'::text,'avait l''habitude d''être'::text,'D''après le rapport de la ville, le métro était à moitié vide avant 2019.'::text),
(368801,40978,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belediye raporuna göre metro 2019''dan önce yarı boş ...'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Belediye raporuna göre metro 2019''dan önce yarı boş olurdu.'::text),
(368802,40978,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A városi jelentés szerint a metró 2019 előtt félig üres ...'::text,'volt'::text,'volt'::text,'volt hozzászokva'::text,'A városi jelentés szerint a metró 2019 előtt félig üres volt.'::text),
(368805,40979,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er beschloss, statt des vollen Busses die U-Bahn ...'::text,'zu nehmen'::text,'nehmend'::text,'nehmen'::text,'Er beschloss, statt des vollen Busses die U-Bahn zu nehmen.'::text),
(368809,40979,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він вирішив ... на метро замість переповненого автобуса.'::text,'поїхати'::text,'їдучи'::text,'поїхати'::text,'Він вирішив поїхати на метро замість переповненого автобуса.'::text),
(368808,40979,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Decidió ... el metro en lugar del autobús abarrotado.'::text,'tomar'::text,'tomando'::text,'toma'::text,'Decidió tomar el metro en lugar del autobús abarrotado.'::text),
(368807,40979,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a décidé ... le métro au lieu du bus bondé.'::text,'de prendre'::text,'prenant'::text,'prendre'::text,'Il a décidé de prendre le métro au lieu du bus bondé.'::text),
(368810,40979,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık otobüs yerine metroya ... karar verdi.'::text,'binmeye'::text,'binmeyi'::text,'binmek'::text,'Kalabalık otobüs yerine metroya binmeye karar verdi.'::text),
(368811,40979,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy döntött, hogy a zsúfolt busz helyett ... a metrót.'::text,'választja'::text,'választás'::text,'választ'::text,'Úgy döntött, hogy a zsúfolt busz helyett választja a metrót.'::text),
(368814,40980,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er fährt jeden Morgen mit ... durch die Stadt.'::text,'der U-Bahn'::text,'der U-Bahn'::text,'einer U-Bahn'::text,'Er fährt jeden Morgen mit der U-Bahn durch die Stadt.'::text),
(368818,40980,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щоранку він їздить містом на ...'::text,'метро'::text,'метро'::text,'метро'::text,'Щоранку він їздить містом на метро.'::text),
(368817,40980,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada mañana cruza la ciudad en ...'::text,'metro'::text,'el metro'::text,'un metro'::text,'Cada mañana cruza la ciudad en metro.'::text),
(368816,40980,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque matin, il traverse la ville en ...'::text,'métro'::text,'le métro'::text,'un métro'::text,'Chaque matin, il traverse la ville en métro.'::text),
