(368820,40980,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden reggel ... szeli át a várost.'::text,'metróval'::text,'a metróval'::text,'egy metróval'::text,'Minden reggel metróval szeli át a várost.'::text),
(368823,40981,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... er sich durch den vollen U-Bahn-Gang.'::text,'drängt'::text,'drängt'::text,'hat gedrängt'::text,'Gerade drängt er sich durch den vollen U-Bahn-Gang.'::text),
(368827,40981,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз він ... переповненим коридором метро.'::text,'проштовхується'::text,'проштовхується'::text,'проштовхнувся'::text,'Просто зараз він проштовхується переповненим коридором метро.'::text),
(368826,40981,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ... por el pasillo abarrotado del metro.'::text,'se está abriendo paso'::text,'se abre paso'::text,'se ha abierto paso'::text,'Ahora mismo se está abriendo paso por el pasillo abarrotado del metro.'::text),
(368825,40981,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, il ... dans le couloir bondé du métro.'::text,'est en train de se frayer un chemin'::text,'se fraie un chemin'::text,'s''est frayé un chemin'::text,'En ce moment, il est en train de se frayer un chemin dans le couloir bondé du métro.'::text),
(368828,40981,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda kalabalık metro koridorunda ...'::text,'yol açarak ilerliyor'::text,'yol açarak ilerler'::text,'yol açarak ilerledi'::text,'Şu anda kalabalık metro koridorunda yol açarak ilerliyor.'::text),
(368829,40981,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most épp ... a zsúfolt metrófolyosón.'::text,'furakszik át'::text,'furakszik át'::text,'átfurakodott'::text,'Most épp furakszik át a zsúfolt metrófolyosón.'::text),
(329466,36608,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die zwei ... ihr gerade die Straße entlang, als die Menge anfing, 134 zu rufen, kein Witz.'::text,'halfen'::text,'halfen'::text,'haben geholfen'::text,'Bro, die zwei halfen ihr gerade die Straße entlang, als die Menge anfing, 134 zu rufen, kein Witz.'::text),
(329470,36608,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ті двоє ... їй іти дорогою, коли натовп почав скандувати «134», без жартів.'::text,'допомагали'::text,'допомогли'::text,'допомогли'::text,'Бро, ті двоє допомагали їй іти дорогою, коли натовп почав скандувати «134», без жартів.'::text),
(329469,36608,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, esos dos la ... calle abajo cuando el público empezó a corear 134, en serio.'::text,'estaban ayudando'::text,'ayudaron'::text,'han ayudado'::text,'Bro, esos dos la estaban ayudando calle abajo cuando el público empezó a corear 134, en serio.'::text),
(329468,36608,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ces deux-là ... à avancer sur la route quand la foule a commencé à scander 134, sans mentir.'::text,'l''aidaient'::text,'l''ont aidée'::text,'l''ont aidée'::text,'Frérot, ces deux-là l''aidaient à avancer sur la route quand la foule a commencé à scander 134, sans mentir.'::text),
(329471,36608,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kalabalık 134 diye tezahürat yapmaya başladığında o ikisi ona yolda ..., yemin ederim.'::text,'yardım ediyordu'::text,'yardım etti'::text,'yardım etmiş'::text,'Kanka, kalabalık 134 diye tezahürat yapmaya başladığında o ikisi ona yolda yardım ediyordu, yemin ederim.'::text),
(329472,36608,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azok ketten épp ... neki az úton, amikor a tömeg elkezdte skandálni, hogy 134, komolyan.'::text,'segítettek'::text,'segítettek'::text,'segítettek'::text,'Tesó, azok ketten épp segítettek neki az úton, amikor a tömeg elkezdte skandálni, hogy 134, komolyan.'::text),
