(329479,36609,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оновлення статусу: двоє помічників ... бігунам на фініші з 9:00.'::text,'допомагають'::text,'допомагають'::text,'допомагають'::text,'Оновлення статусу: двоє помічників допомагають бігунам на фініші з 9:00.'::text),
