(329480,36609,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Durum güncellemesi: iki yardımcı saat 9''dan beri bitiş çizgisinde koşuculara ...'::text,'yardım ediyor'::text,'yardım ediyor'::text,'yardım eder'::text,'Durum güncellemesi: iki yardımcı saat 9''dan beri bitiş çizgisinde koşuculara yardım ediyor.'::text),
(329481,36609,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Státuszfrissítés: a két segítő reggel 9 óta ... a futóknak a célban.'::text,'segít'::text,'segít'::text,'segít'::text,'Státuszfrissítés: a két segítő reggel 9 óta segít a futóknak a célban.'::text),
(329493,36611,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden Helfer ... heute bisher etwa drei erschöpften Läufern über die Linie geholfen.'::text,'haben'::text,'helfen'::text,'halfen'::text,'Die beiden Helfer haben heute bisher etwa drei erschöpften Läufern über die Linie geholfen.'::text),
(329497,36611,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє помічників сьогодні вже ... приблизно трьом виснаженим бігунам перетнути лінію.'::text,'допомогли'::text,'допомагали'::text,'допомогли'::text,'Двоє помічників сьогодні вже допомогли приблизно трьом виснаженим бігунам перетнути лінію.'::text),
(329496,36611,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos voluntarios ... hoy a aproximadamente tres corredores exhaustos a cruzar la línea.'::text,'han ayudado'::text,'han estado ayudando'::text,'ayudaron'::text,'Los dos voluntarios han ayudado hoy a aproximadamente tres corredores exhaustos a cruzar la línea.'::text),
(329495,36611,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux bénévoles ... jusqu''ici environ trois coureurs épuisés à franchir la ligne aujourd''hui.'::text,'ont aidé'::text,'aident depuis le début'::text,'ont aidé'::text,'Les deux bénévoles ont aidé jusqu''ici environ trois coureurs épuisés à franchir la ligne aujourd''hui.'::text),
(329498,36611,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki yardımcı bugün şimdiye kadar yaklaşık üç bitkin koşucunun çizgiyi geçmesine ...'::text,'yardım etti'::text,'yardım ediyor'::text,'yardım etti'::text,'İki yardımcı bugün şimdiye kadar yaklaşık üç bitkin koşucunun çizgiyi geçmesine yardım etti.'::text),
(329499,36611,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két segítő ma eddig nagyjából három kimerült futónak ... átjutni a vonalon.'::text,'segített'::text,'segít'::text,'segített'::text,'A két segítő ma eddig nagyjából három kimerült futónak segített átjutni a vonalon.'::text),
(329502,36612,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis jemand die Katastrophe an der Absperrung bemerkte, ... ihr zwei Freunde schon geholfen!'::text,'hatten'::text,'haben'::text,'helfen'::text,'Bis jemand die Katastrophe an der Absperrung bemerkte, hatten ihr zwei Freunde schon geholfen!'::text),
(329506,36612,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки хтось помітив катастрофу біля огорожі, двоє друзів уже ... їй!'::text,'допомогли'::text,'допомогли'::text,'допомагають'::text,'Поки хтось помітив катастрофу біля огорожі, двоє друзів уже допомогли їй!'::text),
(329505,36612,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando alguien vio el desastre junto a la valla, dos amigos ya la ...!'::text,'habían ayudado'::text,'han ayudado'::text,'ayudan'::text,'¡Para cuando alguien vio el desastre junto a la valla, dos amigos ya la habían ayudado!'::text),
(329504,36612,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que quelqu''un voie la catastrophe à la barrière, deux amis ... !'::text,'l''avaient aidée'::text,'l''ont aidée'::text,'l''aident'::text,'Le temps que quelqu''un voie la catastrophe à la barrière, deux amis l''avaient aidée !'::text),
(329507,36612,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri bariyerdeki felaketi görene kadar iki arkadaş ona çoktan ...!'::text,'yardım etmişti'::text,'yardım etti'::text,'yardım ediyor'::text,'Biri bariyerdeki felaketi görene kadar iki arkadaş ona çoktan yardım etmişti!'::text),
(329508,36612,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire bárki észrevette a katasztrófát a korlátnál, két barát már ... neki!'::text,'segített'::text,'segített'::text,'segít'::text,'Mire bárki észrevette a katasztrófát a korlátnál, két barát már segített neki!'::text),
(329511,36613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächstes Jahr um diese Zeit ... ihr dieselben zwei Freunde wieder im Ziel.'::text,'helfen'::text,'werden helfen'::text,'helfen'::text,'Nächstes Jahr um diese Zeit helfen ihr dieselben zwei Freunde wieder im Ziel.'::text),
(329515,36613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного року в цей час ті самі двоє друзів знову ... їй на фініші.'::text,'допомагатимуть'::text,'допоможуть'::text,'допомагають'::text,'Наступного року в цей час ті самі двоє друзів знову допомагатимуть їй на фініші.'::text),
(329514,36613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El año que viene a esta hora, los mismos dos amigos la ... otra vez en la meta.'::text,'estarán ayudando'::text,'ayudarán'::text,'ayudan'::text,'El año que viene a esta hora, los mismos dos amigos la estarán ayudando otra vez en la meta.'::text),
(329513,36613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''année prochaine à la même heure, les deux mêmes amis ... encore à l''arrivée.'::text,'seront en train de l''aider'::text,'l''aideront'::text,'l''aident'::text,'L''année prochaine à la même heure, les deux mêmes amis seront en train de l''aider encore à l''arrivée.'::text),
(329516,36613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek yıl bu zamanlar aynı iki arkadaş bitiş çizgisinde ona yine ...'::text,'yardım ediyor olacak'::text,'yardım edecek'::text,'yardım ediyor'::text,'Gelecek yıl bu zamanlar aynı iki arkadaş bitiş çizgisinde ona yine yardım ediyor olacak.'::text),
(329517,36613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövőre ilyenkor ugyanaz a két barát megint ... neki a célban.'::text,'segíteni fog'::text,'segít majd'::text,'segít'::text,'Jövőre ilyenkor ugyanaz a két barát megint segíteni fog neki a célban.'::text),
(329520,36614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'„Ich hab dich“, sagt er und verspricht, dass er ihr den ganzen Weg bis zur Linie ...'::text,'helfen wird'::text,'helfen wird'::text,'hilft'::text,'„Ich hab dich“, sagt er und verspricht, dass er ihr den ganzen Weg bis zur Linie helfen wird.'::text),
(329524,36614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'«Я тебе тримаю», — каже він і обіцяє, що ... їй аж до самої лінії.'::text,'допоможе'::text,'допомагатиме'::text,'допомагає'::text,'«Я тебе тримаю», — каже він і обіцяє, що допоможе їй аж до самої лінії.'::text),
(329523,36614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'«Te tengo», dice él, y promete que la ... hasta la línea.'::text,'ayudará'::text,'estará ayudando'::text,'está ayudando'::text,'«Te tengo», dice él, y promete que la ayudará hasta la línea.'::text),
(329522,36614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'« Je te tiens », dit-il, et il promet qu''il ... tout le long jusqu''à la ligne.'::text,'l''aidera'::text,'sera en train de l''aider'::text,'l''aide'::text,'« Je te tiens », dit-il, et il promet qu''il l''aidera tout le long jusqu''à la ligne.'::text),
(329525,36614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'“Seni tuttum,” diyor ve ona çizgiye kadar ... söz veriyor.'::text,'yardım edeceğine'::text,'yardım ediyor olacağına'::text,'yardım ettiğine'::text,'“Seni tuttum,” diyor ve ona çizgiye kadar yardım edeceğine söz veriyor.'::text),
(329526,36614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'„Megvagy”, mondja, és megígéri, hogy egészen a vonalig ... neki.'::text,'segíteni fog'::text,'segít majd'::text,'segít'::text,'„Megvagy”, mondja, és megígéri, hogy egészen a vonalig segíteni fog neki.'::text),
(329529,36615,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Läufer kurz vor dem Ziel zusammenbricht, ... ihm die Leute drumherum meistens.'::text,'helfen'::text,'halfen'::text,'werden helfen'::text,'Wenn ein Läufer kurz vor dem Ziel zusammenbricht, helfen ihm die Leute drumherum meistens.'::text),
(329533,36615,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли бігун падає біля фінішу, люди навколо зазвичай ... йому.'::text,'допомагають'::text,'допомогли'::text,'допоможуть'::text,'Коли бігун падає біля фінішу, люди навколо зазвичай допомагають йому.'::text),
(329532,36615,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un corredor se desploma cerca de la meta, la gente de alrededor normalmente lo ...'::text,'ayuda'::text,'ayudó'::text,'ayudará'::text,'Si un corredor se desploma cerca de la meta, la gente de alrededor normalmente lo ayuda.'::text),
(329531,36615,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un coureur s''effondre près de l''arrivée, les gens autour ... en général.'::text,'l''aident'::text,'l''ont aidé'::text,'l''aideront'::text,'Si un coureur s''effondre près de l''arrivée, les gens autour l''aident en général.'::text),
(329534,36615,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir koşucu bitiş çizgisine yakın yığılırsa etraftaki insanlar genelde ona ...'::text,'yardım eder'::text,'yardım etti'::text,'yardım edecek'::text,'Bir koşucu bitiş çizgisine yakın yığılırsa etraftaki insanlar genelde ona yardım eder.'::text),
(329535,36615,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy futó összeesik a cél közelében, a körülötte lévők általában ... neki.'::text,'segítenek'::text,'segítettek'::text,'segíteni fognak'::text,'Ha egy futó összeesik a cél közelében, a körülötte lévők általában segítenek neki.'::text),
(329538,36616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihr niemand ..., würde sie das Rennen natürlich trotzdem gewinnen. Perfekter Plan.'::text,'helfen würde'::text,'hilft'::text,'geholfen hätte'::text,'Wenn ihr niemand helfen würde, würde sie das Rennen natürlich trotzdem gewinnen. Perfekter Plan.'::text),
(329542,36616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби їй ніхто не ..., вона, очевидно, все одно виграла б забіг. Бездоганний план.'::text,'допомагав'::text,'допомагає'::text,'допоміг'::text,'Якби їй ніхто не допомагав, вона, очевидно, все одно виграла б забіг. Бездоганний план.'::text),
(329541,36616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si nadie la ..., obviamente ganaría la carrera igualmente. Plan perfecto.'::text,'ayudara'::text,'ayuda'::text,'hubiera ayudado'::text,'Si nadie la ayudara, obviamente ganaría la carrera igualmente. Plan perfecto.'::text),
(329540,36616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si personne ne ..., elle gagnerait évidemment quand même la course. Plan parfait.'::text,'l''aidait'::text,'l''aide'::text,'l''avait aidée'::text,'Si personne ne l''aidait, elle gagnerait évidemment quand même la course. Plan parfait.'::text),
(329543,36616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ona kimse yardım ..., yarışı yine de kazanırdı tabii. Kusursuz plan.'::text,'etmese'::text,'etmiyorsa'::text,'etmeseydi'::text,'Ona kimse yardım etmese, yarışı yine de kazanırdı tabii. Kusursuz plan.'::text),
(329544,36616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha senki nem ... neki, nyilván akkor is megnyerné a versenyt. Hibátlan terv.'::text,'segítene'::text,'segít'::text,'segített volna'::text,'Ha senki nem segítene neki, nyilván akkor is megnyerné a versenyt. Hibátlan terv.'::text),
(329547,36617,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... von zwei Freunden über die Linie gestützt. Ein echtes Solo-Finish, ganz klar.'::text,'wurde'::text,'hat'::text,'wird'::text,'Sie wurde von zwei Freunden über die Linie gestützt. Ein echtes Solo-Finish, ganz klar.'::text),
(329551,36617,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її ... через лінію двоє друзів. Дуже сольний фініш, очевидно.'::text,'провели'::text,'провела'::text,'проводять'::text,'Її провели через лінію двоє друзів. Дуже сольний фініш, очевидно.'::text),
(329550,36617,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a cruzar la línea por dos amigos. Un final muy en solitario, claramente.'::text,'Fue ayudada'::text,'Ayudó'::text,'Es ayudada'::text,'Fue ayudada a cruzar la línea por dos amigos. Un final muy en solitario, claramente.'::text),
(329549,36617,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... à franchir la ligne par deux amis. Une arrivée très en solo, clairement.'::text,'a été aidée'::text,'a aidé'::text,'est aidée'::text,'Elle a été aidée à franchir la ligne par deux amis. Une arrivée très en solo, clairement.'::text),
(329552,36617,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki arkadaşı tarafından bitiş çizgisinden ..., belli ki çok solo bir finiş.'::text,'geçirildi'::text,'geçirdi'::text,'geçiriliyor'::text,'İki arkadaşı tarafından bitiş çizgisinden geçirildi, belli ki çok solo bir finiş.'::text),
(329553,36617,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két barátja ... át a vonalon. Nagyon szóló befutó, nyilván.'::text,'segítette'::text,'segített'::text,'segíti'::text,'Két barátja segítette át a vonalon. Nagyon szóló befutó, nyilván.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
